function Icon({name,size=18,color="currentColor",style}){
  const p=PATHS[name];if(!p)return null;
  return<svg width={size} height={size} viewBox="0 0 24 24" fill={color} style={style}><path d={p}/></svg>;
}
function Spinner({size=24}){return<div className="spin" style={{width:size,height:size,border:`2px solid ${C.border}`,borderTop:`2px solid ${C.accent}`,borderRadius:"50%"}}/>;}
function Badge({children,color=C.accent}){return<span style={{display:"inline-block",padding:"2px 8px",borderRadius:20,fontSize:11,fontWeight:600,color,background:color+"22",border:`1px solid ${color}33`}}>{children}</span>;}
function StatCard({icon,value,label,sub,color=C.accent,valueColor,small}){
  const valCol=valueColor||color;
  return(
    <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:12,padding:small?"12px 14px":"16px 18px",display:"flex",flexDirection:"column",gap:5,position:"relative",overflow:"hidden",boxShadow:`0 0 24px ${color}0d`}}>
      <div style={{position:"absolute",top:-8,right:-8,width:56,height:56,background:color+"15",borderRadius:"50%"}}/>
      <div style={{display:"flex",alignItems:"center",gap:7}}>
        <div style={{background:color+"20",borderRadius:7,padding:5,display:"flex"}}><Icon name={icon} size={14} color={color}/></div>
        <span style={{fontSize:12,color:C.textSub,fontWeight:600}}>{label}</span>
      </div>
      <div style={{fontFamily:"Inter,sans-serif",fontSize:small?26:34,fontWeight:800,color:valCol,lineHeight:1,letterSpacing:"-0.02em"}}>{value}</div>
      {sub&&<div style={{fontSize:11,color:C.textMuted}}>{sub}</div>}
    </div>
  );
}
function Card({children,style,title,action}){
  return(
    <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:12,overflow:"hidden",...style}}>
      {title&&<div style={{padding:"12px 16px",borderBottom:`1px solid ${C.border}`,display:"flex",alignItems:"center",justifyContent:"space-between"}}>
        <span style={{fontFamily:"Inter",fontWeight:700,fontSize:13,color:C.text}}>{title}</span>
        {action}
      </div>}
      {children}
    </div>
  );
}
function Table({cols,rows,maxH=380,emptyMsg="Sin datos"}){
  const ROW_H=36;
  const[scrollTop,setScrollTop]=useState(0);
  const[sortKey,setSortKey]=useState(null);
  const[sortDir,setSortDir]=useState("asc");
  const onScroll=useCallback(e=>setScrollTop(e.target.scrollTop),[]);

  const handleSort=useCallback((key)=>{
    if(sortKey===key)setSortDir(d=>d==="asc"?"desc":"asc");
    else{setSortKey(key);setSortDir("asc");}
  },[sortKey]);

  const sortedRows=useMemo(()=>{
    if(!sortKey)return rows;
    return [...rows].sort((a,b)=>{
      const av=a[sortKey],bv=b[sortKey];
      if(av==null)return 1;if(bv==null)return -1;
      const cmp=typeof av==="number"?av-bv:String(av).localeCompare(String(bv));
      return sortDir==="asc"?cmp:-cmp;
    });
  },[rows,sortKey,sortDir]);

  // Todos los hooks antes de cualquier return condicional
  const bufferRows=8;
  const visibleCount=Math.ceil(maxH/ROW_H);
  const startIdx=Math.max(0,Math.floor(scrollTop/ROW_H)-bufferRows);
  const endIdx=Math.min(sortedRows.length,startIdx+visibleCount+bufferRows*2);
  const visibleRows=sortedRows.slice(startIdx,endIdx);
  const offsetY=startIdx*ROW_H;

  if(rows.length===0)return(
    <div style={{padding:"28px",textAlign:"center",color:C.textMuted,fontSize:12}}>{emptyMsg}</div>
  );
  return(
    <div onScroll={onScroll} style={{overflowX:"auto",overflowY:"auto",maxHeight:maxH}}>
      <table style={{width:"100%",borderCollapse:"collapse",fontSize:12}}>
        <thead><tr>{cols.map((c,i)=>(
          <th key={i} onClick={()=>c.key&&handleSort(c.key)}
            style={{padding:"9px 12px",textAlign:"left",position:"sticky",top:0,zIndex:1,background:C.surface,color:sortKey===c.key?C.accent:C.textSub,fontWeight:600,fontSize:10,letterSpacing:".06em",textTransform:"uppercase",borderBottom:`1px solid ${C.border}`,whiteSpace:"nowrap",cursor:c.key?"pointer":"default",userSelect:"none"}}>
            {c.label}{sortKey===c.key?(sortDir==="asc"?" ↑":" ↓"):""}
          </th>
        ))}</tr></thead>
        <tbody>
          {offsetY>0&&<tr style={{height:offsetY}}><td colSpan={cols.length} style={{padding:0,border:"none"}}/></tr>}
          {visibleRows.map((r,i)=>{
            const absI=startIdx+i;
            const hasTooltip=true;
            return(
              <tr key={absI}
                style={{background:absI%2===0?"transparent":C.surface+"66",height:ROW_H,position:"relative",cursor:hasTooltip?"pointer":"default",transition:"background .1s"}}
                onMouseEnter={e=>{
                  e.currentTarget.dataset.bg=absI%2===0?"transparent":C.surface+"66";
                  e.currentTarget.style.background=C.accent+"22";
                  if(!hasTooltip)return;
                  const tip=document.createElement("div");
                  tip.id="row-tip";
                  tip.style.cssText=`position:fixed;z-index:9999;background:${C.surface};border:1px solid ${C.border};border-radius:10px;padding:12px 16px;font-size:12px;font-family:Inter,sans-serif;max-width:320px;box-shadow:0 8px 32px rgba(0,0,0,.5);pointer-events:none;visibility:hidden`;
                  tip.innerHTML="<div><span style=\"font-size:10px;color:#888;text-transform:uppercase;letter-spacing:.06em\">Observaciones</span><div style=\"color:"+(r.observaciones?"#ccc":"#555")+";margin-top:3px;font-style:"+(r.observaciones?"normal":"italic")+"\">"+(r.observaciones||"Sin observaciones")+"</div></div>";
                  document.body.appendChild(tip);
                  const rect=e.currentTarget.getBoundingClientRect();
                  const tipW=tip.offsetWidth||320;
                  const tipH=tip.offsetHeight||60;
                  tip.style.left=Math.min(rect.right+8, window.innerWidth-tipW-8)+"px";
                  tip.style.top=Math.max(8, rect.bottom-tipH)+"px";
                  tip.style.visibility="visible";
                }}
                onMouseLeave={e=>{
                  e.currentTarget.style.background=e.currentTarget.dataset.bg||"transparent";
                  const t=document.getElementById("row-tip");if(t)t.remove();
                }}
              >
                {cols.map((c,j)=><td key={j} style={{padding:"8px 12px",borderBottom:`1px solid ${C.border}18`,color:C.text,whiteSpace:c.wrap?"normal":"nowrap",overflow:"hidden",maxWidth:c.wrap?undefined:300}}>{c.render?c.render(r[c.key],r):(r[c.key]??"—")}</td>)}
              </tr>
            );
          })}
          {endIdx<sortedRows.length&&<tr style={{height:(sortedRows.length-endIdx)*ROW_H}}><td colSpan={cols.length} style={{padding:0,border:"none"}}/></tr>}
        </tbody>
      </table>
    </div>
  );
}
function Sel({label,value,onChange,options}){
  // Si el valor actual no existe en las opciones, caer al default (primera opción)
  const safeValue=options.some(o=>o.value===value)?value:(options[0]?.value??value);
  return(
    <div style={{display:"flex",flexDirection:"column",gap:3}}>
      <label style={{fontSize:10,color:C.textMuted,fontWeight:600,letterSpacing:".06em",textTransform:"uppercase"}}>{label}</label>
      <select value={safeValue} onChange={e=>onChange(e.target.value)} style={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:7,color:C.text,padding:"7px 10px",fontSize:12,cursor:"pointer",outline:"none",minWidth:120}}>
        {options.map(o=><option key={o.value} value={o.value}>{o.label}</option>)}
      </select>
    </div>
  );
}
function DateIn({label,value,onChange,min,max,warn}){
  return(
    <div style={{display:"flex",flexDirection:"column",gap:3}}>
      <label style={{fontSize:10,color:warn?C.red:C.textMuted,fontWeight:600,letterSpacing:".06em",textTransform:"uppercase"}}>{label}{warn?` ⚠ ${warn}`:""}</label>
      <input type="date" value={value} min={min} max={max} onChange={e=>onChange(e.target.value)} style={{background:C.surface,border:`1px solid ${warn?C.red:C.border}`,borderRadius:7,color:C.text,padding:"7px 10px",fontSize:12,outline:"none"}}/>
    </div>
  );
}
function ChartTip({active,payload,label}){
  if(!active||!payload?.length)return null;
  return(
    <div style={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:8,padding:"9px 12px",fontSize:12}}>
      {label&&<div style={{color:C.textSub,marginBottom:4,fontWeight:600,fontSize:11}}>{label}</div>}
      {payload.map((p,i)=><div key={i} style={{color:p.color||C.accent,fontWeight:600}}>{p.name}: {fmtNum(p.value)}</div>)}
    </div>
  );
}
function TabBtn({active,onClick,children}){return<button onClick={onClick} style={{padding:"7px 14px",borderRadius:7,border:"none",cursor:"pointer",background:active?C.accent:C.surface,color:active?"#fff":C.textSub,fontFamily:"Inter",fontWeight:600,fontSize:12,transition:"all .2s"}}>{children}</button>;}
function SubTab({active,onClick,children}){return<button onClick={onClick} style={{padding:"7px 0",border:"none",background:"none",cursor:"pointer",color:active?C.accent:C.textSub,fontFamily:"Inter",fontWeight:600,fontSize:12,borderBottom:`2px solid ${active?C.accent:"transparent"}`,transition:"all .15s",marginRight:18}}>{children}</button>;}
function AlertBanner({type="warn",children}){
  const m={warn:[C.yellow,C.yellowDim],error:[C.red,C.redDim],success:[C.green,C.greenDim],info:[C.blue,C.blueDim]};
  const[col,bg]=m[type]||m.warn;
  return<div style={{display:"flex",alignItems:"flex-start",gap:8,padding:"10px 14px",background:bg,border:`1px solid ${col}44`,borderRadius:9,fontSize:12,color:C.text}}><Icon name="warn" size={14} color={col} style={{flexShrink:0,marginTop:1}}/><span>{children}</span></div>;
}

// ─── fetchAll ─────────────────────────────────────────────────────────────────
async function fetchAll(url){
  const res=await fetch(`${url}?action=all`);
  if(!res.ok)throw new Error(`HTTP ${res.status} desde el Apps Script`);
  const text=await res.text();
  let json;
  try{json=JSON.parse(text);}catch(e){throw new Error("El Apps Script devolvió HTML. Verificá que esté publicado como 'Cualquier persona'.");}
  if(!json.ok&&!json.sources)throw new Error(json.error?.message||"Respuesta inválida del Apps Script");
  return json;
}

// ─── ViewDashboard ────────────────────────────────────────────────────────────
function ViewDashboard({rop02All,rop05,control,dashSt,setDashSt}){
  const proyecto=dashSt?.proyecto??"todos";
  const modeD=dashSt?.modeD??"todo";
  const fechaD=dashSt?.fechaD??"";
  const fechaDD=dashSt?.fechaDD??"";
  const fechaDH=dashSt?.fechaDH??"";
  const setProyecto=v=>setDashSt(s=>({...s,proyecto:v}));
  const setModeD=v=>setDashSt(s=>({...s,modeD:v}));
  const setFechaD=v=>setDashSt(s=>({...s,fechaD:v}));
  const setFechaDD=v=>setDashSt(s=>({...s,fechaDD:v}));
  const setFechaDH=v=>setDashSt(s=>({...s,fechaDH:v}));

  // Proyectos disponibles
  const proyectos=useMemo(()=>uniq(rop02All.map(r=>r.proyecto)),[rop02All]);

  // Base filtrada por proyecto Y fecha
  const r02f=useMemo(()=>rop02All.filter(r=>{
    if(proyecto!=="todos"&&r.proyecto!==proyecto)return false;
    if(modeD==="dia"&&fechaD&&r.fecha!==fechaD)return false;
    if(modeD==="periodo"){if(fechaDD&&r.fecha<fechaDD)return false;if(fechaDH&&r.fecha>fechaDH)return false;}
    return true;
  }),[rop02All,proyecto,modeD,fechaD,fechaDD,fechaDH]);
  const r05f=useMemo(()=>rop05.filter(r=>{
    if(proyecto!=="todos"&&r.proyecto!==proyecto)return false;
    if(modeD==="dia"&&fechaD&&r.fecha!==fechaD)return false;
    if(modeD==="periodo"){if(fechaDD&&r.fecha<fechaDD)return false;if(fechaDH&&r.fecha>fechaDH)return false;}
    return true;
  }),[rop05,proyecto,modeD,fechaD,fechaDD,fechaDH]);

  // Excluye camionetas/camiones de TODOS los cálculos del dashboard
  const r02prod=useMemo(()=>r02f.filter(r=>!isExcluded(r.maquina)),[r02f]);
  const totalHoras=useMemo(()=>r02prod.reduce((s,r)=>s+r.horas,0),[r02prod]);
  const totalComb=useMemo(()=>r02prod.reduce((s,r)=>s+r.combustible,0),[r02prod]);
  const totalProd=useMemo(()=>r05f.reduce((s,r)=>s+r.cantidad,0),[r05f]);
  const totalEquipos=useMemo(()=>uniq(r02prod.filter(r=>r.estado==="TRABAJO").map(r=>r.maquina)).length,[r02prod]);

  // Top 10 equipos con info enriquecida para tooltip
  const topEquipos=useMemo(()=>{
    const m={};
    r02prod.forEach(r=>{
      if(!m[r.maquina])m[r.maquina]={horas:0,proyectos:new Set(),tipo:getMachineType(r.maquina)||""};
      m[r.maquina].horas+=r.horas;
      if(r.proyecto)m[r.maquina].proyectos.add(r.proyecto);
    });
    return Object.entries(m).sort((a,b)=>b[1].horas-a[1].horas).slice(0,10).map(([name,d])=>({
      name,horas:d.horas,
      proyectos:[...d.proyectos].join(" / "),
      tipo:d.tipo,
    }));
  },[r02prod]);

  // Top 8 operarios con info enriquecida para tooltip
  const topOps=useMemo(()=>{
    const m={};
    r02prod.filter(r=>r.operario).forEach(r=>{
      if(!m[r.operario])m[r.operario]={horas:0,proyectos:new Set(),maquinas:new Set()};
      m[r.operario].horas+=r.horas;
      if(r.proyecto)m[r.operario].proyectos.add(r.proyecto);
      if(r.maquina)m[r.operario].maquinas.add(r.maquina);
    });
    return Object.entries(m).sort((a,b)=>b[1].horas-a[1].horas).slice(0,8).map(([fullName,d])=>({
      name:fullName.split(" ")[0],
      fullName,
      horas:d.horas,
      proyectos:[...d.proyectos].join(" / "),
      maquinas:[...d.maquinas].sort().join(", "),
    }));
  },[r02prod]);

  // Producción por unidad (ROP05 no incluye camionetas/camiones por definición)
  const prodUnit=useMemo(()=>{const m={};r05f.forEach(r=>{if(r.unidad)m[r.unidad]=(m[r.unidad]||0)+r.cantidad;});return Object.entries(m).map(([name,value])=>({name,value}));},[r05f]);
  // Top 10 tareas más realizadas en ROP05
  const topTareas=useMemo(()=>{
    const m={};
    r05f.filter(r=>r.tarea&&r.tarea.trim()!=="").forEach(r=>{m[r.tarea]=(m[r.tarea]||0)+1;});
    const total=Object.values(m).reduce((s,v)=>s+v,0);
    return Object.entries(m).sort((a,b)=>b[1]-a[1]).slice(0,10)
      .map(([name,count])=>({name:name.length>34?name.slice(0,32)+"…":name,count,pct:total>0?Math.round((count/total)*100):0}));
  },[r05f]);
  // Horas por proyecto: solo equipos productivos
  const horasProy=useMemo(()=>{const m={};r02prod.forEach(r=>{const p=r.proyecto||"S/D";m[p]=(m[p]||0)+r.horas;});return Object.entries(m).map(([name,value])=>({name,value}));},[r02prod]);
  // KPIs nuevos: horas promedio/día, equipos en FS, días OD
  const horasPromDia=useMemo(()=>{
    const fechas=uniq(r02prod.map(r=>r.fecha));
    return fechas.length>0?Math.round(totalHoras/fechas.length):0;
  },[r02prod,totalHoras]);
  const equiposFS=useMemo(()=>uniq(r02f.filter(r=>r.estado==="FS"&&!isExcluded(r.maquina)).map(r=>r.maquina)).length,[r02f]);
  const diasOperativos=useMemo(()=>uniq(r02prod.filter(r=>r.estado==="TRABAJO").map(r=>r.fecha)).length,[r02prod]);
  const diasOD=useMemo(()=>uniq(r02f.filter(r=>r.estado==="OD"&&!isExcluded(r.maquina)).map(r=>r.fecha)).length,[r02f]);
  const sem=semaforo(control.consistencia);

  // Tooltips custom
  const TooltipEquipo=({active,payload})=>{
    if(!active||!payload?.length)return null;
    const d=payload[0].payload;
    return(
      <div style={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:10,padding:"10px 14px",fontSize:12,minWidth:180,boxShadow:"0 4px 20px rgba(0,0,0,.4)"}}>
        <div style={{fontFamily:"Inter",fontWeight:800,fontSize:14,color:C.accent,marginBottom:6}}>{d.name}</div>
        {d.tipo&&<div style={{color:C.textSub,fontSize:11,marginBottom:4}}>{d.tipo}</div>}
        <div style={{display:"flex",justifyContent:"space-between",gap:16,marginBottom:4}}>
          <span style={{color:C.textMuted,fontSize:11}}>Horas totales</span>
          <span style={{color:C.text,fontWeight:700}}>{fmtNum(d.horas)}</span>
        </div>
        {d.proyectos&&<div style={{display:"flex",justifyContent:"space-between",gap:16}}>
          <span style={{color:C.textMuted,fontSize:11}}>Proyecto</span>
          <span style={{color:C.accent,fontWeight:600,fontSize:11}}>{d.proyectos}</span>
        </div>}
      </div>
    );
  };

  const TooltipOperario=({active,payload})=>{
    if(!active||!payload?.length)return null;
    const d=payload[0].payload;
    return(
      <div style={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:10,padding:"10px 14px",fontSize:12,minWidth:200,boxShadow:"0 4px 20px rgba(0,0,0,.4)"}}>
        <div style={{fontFamily:"Inter",fontWeight:800,fontSize:14,color:C.purple,marginBottom:6}}>{d.fullName||d.name}</div>
        <div style={{display:"flex",justifyContent:"space-between",gap:16,marginBottom:4}}>
          <span style={{color:C.textMuted,fontSize:11}}>Horas totales</span>
          <span style={{color:C.text,fontWeight:700}}>{fmtNum(d.horas)}</span>
        </div>
        {d.proyectos&&<div style={{display:"flex",justifyContent:"space-between",gap:16,marginBottom:4}}>
          <span style={{color:C.textMuted,fontSize:11}}>Proyecto</span>
          <span style={{color:C.accent,fontWeight:600,fontSize:11}}>{d.proyectos}</span>
        </div>}
        {d.maquinas&&<div style={{display:"flex",flexDirection:"column",gap:2,marginTop:4,paddingTop:4,borderTop:`1px solid ${C.border}`}}>
          <span style={{color:C.textMuted,fontSize:10,textTransform:"uppercase",letterSpacing:".06em"}}>Máquinas operadas</span>
          <span style={{color:C.textSub,fontSize:10,lineHeight:1.5}}>{d.maquinas}</span>
        </div>}
      </div>
    );
  };

  return(
    <div className="fade-in" style={{display:"flex",flexDirection:"column",gap:16}}>
      {/* Filtros de proyecto + fecha */}
      <Card>
        <div style={{padding:"10px 14px",display:"flex",alignItems:"center",gap:14,flexWrap:"wrap"}}>
          <Icon name="filter" size={14} color={C.textSub}/>
          <div style={{display:"flex",gap:7}}>
            <TabBtn active={modeD==="todo"} onClick={()=>setModeD("todo")}>Todo</TabBtn>
            <TabBtn active={modeD==="dia"} onClick={()=>setModeD("dia")}>Por día</TabBtn>
            <TabBtn active={modeD==="periodo"} onClick={()=>setModeD("periodo")}>Por período</TabBtn>
          </div>
          {modeD==="dia"&&<DateIn label="Fecha" value={fechaD} onChange={setFechaD}/>}
          {modeD==="periodo"&&<><DateIn label="Desde" value={fechaDD} onChange={setFechaDD}/><DateIn label="Hasta" value={fechaDH} onChange={setFechaDH}/></>}
          <div style={{display:"flex",gap:7,marginLeft:8}}>
            {[{value:"todos",label:"Todos"},...proyectos.map(p=>({value:p,label:p}))].map(opt=>(
              <button key={opt.value} onClick={()=>setProyecto(opt.value)} style={{padding:"6px 14px",borderRadius:7,border:`1px solid ${proyecto===opt.value?C.accent:C.border}`,background:proyecto===opt.value?C.accentDim:"none",color:proyecto===opt.value?C.accent:C.textSub,fontFamily:"Inter",fontWeight:600,fontSize:12,cursor:"pointer",transition:"all .15s"}}>
                {opt.label}
              </button>
            ))}
          </div>
          <button onClick={()=>{setProyecto("todos");setModeD("todo");setFechaD("");setFechaDD("");setFechaDH("");}} style={{marginLeft:"auto",display:"flex",alignItems:"center",gap:5,padding:"6px 12px",borderRadius:7,border:`1px solid ${C.red}44`,background:C.redDim,color:C.red,cursor:"pointer",fontSize:11,fontWeight:600,fontFamily:"Inter",opacity:(proyecto!=="todos"||modeD!=="todo"||fechaD||fechaDD||fechaDH)?1:0.3,pointerEvents:(proyecto!=="todos"||modeD!=="todo"||fechaD||fechaDD||fechaDH)?"auto":"none"}}><Icon name="close" size={11} color={C.red}/>Limpiar filtros</button>
        </div>
      </Card>

      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(145px,1fr))",gap:12}}>
        <StatCard icon="hours" label="Horas Totales" value={fmtNum(totalHoras)} sub="equipos productivos" color={C.yellow}/>
        <StatCard icon="fuel" label="Combustible" value={fmtNum(totalComb)} sub="litros" color={C.teal}/>
        <StatCard icon="equip" label="Equipos" value={totalEquipos} sub="activos" color={C.purple}/>
        <StatCard icon="consist" label="Días Operativos" value={diasOperativos} sub="con registro productivo" color={C.blue}/>
        <StatCard icon="hours" label="Hs Prom./Día" value={fmtNum(horasPromDia)} sub="equipos productivos" color={C.green}/>
        <StatCard icon="parts" label="Días OD" value={diasOD} sub="orden del día" color={C.yellow}/>
        <StatCard icon="warn" label="Equipos en FS" value={equiposFS} sub="fuera de servicio" color={C.red}/>
      </div>

      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:14}}>
        <Card title="Top 10 Equipos — Horas (sin camionetas/camiones)">
          <div style={{padding:"12px 6px"}}>
            <ResponsiveContainer width="100%" height={Math.max(200,topEquipos.length*34+40)}>
              <BarChart data={topEquipos} layout="vertical" margin={{left:8,right:16}}>
                <CartesianGrid strokeDasharray="3 3" stroke={C.border} horizontal={false}/>
                <XAxis type="number" tick={{fill:C.textMuted,fontSize:10}} axisLine={false} tickLine={false}/>
                <YAxis type="category" dataKey="name" tick={{fill:C.textSub,fontSize:10}} width={84} axisLine={false} tickLine={false}/>
                <Tooltip content={<TooltipEquipo/>}/>
                <Bar dataKey="horas" fill={C.accent} radius={[0,4,4,0]} name="Horas" barSize={20}/>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </Card>
        <div style={{display:"flex",flexDirection:"column",gap:14}}>
          <Card title="Top 10 Tareas — ROP05">
            <div style={{padding:"8px 12px 12px",display:"flex",flexDirection:"column",gap:7}}>
              {topTareas.map((t,i)=>(
                <div key={i} style={{display:"flex",flexDirection:"column",gap:3}}>
                  <div style={{display:"flex",alignItems:"center",gap:7}}>
                    <span style={{fontSize:11,fontWeight:800,color:C.accent,width:16,textAlign:"right",flexShrink:0,fontFamily:"Inter"}}>{i+1}</span>
                    <span style={{fontSize:11,color:C.text,flex:1,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",fontWeight:500}}>{t.name}</span>
                    <span style={{fontSize:11,fontWeight:700,color:C.accent,flexShrink:0,minWidth:36,textAlign:"right"}}>{t.pct}%</span>
                  </div>
                  <div style={{marginLeft:23,background:C.border,borderRadius:3,height:4,overflow:"hidden"}}>
                    <div style={{width:`${t.pct}%`,height:"100%",background:C.accent,borderRadius:3,transition:"width .4s ease"}}/>
                  </div>
                </div>
              ))}
            </div>
          </Card>
          <Card title="Horas por Proyecto">
            <div style={{padding:"10px 14px 12px",display:"flex",alignItems:"center",gap:16}}>
              <ResponsiveContainer width={120} height={120}>
                <PieChart>
                  <Pie data={horasProy} cx="50%" cy="50%" outerRadius={52} innerRadius={30} dataKey="value" nameKey="name" labelLine={false} label={false}>
                    {horasProy.map((entry,i)=><Cell key={i} fill={entry.name==="FILO DEL SOL"?"#e8001d":entry.name==="JOSE MARIA"?"#f0f0f0":"#ffaa00"}/>)}
                  </Pie>
                  <Tooltip content={<ChartTip/>}/>
                </PieChart>
              </ResponsiveContainer>
              <div style={{flex:1,display:"flex",flexDirection:"column",gap:8}}>
                {(()=>{const total=horasProy.reduce((s,r)=>s+r.value,0);return horasProy.map((entry,i)=>{const col=entry.name==="FILO DEL SOL"?"#e8001d":entry.name==="JOSE MARIA"?"#f0f0f0":"#ffaa00";const pct=total>0?Math.round((entry.value/total)*100):0;return(<div key={i} style={{display:"flex",flexDirection:"column",gap:3}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"baseline"}}><span style={{fontSize:11,fontWeight:600,color:col}}>{entry.name==="FILO DEL SOL"?"FILO DEL SOL":"JOSÉ MARÍA"}</span><span style={{fontSize:14,fontWeight:800,color:col,fontFamily:"Inter"}}>{pct}%</span></div><div style={{background:C.border,borderRadius:3,height:5,overflow:"hidden"}}><div style={{width:pct+"%",height:"100%",background:col,borderRadius:3}}/></div><span style={{fontSize:10,color:C.textMuted}}>{fmtNum(entry.value)} hs</span></div>);});})()} 
              </div>
            </div>
          </Card>
        </div>
      </div>

      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:14}}>
        <Card title="Top 8 Operarios — Horas (equipos productivos)">
          <div style={{padding:"12px 6px"}}>
            <ResponsiveContainer width="100%" height={180}>
              <BarChart data={topOps} margin={{left:0,right:16}}>
                <CartesianGrid strokeDasharray="3 3" stroke={C.border} vertical={false}/>
                <XAxis dataKey="name" tick={{fill:C.textMuted,fontSize:9}} axisLine={false} tickLine={false}/>
                <YAxis tick={{fill:C.textMuted,fontSize:10}} axisLine={false} tickLine={false}/>
                <Tooltip content={<TooltipOperario/>}/>
                <Bar dataKey="horas" fill={C.accent} radius={[4,4,0,0]} name="Horas"/>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </Card>
        <Card title="Resumen Operativo">
          <div style={{padding:16,display:"flex",flexDirection:"column",gap:10}}>
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:8}}>
              <div style={{background:C.greenDim,borderRadius:8,padding:"12px 10px",border:`1px solid ${C.green}33`,textAlign:"center"}}>
                <div style={{fontFamily:"Inter",fontSize:22,fontWeight:800,color:C.green}}>{fmtNum(horasPromDia)}</div>
                <div style={{fontSize:10,color:C.textSub,marginTop:2}}>Hs prom./día</div>
              </div>
              <div style={{background:C.yellowDim,borderRadius:8,padding:"12px 10px",border:`1px solid ${C.yellow}33`,textAlign:"center"}}>
                <div style={{fontFamily:"Inter",fontSize:22,fontWeight:800,color:C.yellow}}>{diasOD}</div>
                <div style={{fontSize:10,color:C.textSub,marginTop:2}}>Días OD</div>
              </div>
              <div style={{background:C.redDim,borderRadius:8,padding:"12px 10px",border:`1px solid ${C.red}33`,textAlign:"center"}}>
                <div style={{fontFamily:"Inter",fontSize:22,fontWeight:800,color:C.red}}>{equiposFS}</div>
                <div style={{fontSize:10,color:C.textSub,marginTop:2}}>Equipos en FS</div>
              </div>
            </div>
            <div style={{borderTop:`1px solid ${C.border}`,paddingTop:10,display:"flex",flexDirection:"column",gap:6}}>
              <div style={{fontSize:10,color:C.textMuted,fontWeight:600,letterSpacing:".06em",textTransform:"uppercase"}}>Equipos FS por máquina</div>
              {r02f.filter(r=>r.estado==="FS"&&!isExcluded(r.maquina)).reduce((acc,r)=>{
                const ex=acc.find(a=>a.m===r.maquina);
                if(ex)ex.d=uniq([...ex.d,r.fecha]);else acc.push({m:r.maquina,d:[r.fecha]});
                return acc;
              },[]).sort((a,b)=>b.d.length-a.d.length).slice(0,5).map((e,i)=>(
                <div key={i} style={{display:"flex",alignItems:"center",gap:8}}>
                  <span style={{fontSize:10,fontWeight:700,color:C.red,fontFamily:"Inter",width:90,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",flexShrink:0}}>{e.m}</span>
                  <div style={{flex:1,background:C.border,borderRadius:3,height:5}}>
                    <div style={{width:`${(e.d.length/Math.max(...r02f.filter(r=>r.estado==="FS"&&!isExcluded(r.maquina)).reduce((acc,r)=>{const ex=acc.find(a=>a.m===r.maquina);if(ex)ex.d=uniq([...ex.d,r.fecha]);else acc.push({m:r.maquina,d:[r.fecha]});return acc;},[]).map(a=>a.d.length)))*100}%`,height:"100%",background:C.red,borderRadius:3}}/>
                  </div>
                  <span style={{fontSize:10,color:C.textMuted,flexShrink:0}}>{e.d.length}d</span>
                </div>
              ))}
            </div>
          </div>
        </Card>
      </div>
    </div>
  );
}

// ─── Hook: filtros facetados genérico ─────────────────────────────────────────
function useFacetedFilters(allRows, filterKeys, extState, setExtState){
  // Si se pasa extState, usarlo como fuente de verdad (persistencia entre pestañas)
  const fkKeys=useMemo(()=>filterKeys.map(f=>f.key).join(","),[filterKeys]);
  const fkDefaults=useMemo(()=>Object.fromEntries(filterKeys.map(f=>[f.key,f.defaultVal])),[filterKeys]);

  const defaultState=useMemo(()=>({mode:"dia",fecha:"",fechaD:"",fechaH:"",vals:fkDefaults}),[fkDefaults]);

  const[localState,setLocalState]=useState(defaultState);
  const state=extState||localState;
  const setState=useCallback((updater)=>{
    if(setExtState)setExtState(updater);
    else setLocalState(updater);
  },[setExtState]);

  const mode=state.mode;
  const fecha=state.fecha;
  const fechaD=state.fechaD;
  const fechaH=state.fechaH;
  const vals=state.vals||fkDefaults;

  const setMode=useCallback(v=>setState(s=>({...s,mode:v})),[setState]);
  const setFecha=useCallback(v=>setState(s=>({...s,fecha:v})),[setState]);
  const setFechaD=useCallback(v=>setState(s=>({...s,fechaD:v})),[setState]);
  const setFechaH=useCallback(v=>setState(s=>({...s,fechaH:v})),[setState]);

  // byFecha: filtrado solo por fecha — base para todo
  const byFecha=useMemo(()=>byDateFilter(allRows,mode,fecha,fechaD,fechaH),[allRows,mode,fecha,fechaD,fechaH]);

  // filtered: aplica todos los selectores sobre byFecha
  const filtered=useMemo(()=>{
    const activeFilters=filterKeys.filter(f=>vals[f.key]!==f.defaultVal);
    if(activeFilters.length===0)return byFecha;
    return byFecha.filter(r=>activeFilters.every(f=>r[f.key]===vals[f.key]));
  },[byFecha,vals,fkKeys]);// eslint-disable-line

  // opts: opciones facetadas
  const opts=useMemo(()=>{
    const result={};
    const valsEntries=Object.entries(vals);
    filterKeys.forEach(f=>{
      const otherActives=valsEntries.filter(([k,v])=>k!==f.key&&v!==fkDefaults[k]);
      if(otherActives.length===0){
        result[f.key]=uniq(byFecha.map(r=>r[f.key]));
      } else {
        result[f.key]=uniq(byFecha.filter(r=>
          otherActives.every(([k,v])=>r[k]===v)
        ).map(r=>r[f.key]));
      }
    });
    return result;
  },[byFecha,vals,fkKeys]);// eslint-disable-line

  const set=useCallback((key,val)=>setState(s=>({...s,vals:{...s.vals,[key]:val}})),[setState]);
  const reset=useCallback(()=>setState(s=>({...s,mode:"dia",fecha:"",fechaD:"",fechaH:"",vals:fkDefaults})),[setState,fkDefaults]);
  const hayFiltros=fecha||fechaD||fechaH||filterKeys.some(f=>vals[f.key]!==f.defaultVal);

  return{mode,setMode,fecha,setFecha,fechaD,setFechaD,fechaH,setFechaH,byFecha,filtered,opts,vals,set,reset,hayFiltros};
}


// ─── EquipoCard ───────────────────────────────────────────────────────────────
function EquipoCard({img,nombre,prefijos,rop02Prod}){
  const[hover,setHover]=useState(false);
  const codigos=useMemo(()=>
    uniq((rop02Prod||[]).map(r=>r.maquina).filter(m=>prefijos.some(p=>m.startsWith(p))))
  ,[rop02Prod,prefijos]);
  return(
    <div
      style={{position:"relative",display:"flex",flexDirection:"column",alignItems:"center",gap:0,background:C.surface,borderRadius:10,overflow:"visible",border:`1px solid ${hover?C.accent:C.border}`,transition:"border-color .2s",cursor:"default"}}
      onMouseEnter={()=>setHover(true)}
      onMouseLeave={()=>setHover(false)}
    >
      <div style={{width:"100%",height:110,background:"#111",borderRadius:"10px 10px 0 0",overflow:"hidden",display:"flex",alignItems:"center",justifyContent:"center"}}>
        <img src={img} alt={nombre} style={{maxWidth:"100%",maxHeight:"100%",objectFit:"contain",display:"block"}}/>
      </div>
      <span style={{fontFamily:"Inter",fontWeight:700,fontSize:11,color:C.accent,padding:"7px 0",textAlign:"center"}}>{nombre}</span>
      {hover&&codigos.length>0&&(
        <div style={{position:"absolute",bottom:"calc(100% + 8px)",left:"50%",transform:"translateX(-50%)",background:C.surface,border:`1px solid ${C.border}`,borderRadius:10,padding:"10px 14px",zIndex:9999,minWidth:170,boxShadow:"0 4px 24px rgba(0,0,0,.7)",pointerEvents:"none"}}>
          <div style={{fontFamily:"Inter",fontWeight:700,fontSize:11,color:C.accent,marginBottom:6,borderBottom:`1px solid ${C.border}`,paddingBottom:4}}>
            {nombre} — {codigos.length} equipo{codigos.length!==1?"s":""}
          </div>
          <div style={{display:"flex",flexDirection:"column",gap:3,maxHeight:200,overflowY:"auto"}}>
            {codigos.map(c=><span key={c} style={{fontSize:11,color:C.text,fontFamily:"monospace",letterSpacing:".04em"}}>{c}</span>)}
          </div>
        </div>
      )}
    </div>
  );
}

// ─── ViewROP02 ────────────────────────────────────────────────────────────────
function ViewROP02({rop02All,extState,setExtState}){
  // Excluir camionetas y camiones de toda la vista ROP02
  const rop02Prod=useMemo(()=>rop02All.filter(r=>!isExcluded(r.maquina)),[rop02All]);

  const fk=useMemo(()=>[
    {key:"proyecto",defaultVal:"todos"},
    {key:"maquina",defaultVal:"todas"},
    {key:"supervisor",defaultVal:"todos"},
    {key:"operario",defaultVal:"todos"},
  ],[]);
  const{mode,setMode,fecha,setFecha,fechaD,setFechaD,fechaH,setFechaH,filtered:filteredBase,opts,vals,set,reset,hayFiltros}=useFacetedFilters(rop02Prod,fk,extState,setExtState);

  // Filtro de estado independiente (no afecta las opciones facetadas de otros selectores)
  const[estado,setEstado]=useState("todos");
  const filtered=useMemo(()=>{
    if(estado==="todos")return filteredBase;
    if(estado==="TRABAJO")return filteredBase.filter(r=>r.estado==="TRABAJO");
    if(estado==="OD")return filteredBase.filter(r=>r.estado==="OD");
    if(estado==="FS")return filteredBase.filter(r=>r.estado==="FS");
    return filteredBase;
  },[filteredBase,estado]);

  const stats=useMemo(()=>({
    horas:filtered.reduce((s,r)=>s+r.horas,0),
    comb:filtered.reduce((s,r)=>s+r.combustible,0),
    equipos:uniq(filtered.map(r=>r.maquina)).length,
    ops:uniq(filtered.map(r=>r.operario)).length,
    prod:filtered.filter(r=>r.estado==="TRABAJO").length,
    od:filtered.filter(r=>r.estado==="OD").length,
    fs:filtered.filter(r=>r.estado==="FS").length,
    desgaste:filtered.filter(r=>r.desgaste&&r.desgaste.trim()!==""&&!r.desgaste.toLowerCase().includes("sin consumo")).length,
  }),[filtered]);
  const horasFecha=useMemo(()=>{if(mode!=="periodo")return[];const m={};filtered.forEach(r=>{m[r.fecha]=(m[r.fecha]||0)+r.horas;});return Object.entries(m).sort().map(([fecha,horas])=>({fecha,horas}));},[filtered,mode]);

  const cols=useMemo(()=>[
    {key:"fecha",label:"Fecha",render:v=>fmtFecha(v)},
    {key:"maquina",label:"Máquina",render:v=><Badge color={C.purple}>{v}</Badge>},
    {key:"operario",label:"Operario"},
    {key:"supervisor",label:"Supervisor"},
    {key:"tipo_trabajo",label:"Tarea",render:v=><span style={{display:"block",maxWidth:260,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}} title={v}>{v||"—"}</span>},
    {key:"horas",label:"Horas",render:v=><span style={{color:C.accent,fontWeight:600}}>{fmtNum(v)}</span>},
    {key:"combustible",label:"Comb.",render:v=>fmtNum(v)},
    {key:"estado",label:"Estado",render:v=><Badge color={v==="FS"?C.red:v==="OD"?C.yellow:C.green}>{v==="OD"?"OD":v||"—"}</Badge>},
    {key:"desgaste",label:"Desgaste",wrap:true,render:v=>v&&!v.toLowerCase().includes("sin consumo")?<Badge color={C.purple}>{v}</Badge>:<span style={{color:C.textMuted}}>—</span>},
    {key:"proyecto",label:"Proyecto",render:v=><Badge color={v?.includes("FILO")?C.accent:C.teal}>{v||"—"}</Badge>},
  ],[]);
  // Ordenar de más reciente a más viejo
  const filteredSorted=useMemo(()=>[...filtered].sort((a,b)=>b.fecha.localeCompare(a.fecha)),[filtered]);
  return(
    <div className="fade-in" style={{display:"flex",flexDirection:"column",gap:14}}>
      <Card>
        <div style={{padding:"12px 14px",display:"flex",flexDirection:"column",gap:10}}>
          <div style={{display:"flex",gap:7}}>
            <TabBtn active={mode==="dia"} onClick={()=>setMode("dia")}>Por día</TabBtn>
            <TabBtn active={mode==="periodo"} onClick={()=>setMode("periodo")}>Por período</TabBtn>
          </div>
          <div style={{display:"flex",flexWrap:"wrap",gap:10,alignItems:"flex-end"}}>
            {mode==="dia"?<DateIn label="Fecha" value={fecha} onChange={setFecha}/>:<><DateIn label="Desde" value={fechaD} onChange={setFechaD} max={fechaH||undefined}/><DateIn label="Hasta" value={fechaH} onChange={setFechaH} min={fechaD||undefined} warn={fechaH&&fechaD&&fechaH<fechaD?"≥ Desde":null}/></>}
            <Sel label="Proyecto" value={vals.proyecto} onChange={v=>set("proyecto",v)} options={[{value:"todos",label:"Todos"},...opts.proyecto.map(p=>({value:p,label:p}))]}/>
            <Sel label="Máquina" value={vals.maquina} onChange={v=>set("maquina",v)} options={[{value:"todas",label:"Todas"},...opts.maquina.map(m=>({value:m,label:m}))]}/>
            <Sel label="Supervisor" value={vals.supervisor} onChange={v=>set("supervisor",v)} options={[{value:"todos",label:"Todos"},...opts.supervisor.map(s=>({value:s,label:s}))]}/>
            <Sel label="Operario" value={vals.operario} onChange={v=>set("operario",v)} options={[{value:"todos",label:"Todos"},...opts.operario.map(o=>({value:o,label:o}))]}/>
            <Sel label="Estado" value={estado} onChange={setEstado} options={[
              {value:"todos",label:"Todos"},
              {value:"TRABAJO",label:"✅ Trabajo efectivo"},
              {value:"OD",label:"🟡 Operativo a Disposición"},
              {value:"FS",label:"🔴 Fuera de servicio"},
            ]}/>
            <button onClick={reset} style={{marginLeft:"auto",display:"flex",alignItems:"center",gap:5,padding:"6px 12px",borderRadius:7,border:`1px solid ${C.red}44`,background:C.redDim,color:C.red,cursor:"pointer",fontSize:11,fontWeight:600,fontFamily:"Inter",opacity:hayFiltros?1:0.3,pointerEvents:hayFiltros?"auto":"none"}}>
              <Icon name="close" size={11} color={C.red}/>Limpiar filtros
            </button>
          </div>
        </div>
      </Card>
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(120px,1fr))",gap:10}}>
        <StatCard icon="hours" label="Horas" value={fmtNum(stats.horas)} color={C.yellow} small/>
        <StatCard icon="fuel" label="Combustible" value={fmtNum(stats.comb)} color={C.teal} small/>
        <StatCard icon="equip" label="Equipos" value={stats.equipos} color={C.purple} small/>
        <StatCard icon="parts" label="Operarios" value={stats.ops} color={C.blue} small/>
        <StatCard icon="check" label="Productivos" value={stats.prod} color={C.green} small/>
        <StatCard icon="parts" label="Días OD" value={stats.od} color={C.yellow} small/>
        <StatCard icon="warn" label="Días FS" value={stats.fs} color={C.red} small/>
        <StatCard icon="wear" label="Días con elementos de desgaste" value={stats.desgaste} color={C.purple} small/>
      </div>
      {mode==="periodo"&&horasFecha.length>0&&(
        <Card title="Kilómetros por Fecha">
          <div style={{padding:"10px 6px"}}>
            <ResponsiveContainer width="100%" height={160}>
              <AreaChart data={horasFecha} margin={{left:0,right:10}}>
                <defs><linearGradient id="g1" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor={C.accent} stopOpacity={.3}/><stop offset="95%" stopColor={C.accent} stopOpacity={0}/></linearGradient></defs>
                <CartesianGrid strokeDasharray="3 3" stroke={C.border} vertical={false}/>
                <XAxis dataKey="fecha" tick={{fill:C.textMuted,fontSize:9}} axisLine={false} tickLine={false}/>
                <YAxis tick={{fill:C.textMuted,fontSize:10}} axisLine={false} tickLine={false}/>
                <Tooltip content={<ChartTip/>}/>
                <Area type="monotone" dataKey="horas" stroke={C.accent} fill="url(#g1)" name="Horas" strokeWidth={2}/>
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </Card>
      )}
      {mode==="periodo"&&(
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12}}>
          {["FILO DEL SOL","JOSE MARIA"].map((p,i)=>{
            const rows=filtered.filter(r=>r.proyecto===p);
            return(
              <Card key={p} style={{borderColor:(i===0?C.accent:C.teal)+"44"}}>
                <div style={{padding:"12px 16px"}}>
                  <Badge color={i===0?C.accent:C.teal}>{p}</Badge>
                  <div style={{marginTop:10,display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
                    {[[fmtNum(rows.reduce((s,r)=>s+r.horas,0)),"horas",i===0?C.accent:C.teal],[fmtNum(rows.reduce((s,r)=>s+r.combustible,0)),"combustible",C.teal],[rows.length,"registros",C.blue],[uniq(rows.map(r=>r.maquina)).length,"equipos",C.purple]].map(([v,l,c],j)=>(
                      <div key={j}><div style={{fontFamily:"Inter",fontSize:18,fontWeight:800,color:c}}>{v}</div><div style={{fontSize:10,color:C.textMuted}}>{l}</div></div>
                    ))}
                  </div>
                </div>
              </Card>
            );
          })}
        </div>
      )}
      <Card title={`Registros (${filtered.length})`} action={
        <button onClick={()=>{const label=(fecha||fechaD||new Date().toISOString().slice(0,10)).replace(/-/g,"");generarExcelROP02(filteredSorted,label);}} style={{display:"flex",alignItems:"center",gap:5,padding:"5px 12px",borderRadius:7,border:`1px solid ${C.teal}44`,background:C.tealDim,color:C.teal,cursor:"pointer",fontSize:11,fontWeight:600,fontFamily:"Inter"}}>
          ⬇ Excel
        </button>
      }>
        <Table cols={cols} rows={filteredSorted} maxH={400} emptyMsg="Sin registros con los filtros seleccionados"/>
      </Card>
      <Card title="Flota de Equipos" style={{overflow:"visible"}}>
        <div style={{padding:"14px 16px",display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(160px,1fr))",gap:12}}>
          {[
            {img:IMG_CARGADORA_FRONTAL,   nombre:"Cargadora Frontal",   prefijos:["CFN","PCA"]},
            {img:IMG_EXCAVADORA,          nombre:"Excavadora",          prefijos:["EXC"]},
            {img:IMG_TOPADORA,            nombre:"Topadora",            prefijos:["TOP"]},
            {img:IMG_MOTONIVELADORA,      nombre:"Motoniveladora",      prefijos:["MOT"]},
            {img:IMG_RETROPALA,           nombre:"Retropala",           prefijos:["RTP"]},
            {img:IMG_RODILLO_COMPACTADOR, nombre:"Rodillo Compactador", prefijos:["ROD","RPC","RCP"]},
            {img:IMG_MINICARGADORA,       nombre:"Minicargadora",       prefijos:["MCA","MNC"]},
          ].map(tipo=>(
            <EquipoCard key={tipo.nombre} {...tipo} rop02Prod={filtered}/>
          ))}
        </div>
      </Card>
    </div>
  );
}

// ─── Generar Excel de Productividad ──────────────────────────────────────────
function estilosCelda(wb){
  // Helper para crear estilos
  const s=(fill,font,border,align)=>({
    fill:fill?{fgColor:{rgb:fill},patternType:"solid"}:undefined,
    font:font||undefined,
    border:border?{top:{style:"thin",color:{rgb:"CCCCCC"}},bottom:{style:"thin",color:{rgb:"CCCCCC"}},left:{style:"thin",color:{rgb:"CCCCCC"}},right:{style:"thin",color:{rgb:"CCCCCC"}}}:undefined,
    alignment:align||{vertical:"center"},
  });
  return{
    titulo:   s("1A1A2E",{bold:true,color:{rgb:"FFFFFF"},sz:13},true,{horizontal:"center",vertical:"center"}),
    periodo:  s("2D2D2D",{color:{rgb:"AAAAAA"},sz:10},false,{horizontal:"left",vertical:"center"}),
    tipoEq:   s("C00000",{bold:true,color:{rgb:"FFFFFF"},sz:11},true,{horizontal:"center",vertical:"center"}),
    proyJM:   s("1F4E79",{bold:true,color:{rgb:"FFFFFF"},sz:10},true,{horizontal:"center",vertical:"center"}),
    proyFDS:  s("833C00",{bold:true,color:{rgb:"FFFFFF"},sz:10},true,{horizontal:"center",vertical:"center"}),
    header:   s("2E2E2E",{bold:true,color:{rgb:"DDDDDD"},sz:9},true,{horizontal:"center",vertical:"center"}),
    tareaJM:  s("EBF3FB",{color:{rgb:"1A1A2E"},sz:10},true,{horizontal:"left",vertical:"center"}),
    tareaFDS: s("FFF2CC",{color:{rgb:"3A2000"},sz:10},true,{horizontal:"left",vertical:"center"}),
    numJM:    s("EBF3FB",{color:{rgb:"1F4E79"},sz:10},true,{horizontal:"center",vertical:"center"}),
    numFDS:   s("FFF2CC",{color:{rgb:"833C00"},sz:10},true,{horizontal:"center",vertical:"center"}),
    vacio:    s("F5F5F5",null,true,{horizontal:"center",vertical:"center"}),
    sep:      s("888888",null,false,{horizontal:"center",vertical:"center"}),
  };
}

function setCelda(ws,ref,valor,estilo){
  if(!ws[ref])ws[ref]={v:valor,t:typeof valor==="number"?"n":"s"};
  else{ws[ref].v=valor;ws[ref].t=typeof valor==="number"?"n":"s";}
  if(estilo)ws[ref].s=estilo;
}

function generarExcelProductividad(rop05, fechaD, fechaH, mode, fechaDia){
  const MESES=["Enero","Febrero","Marzo","Abril","Mayo","Junio","Julio","Agosto","Septiembre","Octubre","Noviembre","Diciembre"];

  // Período mensual = lo que el usuario tiene en los filtros
  let fechaDesde, fechaHasta, mesNombre, y;
  if(mode==="dia"&&fechaDia){
    fechaDesde=fechaDia; fechaHasta=fechaDia;
    const d=new Date(fechaDia);
    mesNombre=MESES[d.getMonth()]; y=d.getFullYear();
  } else if(fechaD&&fechaH){
    fechaDesde=fechaD; fechaHasta=fechaH;
    const d=new Date(fechaD);
    mesNombre=MESES[d.getMonth()]; y=d.getFullYear();
  } else {
    // Sin filtro: usar mes actual
    const hoy=new Date();
    mesNombre=MESES[hoy.getMonth()]; y=hoy.getFullYear();
    const mesNum=hoy.getMonth()+1;
    fechaDesde=`${y}-${String(mesNum).padStart(2,"0")}-01`;
    // Último día real del mes
    const lastDay=new Date(y,mesNum,0).getDate();
    fechaHasta=`${y}-${String(mesNum).padStart(2,"0")}-${String(lastDay).padStart(2,"0")}`;
  }

  // Temporada según mes de inicio del período
  const mesInicio=new Date(fechaDesde).getMonth(); // 0=Ene
  const esVerano=m=>[8,9,10,11,0,1,2,3].includes(m);
  const temporada=esVerano(mesInicio)?"VERANO (Sep-Abr)":"INVIERNO (May-Ago)";

  // Acumulado: desde inicio de temporada hasta fechaHasta
  let tempDesde;
  if(esVerano(mesInicio)){
    // Verano empieza en Sep
    const añoSep=mesInicio<=3?y-1:y;
    tempDesde=`${añoSep}-09-01`;
  } else {
    // Invierno empieza en May
    tempDesde=`${y}-05-01`;
  }
  const tempHasta=fechaHasta;

  // Filtrar ROP05 por período (excluir HS)
  const filtrarRows=(rows, desde, hasta)=>rows.filter(r=>{
    if(!r.fecha||r.fecha<desde||r.fecha>hasta)return false;
    if(!r.unidad||r.unidad.trim().toUpperCase()==="HS")return false;
    if(!r.horas||r.horas<=0)return false;
    return true;
  });

  const rowsMes=filtrarRows(rop05,fechaDesde,fechaHasta);
  const rowsTemp=filtrarRows(rop05,tempDesde,tempHasta);

  const TIPOS=[
    {nombre:"Motoniveladora",prefijos:["MOT"]},
    {nombre:"Excavadora",prefijos:["EXC"]},
    {nombre:"Rodillo Compactador",prefijos:["ROD","RPC","RCP"]},
    {nombre:"Cargadora Frontal",prefijos:["CFN","PCA"]},
    {nombre:"Minicargadora",prefijos:["MCA","MNC"]},
    {nombre:"Retropala",prefijos:["RTP"]},
    {nombre:"Topadora",prefijos:["TOP"]},
  ];
  const PROYECTOS=["JOSE MARIA","FILO DEL SOL"];

  // Calcular rendimiento: cantidad/horas por tarea, convirtiendo KL→ML (*1000)
  const calcRendimiento=(rows)=>{
    const m={};
    rows.forEach(r=>{
      const k=r.tarea||"Sin tarea";
      if(!m[k])m[k]={horas:0,horasML:0,horasKL:0,horasM2:0,horasM3:0,ml:0,kl:0,m2:0,m3:0};
      m[k].horas+=r.horas;
      const u=(r.unidad||"").trim().toUpperCase();
      const cant=r.cantidad||0;
      // KL y ML separados — igual que los recuadros y la tabla en pantalla
      if(u==="METROS LINEALES"){m[k].ml+=cant;m[k].horasML+=r.horas;}
      else if(u==="KILOMETROS LINEALES"||u==="KILÓMETROS LINEALES"){m[k].kl+=cant;m[k].horasKL+=r.horas;}
      else if(u==="M2"){m[k].m2+=cant;m[k].horasM2+=r.horas;}
      else if(u==="M3"){m[k].m3+=cant;m[k].horasM3+=r.horas;}
    });
    return m;
  };

  // Filtrar tareas al 80% de horas y calcular rendimiento
  const calcTabla=(rows)=>{
    const rend=calcRendimiento(rows);
    const tareas=Object.entries(rend).sort((a,b)=>b[1].horas-a[1].horas);
    const totalHoras=tareas.reduce((s,[,v])=>s+v.horas,0);
    let acum=0;
    const result=[];
    for(const [tarea,v] of tareas){
      if(acum/totalHoras>=0.8&&result.length>0)break;
      result.push({
        tarea,
        horas:Math.round(v.horas*10)/10,
        mlHs:v.horasML>0&&v.ml>0?Math.round(v.ml/v.horasML*10)/10:0,
        klHs:v.horasKL>0&&v.kl>0?Math.round(v.kl/v.horasKL*10)/10:0,
        m2Hs:v.horasM2>0&&v.m2>0?Math.round(v.m2/v.horasM2*10)/10:0,
        m3Hs:v.horasM3>0&&v.m3>0?Math.round(v.m3/v.horasM3*10)/10:0,
      });
      acum+=v.horas;
    }
    return result;
  };

  const wb=XLSX.utils.book_new();
  const ST=estilosCelda(wb);
  const COLS=[{wch:32},{wch:7},{wch:7},{wch:7},{wch:7},{wch:2},{wch:32},{wch:7},{wch:7},{wch:7},{wch:7}];

  // 10 columnas: A-E = JM, F-J = FDS (sin separador)
  const COLS10=[{wch:32},{wch:7},{wch:7},{wch:7},{wch:7},{wch:7},{wch:32},{wch:7},{wch:7},{wch:7},{wch:7},{wch:7}];

  const construirHoja=(rowsFiltradas, titulo, periodo)=>{
    const data=[];
    const merges=[];

    // Título — combinado A:J
    data.push([titulo,"","","","","","","","",""]);
    merges.push({s:{r:0,c:0},e:{r:0,c:9}});

    // Período
    data.push([`Período: ${periodo}`,"","","","","","","","",""]);
    merges.push({s:{r:1,c:0},e:{r:1,c:9}});

    data.push([]); // espacio

    TIPOS.forEach(tipo=>{
      const rowsJM=rowsFiltradas.filter(r=>tipo.prefijos.some(p=>r.maquina?.startsWith(p))&&r.proyecto==="JOSE MARIA");
      const rowsFDS=rowsFiltradas.filter(r=>tipo.prefijos.some(p=>r.maquina?.startsWith(p))&&r.proyecto==="FILO DEL SOL");
      const tablaJM=calcTabla(rowsJM);
      const tablaFDS=calcTabla(rowsFDS);
      if(!tablaJM.length&&!tablaFDS.length)return;

      const baseRow=data.length;

      // Nombre del tipo — combinado A:J
      data.push([tipo.nombre.toUpperCase(),"","","","","","","","",""]);
      merges.push({s:{r:baseRow,c:0},e:{r:baseRow,c:9}});

      // Proyectos — JM combinado A:E, FDS combinado F:J
      data.push(["JOSE MARIA","","","","","FILO DEL SOL","","","",""]);
      merges.push({s:{r:baseRow+1,c:0},e:{r:baseRow+1,c:5}});
      merges.push({s:{r:baseRow+1,c:6},e:{r:baseRow+1,c:11}});

      // Headers columnas
      data.push(["Tarea JM","Hs","ML/Hs","KL/Hs","M2/Hs","M3/Hs","Tarea FDS","Hs","ML/Hs","KL/Hs","M2/Hs","M3/Hs"]);

      // Datos
      const maxR=Math.max(tablaJM.length,tablaFDS.length,1);
      for(let i=0;i<maxR;i++){
        const jm=tablaJM[i];
        const fds=tablaFDS[i];
        data.push([
          jm?jm.tarea:"", jm?jm.horas||0:0, jm?jm.mlHs||0:0, jm?jm.klHs||0:0, jm?jm.m2Hs||0:0, jm?jm.m3Hs||0:0,
          fds?fds.tarea:"",fds?fds.horas||0:0,fds?fds.mlHs||0:0,fds?fds.klHs||0:0,fds?fds.m2Hs||0:0,fds?fds.m3Hs||0:0,
        ]);
      }
      data.push([]); // espacio
    });

    const ws=XLSX.utils.aoa_to_sheet(data);
    ws["!merges"]=merges;
    ws["!cols"]=COLS10;
    return ws;
  };

  const wsMes=construirHoja(rowsMes,`INFORME DE PRODUCTIVIDAD — ${mesNombre.toUpperCase()} ${y}`,`${fechaDesde} → ${fechaHasta}`);
  XLSX.utils.book_append_sheet(wb,wsMes,`${mesNombre} ${y}`);

  const wsAcum=construirHoja(rowsTemp,`PRODUCTIVIDAD ACUMULADA — ${temporada}`,`${tempDesde} → ${tempHasta}`);
  XLSX.utils.book_append_sheet(wb,wsAcum,`Acumulado ${temporada.split(" ")[0]}`);

  // ── Descargar con estilos ─────────────────────────────────────────────────
  XLSX.writeFile(wb,`Productividad_${mesNombre}_${y}.xlsx`);
}


// ─── ViewROP05 ────────────────────────────────────────────────────────────────
function ViewROP05({rop05,extState,setExtState}){
  const fk=useMemo(()=>[
    {key:"proyecto",defaultVal:"todos"},
    {key:"maquina",defaultVal:"todas"},
    {key:"supervisor",defaultVal:"todos"},
    {key:"unidad",defaultVal:"todas"},
  ],[]);
  const{mode,setMode,fecha,setFecha,fechaD,setFechaD,fechaH,setFechaH,filtered:filteredBase05,opts,vals,set,reset,hayFiltros}=useFacetedFilters(rop05,fk,extState,setExtState);

  // Filtro de tarea independiente — sus opciones dependen de la máquina seleccionada
  const[tarea,setTarea]=useState("todas");

  // Filtro por tipo de máquina (agrupa por prefijo)
  const TIPOS_MAQUINA=[
    {label:"Todas",value:"todas",prefijos:[]},
    {label:"Cargadora Frontal",value:"CFN",prefijos:["CFN","PCA"]},
    {label:"Minicargadora",value:"MCA",prefijos:["MCA","MNC"]},
    {label:"Excavadora",value:"EXC",prefijos:["EXC"]},
    {label:"Topadora",value:"TOP",prefijos:["TOP"]},
    {label:"Motoniveladora",value:"MOT",prefijos:["MOT"]},
    {label:"Retropala",value:"RTP",prefijos:["RTP"]},
    {label:"Rodillo Compactador",value:"ROD",prefijos:["ROD","RPC","RCP"]},
  ];
  const[tipoMaquina,setTipoMaquina]=useState("todas");

  // Opciones de tarea: filtra por tipo de máquina, máquina, proyecto y fecha
  const tareasOpts=useMemo(()=>{
    const tipoActivo=TIPOS_MAQUINA.find(t=>t.value===tipoMaquina);
    const base=rop05.filter(r=>{
      const f=r.fecha||"";
      if(mode==="dia"&&fecha&&f!==fecha)return false;
      if(mode==="periodo"){if(fechaD&&f<fechaD)return false;if(fechaH&&f>fechaH)return false;}
      if(vals.maquina!=="todas"&&r.maquina!==vals.maquina)return false;
      if(vals.proyecto!=="todos"&&r.proyecto!==vals.proyecto)return false;
      // Filtrar por tipo de máquina si está activo
      if(tipoMaquina!=="todas"&&tipoActivo&&!tipoActivo.prefijos.some(p=>r.maquina?.startsWith(p)))return false;
      return true;
    });
    return uniq(base.map(r=>r.tarea).filter(Boolean));
  },[rop05,mode,fecha,fechaD,fechaH,vals.maquina,vals.proyecto,tipoMaquina]);

  // Reset tarea cuando cambia máquina o fecha
  useEffect(()=>{setTarea("todas");},[vals.maquina,mode,fecha,fechaD,fechaH,tipoMaquina]);

  const UNIDADES_GRAFICO=[
    {label:"Metros Lineales",value:"METROS LINEALES"},
    {label:"Km Lineales",value:"KILOMETROS LINEALES"},
    {label:"Metros Cuadrados",value:"M2"},
    {label:"Metros Cúbicos",value:"M3"},
    {label:"Horas (HS)",value:"HS"},
  ];
  const[unidadGrafico,setUnidadGrafico]=useState("METROS LINEALES");


  // Aplicar filtro de tipo sobre filtered
  const filtered=useMemo(()=>{
    let rows=tarea==="todas"?filteredBase05:filteredBase05.filter(r=>r.tarea===tarea);
    if(tipoMaquina!=="todas"){
      const tipo=TIPOS_MAQUINA.find(t=>t.value===tipoMaquina);
      if(tipo)rows=rows.filter(r=>tipo.prefijos.some(p=>r.maquina?.startsWith(p)));
    }
    return rows;
  },[filteredBase05,tarea,tipoMaquina]);



  // Configuración fija de unidades productivas
  // Normaliza string: quita tildes, espacios extra, mayúsculas
  const nu=s=>String(s||"").trim().toUpperCase().normalize("NFD").replace(/[̀-ͯ]/g,"").replace(/\s+/g," ");

  const UNIDADES_CONFIG=useMemo(()=>[
    {titulo:"Productividad Metros Lineales", key:"ML",  match:(u)=>nu(u)==="METROS LINEALES",    color:C.green},
    {titulo:"Productividad Km Lineales",     key:"KL",  match:(u)=>nu(u)==="KILOMETROS LINEALES", color:C.blue},
    {titulo:"Productividad Metros Cuadrados",key:"M2",  match:(u)=>nu(u)==="M2",                  color:C.teal},
    {titulo:"Productividad Metros Cúbicos",  key:"M3",  match:(u)=>nu(u)==="M3",                  color:C.purple},
    {titulo:"Trabajos por Hora",             key:"HS",  match:(u)=>nu(u)==="HS",                  color:C.green},
  ],[]);

  const prodCards=useMemo(()=>UNIDADES_CONFIG.map(cfg=>{
    const rows=filtered.filter(r=>r.unidad&&cfg.match(r.unidad));
    // Para HS: el acumulado es la suma de horas (no de cantidad)
    const cantidad=cfg.key==="HS"
      ? rows.reduce((s,r)=>s+r.horas,0)
      : rows.reduce((s,r)=>s+r.cantidad,0);
    const horas=rows.reduce((s,r)=>s+r.horas,0);
    const rendimiento=horas>0?(cantidad/horas):0;
    return{...cfg,cantidad,horas,rendimiento};
  }),[filtered,UNIDADES_CONFIG]);

  const prodFecha=useMemo(()=>{
    if(mode!=="periodo"&&!fecha)return[];
    const base=mode==="dia"?filtered.filter(r=>r.fecha===fecha):filtered;
    // Obtener todas las fechas del período filtrado (para mantener el eje X)
    const todasFechas=[...new Set(base.map(r=>r.fecha))].sort();
    if(!todasFechas.length)return[];
    const m={};
    // Inicializar todas las fechas en 0
    todasFechas.forEach(f=>{m[f]=0;});
    base.forEach(r=>{
      const u=(r.unidad||"").trim().toUpperCase();
      let val=0;
      if(unidadGrafico==="METROS LINEALES"&&u==="METROS LINEALES")val=r.cantidad;
      else if(unidadGrafico==="KILOMETROS LINEALES"&&(u==="KILOMETROS LINEALES"||u==="KILÓMETROS LINEALES"))val=r.cantidad;
      else if(unidadGrafico==="M2"&&u==="M2")val=r.cantidad;
      else if(unidadGrafico==="M3"&&u==="M3")val=r.cantidad;
      else if(unidadGrafico==="HS"&&u==="HS")val=r.horas;
      else return;
      m[r.fecha]=(m[r.fecha]||0)+val;
    });
    return Object.entries(m).sort().map(([fecha,cantidad])=>({fecha,cantidad}));
  },[filtered,mode,fecha,unidadGrafico]);

  const totalHoras05=useMemo(()=>filtered.reduce((s,r)=>s+r.horas,0),[filtered]);
  const filteredSorted=useMemo(()=>[...filtered].sort((a,b)=>b.fecha.localeCompare(a.fecha)),[filtered]);
  const cols=useMemo(()=>[
    {key:"fecha",label:"Fecha",render:v=>fmtFecha(v)},
    {key:"maquina",label:"Máquina",render:v=><Badge color={C.purple}>{v}</Badge>},
    {key:"tipo_maquina",label:"Tipo",render:(v,r)=>{const t=v||getMachineType(r.maquina)||"—";return <Badge color={C.textSub}>{t}</Badge>;}},
    {key:"tarea",label:"Tarea",render:v=><span style={{display:"block",maxWidth:260,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}} title={v}>{v||"—"}</span>},
    {key:"horas",label:"Horas",render:v=><span style={{color:C.accent,fontWeight:600}}>{fmtNum(v)}</span>},
    {key:"cantidad",label:"Cantidad",render:v=><span style={{color:C.blue,fontWeight:600}}>{fmtNum(v)}</span>},
    {key:"unidad",label:"Unidad",render:v=><Badge color={C.teal}>{v}</Badge>},
    {key:"proyecto",label:"Proyecto",render:v=><Badge color={v?.includes("FILO")?C.accent:C.teal}>{v||"—"}</Badge>},
  ],[]);

  return(
    <div className="fade-in" style={{display:"flex",flexDirection:"column",gap:14}}>
      <Card>
        <div style={{padding:"12px 14px",display:"flex",flexDirection:"column",gap:10}}>
          <div style={{display:"flex",gap:7,alignItems:"center",flexWrap:"wrap"}}>
            <TabBtn active={mode==="dia"} onClick={()=>setMode("dia")}>Por día</TabBtn>
            <TabBtn active={mode==="periodo"} onClick={()=>setMode("periodo")}>Por período</TabBtn>
            <button onClick={()=>generarExcelProductividad(rop05,fechaD,fechaH,mode,fecha)} style={{marginLeft:8,display:"flex",alignItems:"center",gap:6,padding:"7px 14px",borderRadius:7,border:`1px solid ${C.accent}`,background:C.accentDim,color:C.accent,cursor:"pointer",fontSize:12,fontWeight:700,fontFamily:"Inter",letterSpacing:".04em"}}>
              📊 Generar Reporte
            </button>
          </div>
          <div style={{display:"flex",flexWrap:"wrap",gap:10,alignItems:"flex-end"}}>
            {mode==="dia"?<DateIn label="Fecha" value={fecha} onChange={setFecha}/>:<><DateIn label="Desde" value={fechaD} onChange={setFechaD} max={fechaH||undefined}/><DateIn label="Hasta" value={fechaH} onChange={setFechaH} min={fechaD||undefined} warn={fechaH&&fechaD&&fechaH<fechaD?"≥ Desde":null}/></>}
            <Sel label="Proyecto" value={vals.proyecto} onChange={v=>set("proyecto",v)} options={[{value:"todos",label:"Todos"},...opts.proyecto.map(p=>({value:p,label:p}))]}/>
            <Sel label="Tipo de Máquina" value={tipoMaquina} onChange={v=>{setTipoMaquina(v);set("maquina","todas");}} options={TIPOS_MAQUINA.map(t=>({value:t.value,label:t.label}))}/>
            <Sel label="Máquina" value={vals.maquina} onChange={v=>set("maquina",v)} options={[{value:"todas",label:"Todas"},...opts.maquina.filter(m=>tipoMaquina==="todas"||TIPOS_MAQUINA.find(t=>t.value===tipoMaquina)?.prefijos.some(p=>m.startsWith(p))).map(m=>({value:m,label:m}))]}/>
            <Sel label="Supervisor" value={vals.supervisor} onChange={v=>set("supervisor",v)} options={[{value:"todos",label:"Todos"},...opts.supervisor.map(s=>({value:s,label:s}))]}/>
            <Sel label="Tarea" value={tarea} onChange={setTarea} options={[{value:"todas",label:"Todas"},...tareasOpts.map(t=>({value:t,label:t.length>40?t.slice(0,38)+"…":t}))]}/>
            <Sel label="Unidad" value={vals.unidad} onChange={v=>set("unidad",v)} options={[{value:"todas",label:"Todas"},...opts.unidad.map(u=>({value:u,label:u}))]}/>
            <button onClick={reset} style={{marginLeft:"auto",display:"flex",alignItems:"center",gap:5,padding:"6px 12px",borderRadius:7,border:`1px solid ${C.red}44`,background:C.redDim,color:C.red,cursor:"pointer",fontSize:11,fontWeight:600,fontFamily:"Inter",opacity:hayFiltros?1:0.3,pointerEvents:hayFiltros?"auto":"none"}}>
              <Icon name="close" size={11} color={C.red}/>Limpiar filtros
            </button>
          </div>
        </div>
      </Card>
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(140px,1fr))",gap:10}}>
        <StatCard icon="prod" label="Registros" value={filtered.length} color={C.blue} small/>
        <StatCard icon="hours" label="Horas" value={fmtNum(totalHoras05)} color={C.yellow} small/>
        <StatCard icon="equip" label="Equipos" value={uniq(filtered.map(r=>r.maquina)).length} color={C.purple} small/>
        {prodCards.filter(({key})=>key!=="HS").map(({titulo,color,rendimiento})=>(
          <StatCard key={titulo}
            icon="prod"
            label={titulo}
            value={rendimiento>0?fmtNum(rendimiento):"—"}
            sub={rendimiento>0?"unidades / hora":"sin datos"}
            color={color}
            small
          />
        ))}
      </div>
      <div style={{display:"grid",gridTemplateColumns:"repeat(5,1fr)",gap:12}}>
        {prodCards.map(({titulo,color,cantidad,rendimiento})=>(
          <Card key={titulo} style={{borderColor:color+"44"}}>
            <div style={{padding:"14px 16px",display:"flex",flexDirection:"column",gap:6}}>
              <div style={{fontSize:10,color:color,fontWeight:700,letterSpacing:".04em",textTransform:"uppercase",lineHeight:1.3}}>{titulo}</div>
              <div style={{fontFamily:"Inter",fontSize:26,fontWeight:800,color:"#ffffff",lineHeight:1}}>{cantidad>0?fmtNum(cantidad):"—"}</div>
              <div style={{fontSize:10,color:C.textMuted}}>total acumulado</div>
              <div style={{borderTop:`1px solid ${C.border}`,paddingTop:6,display:"flex",justifyContent:"space-between",alignItems:"baseline"}}>
                <span style={{fontSize:10,color:C.textMuted}}>Productividad</span>
                <span style={{fontFamily:"Inter",fontSize:14,fontWeight:800,color:color}}>{rendimiento>0?fmtNum(rendimiento):"—"}<span style={{fontSize:9,fontWeight:400,color:C.textMuted,marginLeft:2}}>/hs</span></span>
              </div>
            </div>
          </Card>
        ))}
      </div>
      {(mode==="periodo")&&filtered.length>0&&(
        <Card title="Producción por Fecha" action={<Sel label="" value={unidadGrafico} onChange={setUnidadGrafico} options={UNIDADES_GRAFICO.map(u=>({value:u.value,label:u.label}))}/>}>
          <div style={{padding:"10px 6px"}}>
            <ResponsiveContainer width="100%" height={160}>
              <AreaChart data={prodFecha} margin={{left:0,right:10}}>
                <defs><linearGradient id="g2" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor={C.blue} stopOpacity={.3}/><stop offset="95%" stopColor={C.blue} stopOpacity={0}/></linearGradient></defs>
                <CartesianGrid strokeDasharray="3 3" stroke={C.border}/>
                <XAxis dataKey="fecha" tick={{fill:C.textMuted,fontSize:9}} axisLine={false} tickLine={false}/>
                <YAxis tick={{fill:C.textMuted,fontSize:9}} axisLine={false} tickLine={false} width={40}/>
                <Tooltip content={({active,payload})=>{
                  if(!active||!payload?.length)return null;
                  return(<div style={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:8,padding:"8px 12px",fontSize:12}}>
                    <div style={{color:C.textSub}}>{payload[0].payload.fecha}</div>
                    <div style={{color:C.blue,fontWeight:700}}>{fmtNum(payload[0].value)}</div>
                  </div>);
                }}/>
                <Area type="monotone" dataKey="cantidad" stroke={C.blue} fill="url(#g2)" strokeWidth={2} dot={false}/>
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </Card>
      )}
      {mode==="periodo"&&filtered.length>0&&(()=>{
        const COLORS=["#e8001d","#3b82f6","#10b981","#f59e0b","#8b5cf6","#ec4899","#06b6d4","#f97316","#84cc16","#6366f1"];
        // Excluir unidad HS igual que en el reporte Excel
        const filteredSinHS=filtered.filter(r=>(r.unidad||"").trim().toUpperCase()!=="HS");
        const tareaMap={};
        filteredSinHS.forEach(r=>{
          if(!r.tarea)return;
          const u=(r.unidad||"").trim().toUpperCase();
          if(!tareaMap[r.tarea])tareaMap[r.tarea]={horas:0,horasML:0,horasKL:0,horasM2:0,horasM3:0,ml:0,kl:0,m2:0,m3:0};
          tareaMap[r.tarea].horas+=r.horas;
          const cant=r.cantidad||0;
          // Acumular horas y cantidad solo para registros que producen esa unidad
          if(u==="METROS LINEALES"){tareaMap[r.tarea].ml+=cant;tareaMap[r.tarea].horasML+=r.horas;}
          else if(u==="KILOMETROS LINEALES"||u==="KILÓMETROS LINEALES"){tareaMap[r.tarea].kl+=cant;tareaMap[r.tarea].horasKL+=r.horas;}
          else if(u==="M2"){tareaMap[r.tarea].m2+=cant;tareaMap[r.tarea].horasM2+=r.horas;}
          else if(u==="M3"){tareaMap[r.tarea].m3+=cant;tareaMap[r.tarea].horasM3+=r.horas;}
        });
        const totalHs=Object.values(tareaMap).reduce((s,v)=>s+v.horas,0);
        const pieData=Object.entries(tareaMap).sort((a,b)=>b[1].horas-a[1].horas).map(([name,v])=>({
          name,
          value:Math.round(v.horas*10)/10,
          pct:Math.round(v.horas/totalHs*1000)/10,
          // Rendimiento: cantidad / horas de registros de esa unidad (igual que los recuadros)
          mlHs:v.horasML>0&&v.ml>0?Math.round(v.ml/v.horasML*10)/10:0,
          klHs:v.horasKL>0&&v.kl>0?Math.round(v.kl/v.horasKL*10)/10:0,
          m2Hs:v.horasM2>0&&v.m2>0?Math.round(v.m2/v.horasM2*10)/10:0,
          m3Hs:v.horasM3>0&&v.m3>0?Math.round(v.m3/v.horasM3*10)/10:0,
        }));
        const maqMap={};
        filtered.forEach(r=>{if(r.maquina)maqMap[r.maquina]=(maqMap[r.maquina]||0)+r.horas;});
        const barData=Object.entries(maqMap).sort((a,b)=>b[1]-a[1]).map(([maquina,horas])=>({maquina,horas}));
        return(
          <div style={{display:"flex",flexDirection:"column",gap:14}}>
          <div style={{display:"grid",gridTemplateColumns:"2fr 3fr",gap:14}}>
            <Card title="Distribución de Horas por Tarea">
              <div style={{padding:"16px",display:"flex",gap:20,alignItems:"center"}}>
                <div style={{flexShrink:0}}>
                  <PieChart width={220} height={220}>
                    <Pie data={pieData} dataKey="value" cx="50%" cy="50%" outerRadius={100} innerRadius={44}>
                      {pieData.map((_,i)=><Cell key={i} fill={COLORS[i%COLORS.length]}/>)}
                    </Pie>
                    <Tooltip content={({active,payload})=>{
                      if(!active||!payload?.length)return null;
                      const d=payload[0].payload;
                      return(<div style={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:8,padding:"8px 12px",fontSize:12}}>
                        <div style={{color:C.text,fontWeight:600,marginBottom:4}}>{d.name}</div>
                        <div style={{color:C.accent}}>{fmtNum(d.value)} hs — {d.pct}%</div>
                      </div>);
                    }}/>
                  </PieChart>
                </div>
                <div style={{display:"flex",flexDirection:"column",gap:8,flex:1,overflow:"hidden"}}>
                  {pieData.map((d,i)=>(
                    <div key={i} style={{display:"flex",alignItems:"center",gap:8}}>
                      <div style={{width:12,height:12,borderRadius:"50%",background:COLORS[i%COLORS.length],flexShrink:0}}/>
                      <span style={{fontSize:13,color:C.textSub,flex:1,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{d.name}</span>
                      <span style={{fontSize:13,fontWeight:700,color:C.text,flexShrink:0}}>{d.pct}%</span>
                      <span style={{fontSize:12,color:C.textMuted,flexShrink:0,minWidth:36,textAlign:"right"}}>{fmtNum(d.value)}hs</span>
                    </div>
                  ))}
                </div>
              </div>
            </Card>
            <Card title="Horas por Equipo">
              <div style={{padding:"8px 6px"}}>
                <ResponsiveContainer width="100%" height={Math.max(160,barData.length*26+30)}>
                  <BarChart data={barData} layout="vertical" margin={{left:8,right:30}}>
                    <CartesianGrid strokeDasharray="3 3" stroke={C.border} horizontal={false}/>
                    <XAxis type="number" tick={{fill:C.textMuted,fontSize:11}} axisLine={false} tickLine={false} unit="hs"/>
                    <YAxis type="category" dataKey="maquina" tick={{fill:C.textSub,fontSize:11}} width={90} axisLine={false} tickLine={false}/>
                    <Tooltip content={({active,payload})=>{
                      if(!active||!payload?.length)return null;
                      return(<div style={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:8,padding:"8px 12px",fontSize:13}}>
                        <div style={{color:C.purple,fontWeight:700}}>{payload[0].payload.maquina}</div>
                        <div style={{color:C.accent}}>{fmtNum(payload[0].value)} hs</div>
                      </div>);
                    }}/>
                    <Bar dataKey="horas" fill={C.accent} radius={[0,4,4,0]} barSize={16}/>
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </Card>
          </div>
          <Card title="Tareas principales — 80% de las horas">
            <div style={{overflowX:"auto"}}>
              <table style={{width:"100%",borderCollapse:"collapse",fontSize:14}}>
                <thead>
                  <tr style={{background:C.surface}}>
                    {["Tarea","Horas","%","% Acum.","ML/Hs","KL/Hs","M2/Hs","M3/Hs"].map((h,i)=>(
                      <th key={i} style={{padding:"10px 14px",textAlign:i===0?"left":"center",color:C.textSub,fontWeight:600,fontSize:12,letterSpacing:".05em",textTransform:"uppercase",borderBottom:`1px solid ${C.border}`}}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {(()=>{
                    let acum=0;
                    return pieData.filter(d=>{
                      if(acum>=80)return false;
                      acum+=d.pct;
                      return true;
                    }).map((d,i)=>{
                      let acumLocal=0;
                      for(let j=0;j<=i;j++)acumLocal+=pieData[j].pct;
                      return(
                        <tr key={i} style={{background:i%2===0?"transparent":C.surface+"55"}}>
                          <td style={{padding:"10px 14px",borderBottom:`1px solid ${C.border}18`,color:C.text,fontSize:14}}>{d.name}</td>
                          <td style={{padding:"10px 14px",textAlign:"center",borderBottom:`1px solid ${C.border}18`,color:C.accent,fontWeight:600,fontSize:14}}>{fmtNum(d.value)}</td>
                          <td style={{padding:"10px 14px",textAlign:"center",borderBottom:`1px solid ${C.border}18`,color:C.text,fontWeight:700,fontSize:14}}>{d.pct}%</td>
                          <td style={{padding:"10px 14px",textAlign:"center",borderBottom:`1px solid ${C.border}18`}}>
                            <span style={{display:"inline-block",padding:"4px 14px",borderRadius:20,fontSize:13,fontWeight:700,background:acumLocal>=80?C.green+"22":C.yellow+"22",color:acumLocal>=80?C.green:C.yellow,border:`1px solid ${acumLocal>=80?C.green:C.yellow}44`}}>{Math.min(acumLocal,100).toFixed(1)}%</span>
                          </td>
                          <td style={{padding:"10px 14px",textAlign:"center",borderBottom:`1px solid ${C.border}18`,color:d.mlHs>0?C.blue:C.textMuted,fontWeight:d.mlHs>0?700:400,fontSize:14}}>{d.mlHs>0?fmtNum(d.mlHs):"—"}</td>
                          <td style={{padding:"10px 14px",textAlign:"center",borderBottom:`1px solid ${C.border}18`,color:d.klHs>0?C.blue:C.textMuted,fontWeight:d.klHs>0?700:400,fontSize:14}}>{d.klHs>0?fmtNum(d.klHs):"—"}</td>
                          <td style={{padding:"10px 14px",textAlign:"center",borderBottom:`1px solid ${C.border}18`,color:d.m2Hs>0?C.teal:C.textMuted,fontWeight:d.m2Hs>0?700:400,fontSize:14}}>{d.m2Hs>0?fmtNum(d.m2Hs):"—"}</td>
                          <td style={{padding:"10px 14px",textAlign:"center",borderBottom:`1px solid ${C.border}18`,color:d.m3Hs>0?C.purple:C.textMuted,fontWeight:d.m3Hs>0?700:400,fontSize:14}}>{d.m3Hs>0?fmtNum(d.m3Hs):"—"}</td>
                        </tr>
                      );
                    });
                  })()}
                </tbody>
              </table>
            </div>
          </Card>
                    </div>
        );
      })()}
      {mode==="dia"&&fecha&&filtered.length>0&&(()=>{
        const COLORS=["#e8001d","#3b82f6","#10b981","#f59e0b","#8b5cf6","#ec4899","#06b6d4","#f97316","#84cc16","#6366f1"];
        const tareaMap={};
        filtered.forEach(r=>{if(r.tarea)tareaMap[r.tarea]=(tareaMap[r.tarea]||0)+r.horas;});
        const totalHs=Object.values(tareaMap).reduce((s,v)=>s+v,0);
        const pieData=Object.entries(tareaMap).sort((a,b)=>b[1]-a[1]).map(([name,value])=>({name,value,pct:Math.round(value/totalHs*1000)/10}));
        return(
          <div style={{display:"grid",gridTemplateColumns:"2fr 3fr",gap:14}}>
            <Card title={`Distribución de Horas por Tarea — ${fecha}`}>
              <div style={{padding:"16px",display:"flex",gap:20,alignItems:"center"}}>
                <div style={{flexShrink:0}}>
                  <PieChart width={220} height={220}>
                    <Pie data={pieData} dataKey="value" cx="50%" cy="50%" outerRadius={100} innerRadius={44}>
                      {pieData.map((_,i)=><Cell key={i} fill={COLORS[i%COLORS.length]}/>)}
                    </Pie>
                    <Tooltip content={({active,payload})=>{
                      if(!active||!payload?.length)return null;
                      const d=payload[0].payload;
                      return(<div style={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:8,padding:"8px 12px",fontSize:12}}>
                        <div style={{color:C.text,fontWeight:600,marginBottom:4}}>{d.name}</div>
                        <div style={{color:C.accent}}>{fmtNum(d.value)} hs — {d.pct}%</div>
                      </div>);
                    }}/>
                  </PieChart>
                </div>
                <div style={{display:"flex",flexDirection:"column",gap:7,flex:1,overflow:"hidden"}}>
                  {pieData.map((d,i)=>(
                    <div key={i} style={{display:"flex",alignItems:"center",gap:8}}>
                      <div style={{width:11,height:11,borderRadius:"50%",background:COLORS[i%COLORS.length],flexShrink:0}}/>
                      <span style={{fontSize:12,color:C.textSub,flex:1,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{d.name}</span>
                      <span style={{fontSize:12,fontWeight:700,color:C.text,flexShrink:0}}>{d.pct}%</span>
                      <span style={{fontSize:11,color:C.textMuted,flexShrink:0,minWidth:32,textAlign:"right"}}>{fmtNum(d.value)}hs</span>
                    </div>
                  ))}
                </div>
              </div>
            </Card>
            <Card title={`Horas por Equipo — ${fecha}`}>
              <div style={{padding:"8px 6px"}}>
                {(()=>{
                  const maqMap={};
                  filtered.forEach(r=>{if(r.maquina)maqMap[r.maquina]=(maqMap[r.maquina]||0)+r.horas;});
                  const barData=Object.entries(maqMap).sort((a,b)=>b[1]-a[1]).map(([maquina,horas])=>({maquina,horas}));
                  return(
                    <ResponsiveContainer width="100%" height={Math.max(160,barData.length*26+30)}>
                      <BarChart data={barData} layout="vertical" margin={{left:8,right:30}}>
                        <CartesianGrid strokeDasharray="3 3" stroke={C.border} horizontal={false}/>
                        <XAxis type="number" tick={{fill:C.textMuted,fontSize:9}} axisLine={false} tickLine={false} unit="hs"/>
                        <YAxis type="category" dataKey="maquina" tick={{fill:C.textSub,fontSize:9}} width={80} axisLine={false} tickLine={false}/>
                        <Tooltip content={({active,payload})=>{
                          if(!active||!payload?.length)return null;
                          return(<div style={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:8,padding:"8px 12px",fontSize:12}}>
                            <div style={{color:C.purple,fontWeight:700}}>{payload[0].payload.maquina}</div>
                            <div style={{color:C.accent}}>{fmtNum(payload[0].value)} hs</div>
                          </div>);
                        }}/>
                        <Bar dataKey="horas" fill={C.accent} radius={[0,4,4,0]} barSize={14}/>
                      </BarChart>
                    </ResponsiveContainer>
                  );
                })()}
              </div>
            </Card>
          </div>
        );
      })()}
      <Card title={`Registros (${filtered.length})`}>
        <Table cols={cols} rows={filteredSorted} maxH={400} emptyMsg="Sin registros con los filtros seleccionados"/>
      </Card>
    </div>
  );
}

// ─── Generar PDF de reporte de Control ───────────────────────────────────────
function generarReporteControl(periodo, faltanEn05, faltanEn02){
  const fmtF=f=>{if(!f)return"—";const[y,m,d]=String(f).slice(0,10).split("-");return`${d}/${m}/${y}`;};
  const fmtN=n=>n==null?"—":Number(n).toLocaleString("es-AR",{minimumFractionDigits:1,maximumFractionDigits:1});

  const tableStyle=`border-collapse:collapse;width:100%;font-size:10px;margin-bottom:20px;`;
  const thStyle=`background:#1a1a2e;color:#fff;padding:7px 9px;text-align:left;border:1px solid #333;font-size:9px;text-transform:uppercase;letter-spacing:.05em;`;
  const tdStyle=`padding:6px 9px;border:1px solid #ddd;vertical-align:top;`;
  const trEven=`background:#f9f9f9;`;

  const buildTable=(rows,cols)=>{
    if(!rows.length)return`<p style="color:#888;font-style:italic">Sin registros</p>`;
    return`<table style="${tableStyle}">
      <thead><tr>${cols.map(c=>`<th style="${thStyle}">${c.label}</th>`).join("")}</tr></thead>
      <tbody>${rows.map((r,i)=>`<tr style="${i%2===1?trEven:""}">
        ${cols.map(c=>`<td style="${tdStyle}">${c.render?c.render(r[c.key]):r[c.key]||"—"}</td>`).join("")}
      </tr>`).join("")}</tbody>
    </table>`;
  };

  const cols05=[
    {key:"fecha",label:"Fecha",render:v=>fmtF(v)},
    {key:"proyecto",label:"Proyecto"},
    {key:"maquina",label:"Máquina"},
    {key:"parte",label:"N° Parte"},
    {key:"operario",label:"Operario"},
    {key:"supervisor",label:"Supervisor"},
    {key:"horas",label:"Horas",render:v=>fmtN(v)},
    {key:"estado",label:"Estado"},
  ];
  const cols02=[
    {key:"fecha",label:"Fecha",render:v=>fmtF(v)},
    {key:"proyecto",label:"Proyecto"},
    {key:"maquina",label:"Máquina"},
    {key:"tarea",label:"Tarea"},
    {key:"supervisor",label:"Supervisor"},
    {key:"horas",label:"Horas",render:v=>fmtN(v)},
  ];

  const html=`<!DOCTYPE html><html><head><meta charset="UTF-8">
  <title>Reporte Control de Consistencia</title>
  <style>
    body{font-family:Arial,sans-serif;margin:32px;color:#111;font-size:11px;}
    h1{font-size:18px;color:#1a1a2e;margin-bottom:4px;}
    h2{font-size:13px;color:#c00;margin:24px 0 8px;border-bottom:2px solid #c00;padding-bottom:4px;}
    .header{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:24px;border-bottom:3px solid #1a1a2e;padding-bottom:12px;}
    .badge{display:inline-block;background:#1a1a2e;color:#fff;padding:3px 10px;border-radius:4px;font-size:10px;font-weight:bold;}
    .periodo{font-size:12px;color:#444;margin-top:6px;}
    .stats{display:flex;gap:20px;margin-bottom:20px;}
    .stat{background:#f3f3f3;border-radius:6px;padding:10px 16px;text-align:center;}
    .stat .val{font-size:22px;font-weight:bold;color:#c00;}
    .stat .lbl{font-size:9px;color:#666;text-transform:uppercase;}
    @media print{body{margin:16px;}h2{page-break-before:auto;}}
  </style></head><body>
  <div class="header">
    <div>
      <h1>🔍 Reporte — Control de Consistencia</h1>
      <div class="periodo">Período analizado: <strong>${periodo}</strong></div>
      <div style="margin-top:6px;">Generado el ${new Date().toLocaleDateString("es-AR",{day:"2-digit",month:"2-digit",year:"numeric"})} a las ${new Date().toLocaleTimeString("es-AR",{hour:"2-digit",minute:"2-digit"})}</div>
    </div>
    <div class="badge">DELTA MINING OPS</div>
  </div>
  <div class="stats">
    <div class="stat"><div class="val">${faltanEn05.length}</div><div class="lbl">Sin producción en ROP05</div></div>
    <div class="stat"><div class="val">${faltanEn02.length}</div><div class="lbl">Sin parte diario en ROP02</div></div>
    <div class="stat"><div class="val">${new Set([...faltanEn05.map(r=>r.maquina),...faltanEn02.map(r=>r.maquina)]).size}</div><div class="lbl">Equipos con inconsistencias</div></div>
  </div>
  <h2>⚠ Registros en ROP02 sin producción en ROP05 (${faltanEn05.length})</h2>
  ${buildTable(faltanEn05,cols05)}
  <h2>⚠ Registros en ROP05 sin parte diario en ROP02 (${faltanEn02.length})</h2>
  ${buildTable(faltanEn02,cols02)}
  </body></html>`;

  const w=window.open("","_blank","width=900,height=700");
  w.document.write(html);
  w.document.close();
  setTimeout(()=>w.print(),600);
}


// ─── ViewControl ──────────────────────────────────────────────────────────────
function ViewControl({control,rop02All,rop05,extState,setExtState}){
  const[sub,setSub]=useState("dashboard");

  // Filtros facetados sobre el universo productivo combinado (02+05)
  // Usamos el hook sobre productivos para ROP02; para ROP05 aplicamos manualmente los mismos filtros
  const fk=useMemo(()=>[
    {key:"proyecto",defaultVal:"todos"},
    {key:"maquina",defaultVal:"todas"},
    {key:"supervisor",defaultVal:"todos"},
  ],[]);
  const{mode,setMode,fecha,setFecha,fechaD,setFechaD,fechaH,setFechaH,vals,set,reset,hayFiltros,byFecha:byFecha02,opts:opts02}=useFacetedFilters(control.productivos,fk,extState,setExtState);

  // Aplicar mismo filtro de fecha+selectores a prod05
  const byFecha05=useMemo(()=>byDateFilter(control.prod05,mode,fecha,fechaD,fechaH),[control.prod05,mode,fecha,fechaD,fechaH]);
  const filtered05=useMemo(()=>byFecha05.filter(r=>
    (vals.proyecto==="todos"||r.proyecto===vals.proyecto)&&
    (vals.maquina==="todas"||r.maquina===vals.maquina)
  ),[byFecha05,vals]);
  const filtered02=useMemo(()=>byFecha02.filter(r=>
    (vals.proyecto==="todos"||r.proyecto===vals.proyecto)&&
    (vals.maquina==="todas"||r.maquina===vals.maquina)&&
    (vals.supervisor==="todos"||r.supervisor===vals.supervisor)
  ),[byFecha02,vals]);

  // Opciones facetadas para Control: unión de 02 y 05
  const optsControl=useMemo(()=>{
    const combined=[...byFecha02,...byFecha05];
    const result={};
    fk.forEach(f=>{
      const others=fk.filter(o=>o.key!==f.key);
      result[f.key]=uniq(combined.filter(r=>
        others.every(o=>vals[o.key]===o.defaultVal||r[o.key]===vals[o.key])
      ).map(r=>r[f.key]));
    });
    return result;
  },[byFecha02,byFecha05,vals]);// eslint-disable-line

  // Recalcular inconsistencias sobre subconjunto filtrado
  const filteredData=useMemo(()=>{
    const key=r=>`${r.fecha}__${r.maquina}`;
    const set05=new Set(filtered05.map(key));
    const set02=new Set(filtered02.map(key));
    const faltanEn05=filtered02.filter(r=>!set05.has(key(r)));
    const faltanEn02=filtered05.filter(r=>!set02.has(key(r)));
    const total=filtered02.length+filtered05.length;
    const problemas=faltanEn05.length+faltanEn02.length;
    const consistencia=total>0?Math.round(((total-problemas)/total)*100):100;
    return{faltanEn05,faltanEn02,total,problemas,consistencia,prod02f:filtered02,prod05f:filtered05};
  },[filtered02,filtered05]);

  const inconsistFecha=useMemo(()=>{
    const m={};
    filteredData.faltanEn05.forEach(r=>{m[r.fecha]=m[r.fecha]||{fecha:r.fecha,sinProd:0,sinParte:0};m[r.fecha].sinProd++;});
    filteredData.faltanEn02.forEach(r=>{m[r.fecha]=m[r.fecha]||{fecha:r.fecha,sinProd:0,sinParte:0};m[r.fecha].sinParte++;});
    return Object.values(m).sort((a,b)=>a.fecha.localeCompare(b.fecha));
  },[filteredData]);

  const sem=semaforo(filteredData.consistencia);

  const FilterPanel=(
    <Card>
      <div style={{padding:"12px 14px",display:"flex",flexDirection:"column",gap:10}}>
        {/* Fila 1: tabs + botón reporte */}
        <div style={{display:"flex",gap:7,alignItems:"center",flexWrap:"wrap"}}>
          <TabBtn active={mode==="dia"} onClick={()=>setMode("dia")}>Por día</TabBtn>
          <TabBtn active={mode==="periodo"} onClick={()=>setMode("periodo")}>Por período</TabBtn>
          <button onClick={()=>generarReporteControl(
            (fecha&&mode==="dia"?fmtFecha(fecha):(fechaD||fechaH)?`${fmtFecha(fechaD)} → ${fmtFecha(fechaH)}`:"Todo el período"),
            filteredData.faltanEn05,
            filteredData.faltanEn02
          )} style={{marginLeft:8,display:"flex",alignItems:"center",gap:6,padding:"7px 14px",borderRadius:7,border:`1px solid ${C.accent}`,background:C.accentDim,color:C.accent,cursor:"pointer",fontSize:12,fontWeight:700,fontFamily:"Inter",letterSpacing:".04em"}}>
            📄 Guardar Reporte
          </button>
        </div>
        {/* Fila 2: filtros */}
        <div style={{display:"flex",flexWrap:"wrap",gap:10,alignItems:"flex-end"}}>
          {mode==="dia"?<DateIn label="Fecha" value={fecha} onChange={setFecha}/>:<><DateIn label="Desde" value={fechaD} onChange={setFechaD} max={fechaH||undefined}/><DateIn label="Hasta" value={fechaH} onChange={setFechaH} min={fechaD||undefined} warn={fechaH&&fechaD&&fechaH<fechaD?"≥ Desde":null}/></>}
          <Sel label="Proyecto" value={vals.proyecto} onChange={v=>set("proyecto",v)} options={[{value:"todos",label:"Todos"},...optsControl.proyecto.map(p=>({value:p,label:p}))]}/>
          <Sel label="Máquina" value={vals.maquina} onChange={v=>set("maquina",v)} options={[{value:"todas",label:"Todas"},...optsControl.maquina.map(m=>({value:m,label:m}))]}/>
          <button onClick={reset} style={{marginLeft:"auto",display:"flex",alignItems:"center",gap:5,padding:"6px 12px",borderRadius:7,border:`1px solid ${C.red}44`,background:C.redDim,color:C.red,cursor:"pointer",fontSize:11,fontWeight:600,fontFamily:"Inter",opacity:hayFiltros?1:0.3,pointerEvents:hayFiltros?"auto":"none"}}><Icon name="close" size={11} color={C.red}/>Limpiar filtros</button>
        </div>
        {hayFiltros&&(
          <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
            {fecha&&<Badge color={C.blue}>Fecha: {fecha}</Badge>}
            {fechaD&&<Badge color={C.blue}>Desde: {fechaD}</Badge>}
            {fechaH&&<Badge color={C.blue}>Hasta: {fechaH}</Badge>}
            {vals.proyecto!=="todos"&&<Badge color={C.accent}>Proyecto: {vals.proyecto}</Badge>}
            {vals.maquina!=="todas"&&<Badge color={C.purple}>Máquina: {vals.maquina}</Badge>}
            {vals.supervisor!=="todos"&&<Badge color={C.teal}>Supervisor: {vals.supervisor}</Badge>}
          </div>
        )}
      </div>
    </Card>
  );

  const cols1=[
    {key:"fecha",label:"Fecha",render:v=>fmtFecha(v)},
    {key:"proyecto",label:"Proyecto",render:v=><Badge color={v?.includes("FILO")?C.accent:C.teal}>{v||"—"}</Badge>},
    {key:"maquina",label:"Máquina",render:v=><Badge color={C.purple}>{v}</Badge>},
    {key:"parte",label:"N° Parte",render:v=><span style={{color:C.blue,fontWeight:600}}>{v||"—"}</span>},
    {key:"operario",label:"Operario"},{key:"supervisor",label:"Supervisor"},
    {key:"horas",label:"Horas",render:v=><span style={{color:C.accent,fontWeight:600}}>{fmtNum(v)}</span>},
    {key:"estado",label:"Estado",render:v=><Badge color={C.green}>{v||"—"}</Badge>},
    {key:"_",label:"Problema",render:()=><span style={{color:C.red,fontSize:11}}>Sin producción en ROP05</span>},
  ];
  const cols2=[
    {key:"fecha",label:"Fecha",render:v=>fmtFecha(v)},
    {key:"proyecto",label:"Proyecto",render:v=><Badge color={v?.includes("FILO")?C.accent:C.teal}>{v||"—"}</Badge>},
    {key:"maquina",label:"Máquina",render:v=><Badge color={C.purple}>{v}</Badge>},
    {key:"supervisor",label:"Supervisor"},{key:"tarea",label:"Tarea",wrap:true},
    {key:"horas",label:"Horas",render:v=><span style={{color:C.accent,fontWeight:600}}>{fmtNum(v)}</span>},
    {key:"cantidad",label:"Cantidad",render:v=>fmtNum(v)},
    {key:"unidad",label:"Unidad",render:v=><Badge color={C.teal}>{v}</Badge>},
    {key:"_",label:"Problema",render:()=><span style={{color:C.yellow,fontSize:11}}>Sin parte diario en ROP02</span>},
  ];

  return(
    <div className="fade-in" style={{display:"flex",flexDirection:"column",gap:14}}>
      <div style={{borderBottom:`1px solid ${C.border}`,paddingBottom:2}}>
        <SubTab active={sub==="dashboard"} onClick={()=>setSub("dashboard")}>Dashboard</SubTab>
        <SubTab active={sub==="sinprod"} onClick={()=>setSub("sinprod")}>Sin producción ({filteredData.faltanEn05.length})</SubTab>
        <SubTab active={sub==="sinparte"} onClick={()=>setSub("sinparte")}>Sin parte diario ({filteredData.faltanEn02.length})</SubTab>
      </div>
      {FilterPanel}
      <AlertBanner type="info">Camionetas, camiones y equipos auxiliares están excluidos de este análisis.</AlertBanner>

      {sub==="dashboard"&&(
        <div style={{display:"flex",flexDirection:"column",gap:14}}>
          <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(130px,1fr))",gap:10}}>
            <StatCard icon="consist" label="Partes Consistentes" value={fmtPct(filteredData.consistencia)} sub={sem.label} color={sem.color} small/>
            <StatCard icon="alert" label="Problemas" value={filteredData.problemas} sub="registros" color={C.red} small/>
            <StatCard icon="warn" label="Supervisor c/ más faltas" value={(()=>{
              const m={};
              filteredData.faltanEn05.forEach(r=>{if(r.supervisor)m[r.supervisor]=(m[r.supervisor]||0)+1;});
              const top=Object.entries(m).sort((a,b)=>b[1]-a[1])[0];
              return top?top[0]:"—";
            })()} sub={(()=>{
              const m={};
              filteredData.faltanEn05.forEach(r=>{if(r.supervisor)m[r.supervisor]=(m[r.supervisor]||0)+1;});
              const top=Object.entries(m).sort((a,b)=>b[1]-a[1])[0];
              return top?`${top[1]} registros sin carga`:"sin datos";
            })()} color={C.red} small/>
            <StatCard icon="warn" label="Equipos con problemas" value={uniq([...filteredData.faltanEn05.map(r=>r.maquina),...filteredData.faltanEn02.map(r=>r.maquina)]).length} sub="con inconsistencias" color={C.red} small/>
            <StatCard icon="warn" label="Sin producción" value={filteredData.faltanEn05.length} sub="→ ROP05 faltante" color={C.red} small/>
            <StatCard icon="warn" label="Sin parte diario" value={filteredData.faltanEn02.length} sub="→ ROP02 faltante" color={C.yellow} small/>
          </div>
          <div style={{display:"grid",gridTemplateColumns:"2fr 3fr",gap:14}}>
            <Card title="Índice de Consistencia">
              <div style={{padding:"20px 24px",display:"flex",alignItems:"center",gap:24}}>
                <div style={{width:108,height:108,borderRadius:"50%",border:`5px solid ${sem.color}`,background:sem.dim,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",boxShadow:`0 0 32px ${sem.color}33`,flexShrink:0}}>
                  <span style={{fontFamily:"Inter",fontSize:28,fontWeight:800,color:sem.color}}>{filteredData.consistencia}%</span>
                  <span style={{fontSize:9,color:sem.color,fontWeight:700,letterSpacing:".1em"}}>{sem.label}</span>
                </div>
                <div style={{flex:1}}>
                  <div style={{fontFamily:"Inter",fontSize:14,fontWeight:700,color:C.text,marginBottom:8}}>Compara ROP02 productivos vs ROP05</div>
                  <p style={{fontSize:12,color:C.textSub,lineHeight:1.6,marginBottom:12}}>Cruce por <strong style={{color:C.text}}>fecha + máquina</strong>. Excluye camionetas y auxiliares.</p>
                  <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:8}}>
                    {[{l:"Total",v:filteredData.total,c:C.blue},{l:"Problemas",v:filteredData.problemas,c:C.red},{l:"OK",v:filteredData.total-filteredData.problemas,c:C.green}].map(({l,v,c})=>(
                      <div key={l} style={{background:c+"15",borderRadius:8,padding:"10px 12px",border:`1px solid ${c}33`}}>
                        <div style={{fontFamily:"Inter",fontSize:20,fontWeight:800,color:c}}>{v}</div>
                        <div style={{fontSize:10,color:C.textMuted}}>{l}</div>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </Card>
            <Card title="Umbrales">
              <div style={{padding:14,display:"flex",flexDirection:"column",gap:8}}>
                {[["≥ 90%","ÓPTIMO",C.green],["70–89%","ATENCIÓN",C.yellow],["< 70%","CRÍTICO",C.red]].map(([r,l,c])=>(
                  <div key={l} style={{background:c+"15",borderRadius:8,padding:"10px 14px",border:`1px solid ${c}33`,display:"flex",alignItems:"center",justifyContent:"space-between"}}>
                    <span style={{fontFamily:"Inter",fontSize:16,fontWeight:800,color:c}}>{r}</span><Badge color={c}>{l}</Badge>
                  </div>
                ))}
              </div>
            </Card>
          </div>
          {inconsistFecha.length>0&&(
            <Card title="Inconsistencias por fecha">
              <div style={{padding:"10px 6px"}}>
                <ResponsiveContainer width="100%" height={180}>
                  <BarChart data={inconsistFecha} margin={{left:0,right:16}}>
                    <CartesianGrid strokeDasharray="3 3" stroke={C.border} vertical={false}/>
                    <XAxis dataKey="fecha" tick={{fill:C.textMuted,fontSize:9}} axisLine={false} tickLine={false}/>
                    <YAxis tick={{fill:C.textMuted,fontSize:10}} axisLine={false} tickLine={false} allowDecimals={false}/>
                    <Tooltip content={<ChartTip/>}/>
                    <Bar dataKey="sinProd" name="Sin producción" fill={C.red} radius={[4,4,0,0]} stackId="a"/>
                    <Bar dataKey="sinParte" name="Sin parte diario" fill={C.yellow} radius={[4,4,0,0]} stackId="a"/>
                    <Legend iconSize={8} wrapperStyle={{fontSize:10,color:C.textSub}}/>
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </Card>
          )}
          {filteredData.faltanEn05.length+filteredData.faltanEn02.length>0&&(
            <Card title="Máquinas con más inconsistencias">
              <div style={{padding:"12px 6px"}}>
                {(()=>{
                  const m={};
                  filteredData.faltanEn05.forEach(r=>{m[r.maquina]=m[r.maquina]||{maq:r.maquina,sinProd:0,sinParte:0};m[r.maquina].sinProd++;});
                  filteredData.faltanEn02.forEach(r=>{m[r.maquina]=m[r.maquina]||{maq:r.maquina,sinProd:0,sinParte:0};m[r.maquina].sinParte++;});
                  const top=Object.values(m).sort((a,b)=>(b.sinProd+b.sinParte)-(a.sinProd+a.sinParte)).slice(0,10);
                  return(
                    <ResponsiveContainer width="100%" height={Math.max(160,top.length*28)}>
                      <BarChart data={top} layout="vertical" margin={{left:8,right:16}}>
                        <CartesianGrid strokeDasharray="3 3" stroke={C.border} horizontal={false}/>
                        <XAxis type="number" tick={{fill:C.textMuted,fontSize:10}} axisLine={false} tickLine={false} allowDecimals={false}/>
                        <YAxis type="category" dataKey="maq" tick={{fill:C.textSub,fontSize:10}} width={84} axisLine={false} tickLine={false}/>
                        <Tooltip content={<ChartTip/>}/>
                        <Bar dataKey="sinProd" name="Sin producción" fill={C.red} radius={[0,4,4,0]} stackId="a"/>
                        <Bar dataKey="sinParte" name="Sin parte diario" fill={C.yellow} radius={[0,4,4,0]} stackId="a"/>
                        <Legend iconSize={8} wrapperStyle={{fontSize:10,color:C.textSub}}/>
                      </BarChart>
                    </ResponsiveContainer>
                  );
                })()}
              </div>
            </Card>
          )}
          <Card title="Reglas de Validación">
            <div style={{padding:14,display:"flex",flexDirection:"column",gap:9}}>
              {[["1","Máquina productiva en ROP02 → debe estar en ROP05",C.green],["2","Máquina en ROP05 → debe existir en ROP02",C.green],["3","Camionetas, camiones y auxiliares → excluidos del control",C.blue],["4","Comparación por fecha + máquina",C.blue],["5","Sin producción registrada → inconsistencia tipo A",C.yellow],["6","Sin parte diario → inconsistencia tipo B",C.yellow]].map(([n,d,c])=>(
                <div key={n} style={{display:"flex",gap:8,alignItems:"flex-start"}}>
                  <span style={{width:20,height:20,borderRadius:"50%",background:c+"22",border:`1px solid ${c}44`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:10,fontWeight:700,color:c,flexShrink:0}}>{n}</span>
                  <span style={{fontSize:12,color:C.textSub,lineHeight:1.5}}>{d}</span>
                </div>
              ))}
            </div>
          </Card>
        </div>
      )}
      {sub==="sinprod"&&(
        <div style={{display:"flex",flexDirection:"column",gap:12}}>
          {filteredData.faltanEn05.length>0
            ?<AlertBanner type="error">{filteredData.faltanEn05.length} máquinas productivas en ROP02 sin producción en ROP05.</AlertBanner>
            :<AlertBanner type="success">Sin inconsistencias con los filtros actuales.</AlertBanner>}
          <Card title={`Sin producción en ROP05 (${filteredData.faltanEn05.length})`}>
            <Table cols={cols1} rows={filteredData.faltanEn05} maxH={500} emptyMsg="Sin inconsistencias"/>
          </Card>
        </div>
      )}
      {sub==="sinparte"&&(
        <div style={{display:"flex",flexDirection:"column",gap:12}}>
          {filteredData.faltanEn02.length>0
            ?<AlertBanner type="warn">{filteredData.faltanEn02.length} registros de ROP05 sin parte diario en ROP02.</AlertBanner>
            :<AlertBanner type="success">Sin inconsistencias con los filtros actuales.</AlertBanner>}
          <Card title={`Sin parte diario en ROP02 (${filteredData.faltanEn02.length})`}>
            <Table cols={cols2} rows={filteredData.faltanEn02} maxH={500} emptyMsg="Sin inconsistencias"/>
          </Card>
        </div>
      )}
    </div>
  );
}

// ─── ErrorScreen ──────────────────────────────────────────────────────────────
function ErrorScreen({errors,onRetry}){
  return(
    <div style={{display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",height:"60vh",gap:20,textAlign:"center",padding:24}}>
      <div style={{width:56,height:56,borderRadius:"50%",background:C.redDim,border:`2px solid ${C.red}44`,display:"flex",alignItems:"center",justifyContent:"center"}}>
        <Icon name="warn" size={26} color={C.red}/>
      </div>
      <div>
        <div style={{fontFamily:"Inter",fontSize:16,fontWeight:700,color:C.red,marginBottom:8}}>Error al cargar datos</div>
        <div style={{display:"flex",flexDirection:"column",gap:6,maxWidth:480}}>
          {errors.map((e,i)=>(
            <div key={i} style={{background:C.redDim,border:`1px solid ${C.red}33`,borderRadius:8,padding:"10px 14px",textAlign:"left"}}>
              <div style={{fontSize:11,color:C.red,fontWeight:600}}>{e.source}</div>
              <div style={{fontSize:12,color:C.textSub,marginTop:2}}>{e.message}</div>
            </div>
          ))}
        </div>
      </div>
      <button onClick={onRetry} style={{padding:"9px 18px",borderRadius:8,border:`1px solid ${C.accent}44`,background:C.accentDim,color:C.accent,fontFamily:"Inter",fontWeight:600,fontSize:13,cursor:"pointer",display:"flex",alignItems:"center",gap:6}}>
        <Icon name="refresh" size={14} color={C.accent}/> Reintentar
      </button>
    </div>
  );
}

// ─── ViewVehiculos ────────────────────────────────────────────────────────────
function ViewVehiculos({rop02All,extState,setExtState}){
  // Solo camionetas y camiones
  const rop02Veh=useMemo(()=>rop02All.filter(r=>isExcluded(r.maquina)),[rop02All]);

  const fk=useMemo(()=>[
    {key:"proyecto",defaultVal:"todos"},
    {key:"maquina",defaultVal:"todas"},
    {key:"supervisor",defaultVal:"todos"},
    {key:"operario",defaultVal:"todos"},
  ],[]);
  const{mode,setMode,fecha,setFecha,fechaD,setFechaD,fechaH,setFechaH,filtered:filteredBase,opts,vals,set,reset,hayFiltros}=useFacetedFilters(rop02Veh,fk,extState,setExtState);

  const[estado,setEstado]=useState("todos");
  const filtered=useMemo(()=>{
    if(estado==="todos")return filteredBase;
    return filteredBase.filter(r=>r.estado===estado);
  },[filteredBase,estado]);

  const stats=useMemo(()=>({
    horas:filtered.reduce((s,r)=>s+r.horas,0),
    comb:filtered.reduce((s,r)=>s+r.combustible,0),
    equipos:uniq(filtered.map(r=>r.maquina)).length,
    ops:uniq(filtered.map(r=>r.operario)).length,
    prod:filtered.filter(r=>r.estado==="TRABAJO").length,
    od:filtered.filter(r=>r.estado==="OD").length,
    fs:filtered.filter(r=>r.estado==="FS").length,
  }),[filtered]);

  const horasFecha=useMemo(()=>{
    if(mode!=="periodo")return[];
    const m={};filtered.forEach(r=>{m[r.fecha]=(m[r.fecha]||0)+r.horas;});
    return Object.entries(m).sort().map(([fecha,horas])=>({fecha,horas}));
  },[filtered,mode]);

  const cols=useMemo(()=>[
    {key:"fecha",label:"Fecha",render:v=>fmtFecha(v)},
    {key:"maquina",label:"Vehículo",render:v=><Badge color={C.teal}>{v}</Badge>},
    {key:"operario",label:"Operario"},
    {key:"supervisor",label:"Supervisor"},
    {key:"tipo_trabajo",label:"Tarea",render:v=><span style={{display:"block",maxWidth:260,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}} title={v}>{v||"—"}</span>},
    {key:"horas",label:"Km",render:v=><span style={{color:C.accent,fontWeight:600}}>{fmtNum(v)}</span>},
    {key:"combustible",label:"Comb.",render:v=>fmtNum(v)},
    {key:"estado",label:"Estado",render:v=><Badge color={v==="FS"?C.red:v==="OD"?C.yellow:C.green}>{v==="OD"?"OD":v||"—"}</Badge>},
    {key:"proyecto",label:"Proyecto",render:v=><Badge color={v?.includes("FILO")?C.accent:C.teal}>{v||"—"}</Badge>},
  ],[]);

  const filteredSorted=useMemo(()=>[...filtered].sort((a,b)=>b.fecha.localeCompare(a.fecha)),[filtered]);

  return(
    <div className="fade-in" style={{display:"flex",flexDirection:"column",gap:14}}>
      <Card>
        <div style={{padding:"12px 14px",display:"flex",flexDirection:"column",gap:10}}>
          <div style={{display:"flex",gap:7}}>
            <TabBtn active={mode==="dia"} onClick={()=>setMode("dia")}>Por día</TabBtn>
            <TabBtn active={mode==="periodo"} onClick={()=>setMode("periodo")}>Por período</TabBtn>
          </div>
          <div style={{display:"flex",flexWrap:"wrap",gap:10,alignItems:"flex-end"}}>
            {mode==="dia"?<DateIn label="Fecha" value={fecha} onChange={setFecha}/>:<><DateIn label="Desde" value={fechaD} onChange={setFechaD} max={fechaH||undefined}/><DateIn label="Hasta" value={fechaH} onChange={setFechaH} min={fechaD||undefined} warn={fechaH&&fechaD&&fechaH<fechaD?"≥ Desde":null}/></>}
            <Sel label="Proyecto" value={vals.proyecto} onChange={v=>set("proyecto",v)} options={[{value:"todos",label:"Todos"},...opts.proyecto.map(p=>({value:p,label:p}))]}/>
            <Sel label="Vehículo" value={vals.maquina} onChange={v=>set("maquina",v)} options={[{value:"todas",label:"Todos"},...opts.maquina.map(m=>({value:m,label:m}))]}/>
            <Sel label="Supervisor" value={vals.supervisor} onChange={v=>set("supervisor",v)} options={[{value:"todos",label:"Todos"},...opts.supervisor.map(s=>({value:s,label:s}))]}/>
            <Sel label="Operario" value={vals.operario} onChange={v=>set("operario",v)} options={[{value:"todos",label:"Todos"},...opts.operario.map(o=>({value:o,label:o}))]}/>
            <Sel label="Estado" value={estado} onChange={setEstado} options={[
              {value:"todos",label:"Todos"},
              {value:"TRABAJO",label:"✅ Trabajo efectivo"},
              {value:"OD",label:"🟡 Operativo a Disposición"},
              {value:"FS",label:"🔴 Fuera de servicio"},
            ]}/>
          <button onClick={reset} style={{marginLeft:"auto",display:"flex",alignItems:"center",gap:5,padding:"6px 12px",borderRadius:7,border:`1px solid ${C.red}44`,background:C.redDim,color:C.red,cursor:"pointer",fontSize:11,fontWeight:600,fontFamily:"Inter",opacity:hayFiltros?1:0.3,pointerEvents:hayFiltros?"auto":"none"}}><Icon name="close" size={11} color={C.red}/>Limpiar filtros</button>
          </div>
        </div>
      </Card>

      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(120px,1fr))",gap:10}}>
        <StatCard icon="hours" label="Kilómetros" value={fmtNum(stats.horas)} color={C.yellow} small/>
        <StatCard icon="fuel" label="Combustible" value={fmtNum(stats.comb)} color={C.teal} small/>
        <StatCard icon="equip" label="Vehículos" value={stats.equipos} color={C.purple} small/>
        <StatCard icon="parts" label="Operarios" value={stats.ops} color={C.blue} small/>
        <StatCard icon="check" label="Productivos" value={stats.prod} color={C.green} small/>
        <StatCard icon="parts" label="Días OD" value={stats.od} color={C.yellow} small/>
        <StatCard icon="warn" label="Días FS" value={stats.fs} color={C.red} small/>
      </div>

      {mode==="periodo"&&horasFecha.length>0&&(
        <Card title="Kilómetros por Fecha">
          <div style={{padding:"10px 6px"}}>
            <ResponsiveContainer width="100%" height={160}>
              <AreaChart data={horasFecha} margin={{left:0,right:10}}>
                <defs><linearGradient id="gv" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor={C.teal} stopOpacity={.3}/><stop offset="95%" stopColor={C.teal} stopOpacity={0}/></linearGradient></defs>
                <CartesianGrid strokeDasharray="3 3" stroke={C.border} vertical={false}/>
                <XAxis dataKey="fecha" tick={{fill:C.textMuted,fontSize:9}} axisLine={false} tickLine={false}/>
                <YAxis tick={{fill:C.textMuted,fontSize:10}} axisLine={false} tickLine={false}/>
                <Tooltip content={<ChartTip/>}/>
                <Area type="monotone" dataKey="horas" stroke={C.teal} fill="url(#gv)" name="Kilómetros" strokeWidth={2}/>
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </Card>
      )}

      {mode==="periodo"&&(
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12}}>
          {["FILO DEL SOL","JOSE MARIA"].map((p,i)=>{
            const rows=filtered.filter(r=>r.proyecto===p);
            return(
              <Card key={p} style={{borderColor:(i===0?C.accent:C.teal)+"44"}}>
                <div style={{padding:"12px 16px"}}>
                  <Badge color={i===0?C.accent:C.teal}>{p}</Badge>
                  <div style={{marginTop:10,display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
                    {[
                      [fmtNum(rows.reduce((s,r)=>s+r.horas,0)),"km",i===0?C.accent:C.teal],
                      [fmtNum(rows.reduce((s,r)=>s+r.combustible,0)),"combustible",C.teal],
                      [rows.length,"registros",C.blue],
                      [uniq(rows.map(r=>r.maquina)).length,"vehículos",C.purple],
                    ].map(([v,l,c],j)=>(
                      <div key={j}><div style={{fontFamily:"Inter",fontSize:18,fontWeight:800,color:c}}>{v}</div><div style={{fontSize:10,color:C.textMuted}}>{l}</div></div>
                    ))}
                  </div>
                </div>
              </Card>
            );
          })}
        </div>
      )}

      <Card title={`Registros (${filtered.length})`}>
        <Table cols={cols} rows={filteredSorted} maxH={400} emptyMsg="Sin registros con los filtros seleccionados"/>
      </Card>

      <Card title="Flota de Vehículos" style={{overflow:"visible"}}>
        <div style={{padding:"14px 16px",display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(160px,1fr))",gap:12}}>
          {[
            {img:VEH_CAMIONETA, nombre:"Camioneta",      prefijos:["CTA"]},
            {img:VEH_VOLCADOR,  nombre:"Camión Volcador", prefijos:["CAV"]},
            {img:VEH_REGADOR,   nombre:"Camión Regador",  prefijos:["CAR","CAA"]},
            {img:VEH_TRACTOR,   nombre:"Camión Tractor",  prefijos:["CAT"]},
          ].map(tipo=>(
            <EquipoCard key={tipo.nombre} {...tipo} rop02Prod={filtered}/>
          ))}
        </div>
      </Card>
    </div>
  );
}


// ─── ViewCHC — Indicador Control de Horas Contratadas ────────────────────────
function ViewCHC({rop02All}){
  const rop02Prod=useMemo(()=>rop02All.filter(r=>!isExcluded(r.maquina)),[rop02All]);
  const[proyecto,setProyecto]=useState("todos");
  const[mesSelec,setMesSelec]=useState(""); // formato "YYYY-MM" del mes nominal
  const HS_MES=180;

  // Meses disponibles: lista fija de nombres
  const MESES=["Enero","Febrero","Marzo","Abril","Mayo","Junio","Julio","Agosto","Septiembre","Octubre","Noviembre","Diciembre"];

  // Años disponibles a partir de los datos
  const años=useMemo(()=>{
    const ys=new Set(["2025","2026"]); // años mínimos garantizados
    rop02All.forEach(r=>{if(r.fecha)ys.add(r.fecha.slice(0,4));});
    return [...ys].sort();
  },[rop02All]);

  const[añoSelec,setAñoSelec]=useState(()=>new Date().getFullYear().toString());
  const[mesIdx,setMesIdx]=useState(()=>new Date().getMonth()); // 0=Enero

  const proyectos=useMemo(()=>uniq(rop02All.filter(r=>!isExcluded(r.maquina)).map(r=>r.proyecto)),[rop02All]);

  // Calcular fechaD y fechaH a partir del mes/año seleccionado
  // El período es del 26 del mes anterior al 25 del mes seleccionado
  // Ej: Mayo = del 26/04 al 25/05
  const{fechaD,fechaH,diasPeriodo}=useMemo(()=>{
    const y=parseInt(añoSelec);
    const m=mesIdx; // 0=Enero
    // Inicio: 26 del mes anterior al mes seleccionado
    // Si enero (m=0): inicio = 26/12 del año anterior
    const mesAnteriorNum=m===0?12:m;          // número de mes (1-12) del mes anterior
    const añoInicio=m===0?y-1:y;             // año del inicio
    const dD=`${añoInicio}-${String(mesAnteriorNum).padStart(2,"0")}-26`;
    // Fin: 25 del mes seleccionado en el año seleccionado
    const dH=`${y}-${String(m+1).padStart(2,"0")}-25`;
    const dias=Math.round((new Date(dH)-new Date(dD))/(1000*60*60*24))+1;
    return{fechaD:dD,fechaH:dH,diasPeriodo:dias};
  },[añoSelec,mesIdx]);

  // Base: solo equipos productivos filtrados por proyecto y período
  const base=useMemo(()=>rop02All.filter(r=>{
    if(isExcluded(r.maquina))return false;
    if(proyecto!=="todos"&&r.proyecto!==proyecto)return false;
    if(r.fecha<fechaD||r.fecha>fechaH)return false;
    return true;
  }),[rop02All,proyecto,fechaD,fechaH]);

  // Agrupar por máquina y calcular métricas
  const rows=useMemo(()=>{
    const m={};
    base.forEach(r=>{
      if(!m[r.maquina])m[r.maquina]={
        maquina:r.maquina,
        proyecto:r.proyecto,
        fechas:[],
        horasTrabajo:0,
        diasFS:0,
        diasOD:0,
        diasFaltaOp:0,
      };
      const eq=m[r.maquina];
      eq.fechas.push(r.fecha);
      if(r.estado==="TRABAJO")eq.horasTrabajo+=r.horas;
      else if(r.estado==="FS")eq.diasFS+=1;
      else if(r.estado==="OD")eq.diasOD+=1;
    });

    return Object.values(m).map(eq=>{
      const fechasOrd=[...new Set(eq.fechas)].sort();
      const primerRegistro=fechasOrd[0]||fechaD;
      const ultimaFecha=fechasOrd[fechasOrd.length-1]||fechaH;
      // Fecha inicio: la más tardía entre el inicio del período y el primer registro del equipo
      const fechaInicio=primerRegistro>fechaD?primerRegistro:fechaD;
      // Fecha fin: la más temprana entre el fin del período y el último registro del equipo
      const fechaFin=ultimaFecha<fechaH?ultimaFecha:fechaH;
      // Días totales del equipo en el período (por diferencia de fechas)
      const diasTotalesEquipo=fechaInicio&&fechaFin?
        Math.round((new Date(fechaFin)-new Date(fechaInicio))/(1000*60*60*24))+1:diasPeriodo;
      // diasEfectivos (trabajo + OD) = días totales - días FS
      // Garantiza que diasEfectivos + diasFS = diasTotalesEquipo
      const diasEfectivos=Math.max(0, diasTotalesEquipo-eq.diasFS);
      // Horas contratadas proporcionales a días trabajados
      // Rodillos compactadores en FILO DEL SOL tienen 100hs, en JOSE MARIA 180hs
      const esRodillo=/^(ROD|RPC|RCP)/.test(eq.maquina);
      const esFilo=eq.proyecto==="FILO DEL SOL";
      const HS_EQUIPO=esRodillo&&esFilo?100:HS_MES;
      // Hs contratadas = (hs_equipo / días_período) × días_totales_equipo (fecha inicio a fecha fin)
      const hsContratadas=diasPeriodo>0?Math.round((HS_EQUIPO/diasPeriodo)*diasTotalesEquipo*10)/10:HS_EQUIPO;
      const diasEfectivosYOD=diasEfectivos;
      // Horas OD = días OD × (180hs / días del período)
      const hsOD=diasPeriodo>0?Math.round((HS_EQUIPO/diasPeriodo)*eq.diasOD*10)/10:0;
      // % CHC = (hs trabajadas + hs OD) / hs contratadas
      const pct=hsContratadas>0?Math.round(((eq.horasTrabajo+hsOD)/hsContratadas)*1000)/10:0;
      return{
        ...eq,
        fechaInicio,
        fechaFin,
        diasEfectivos:diasEfectivosYOD,
        hsOD,
        hsContratadas,
        pct,
      };
    }).sort((a,b)=>a.maquina.localeCompare(b.maquina));
  },[base,fechaD,fechaH,diasPeriodo]);

  // Totales
  const totales=useMemo(()=>{
    const horasTrabajo=rows.reduce((s,r)=>s+r.horasTrabajo,0);
    const hsOD=Math.round(rows.reduce((s,r)=>s+r.hsOD,0)*10)/10;
    const hsContratadas=Math.round(rows.reduce((s,r)=>s+r.hsContratadas,0)*10)/10;
    const pct=hsContratadas>0?Math.round(((horasTrabajo+hsOD)/hsContratadas)*1000)/10:0;
    return{
      horasTrabajo,
      diasFS:rows.reduce((s,r)=>s+r.diasFS,0),
      diasOD:rows.reduce((s,r)=>s+r.diasOD,0),
      hsOD,
      hsContratadas,
      pct,
    };
  },[rows]);

  const semPct=(p)=>{
    if(p>=90)return{color:C.green,bg:C.greenDim};
    if(p>=70)return{color:C.yellow,bg:C.yellowDim};
    return{color:C.red,bg:C.redDim};
  };



  return(
    <div className="fade-in" style={{display:"flex",flexDirection:"column",gap:14}}>
      {/* Filtros */}
      <Card>
        <div style={{padding:"12px 14px",display:"flex",flexWrap:"wrap",alignItems:"flex-end",gap:12}}>
          <Icon name="filter" size={14} color={C.textSub}/>
          <Sel label="Mes" value={String(mesIdx)} onChange={v=>setMesIdx(Number(v))}
            options={MESES.map((m,i)=>({value:String(i),label:m}))}/>
          <Sel label="Año" value={añoSelec} onChange={setAñoSelec}
            options={años.map(y=>({value:y,label:y}))}/>
          <div style={{display:"flex",flexDirection:"column",gap:3}}>
            <label style={{fontSize:10,color:C.textMuted,fontWeight:600,letterSpacing:".06em",textTransform:"uppercase"}}>Período</label>
            <div style={{fontSize:12,color:C.textSub,padding:"7px 10px",background:C.surface,border:`1px solid ${C.border}`,borderRadius:7,whiteSpace:"nowrap"}}>
              {fmtFecha(fechaD)} → {fmtFecha(fechaH)}
            </div>
          </div>
          <Sel label="Proyecto" value={proyecto} onChange={setProyecto}
            options={[{value:"todos",label:"Todos"},...proyectos.map(p=>({value:p,label:p}))]}/>
        </div>
      </Card>

      {/* KPIs */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(140px,1fr))",gap:10}}>
        <StatCard icon="equip" label="Equipos" value={rows.length} color={C.purple} small/>
        <StatCard icon="hours" label="Hs Trabajadas" value={fmtNum(totales.horasTrabajo)} color={C.accent} small/>
        <StatCard icon="hours" label="Hs Contratadas" value={fmtNum(totales.hsContratadas)} color={C.blue} small/>
        <StatCard icon="warn" label="Días FS Total" value={totales.diasFS} color={C.red} small/>
        <StatCard icon="parts" label="Días OD Total" value={totales.diasOD} color={C.yellow} small/>
        <StatCard icon="prod" label="% Cumplimiento" value={`${totales.pct}%`} sub={totales.pct>=90?"ÓPTIMO":totales.pct>=70?"ATENCIÓN":"CRÍTICO"} color={semPct(totales.pct).color} small/>
      </div>


      {/* Tabla */}
      <Card title={`Control de Horas Contratadas (${rows.length} equipos)`} action={
        <button onClick={()=>{const label=`${MESES[mesIdx]}_${añoSelec}`;generarExcelICHC(rows,totales,label);}} style={{display:"flex",alignItems:"center",gap:5,padding:"5px 12px",borderRadius:7,border:`1px solid ${C.teal}44`,background:C.tealDim,color:C.teal,cursor:"pointer",fontSize:11,fontWeight:600,fontFamily:"Inter"}}>⬇ Excel</button>
      }>
        <div style={{overflowX:"auto"}}>
          <table style={{width:"100%",borderCollapse:"collapse",fontSize:13}}>
            <thead>
              <tr style={{background:C.surface}}>
                {["Máquina","Proyecto","Hs Efectivas","Fecha Inicio","Fecha Fin","Días Efect.+OD","Días FS","Días OD","Hs Op. a Disposición","Días Sin Operador","Hs Contratadas","% CHC"].map((h,i)=>(
                  <th key={i} style={{padding:"9px 10px",textAlign:i>=2?"center":"left",color:C.textSub,fontWeight:600,fontSize:11,letterSpacing:".04em",textTransform:"uppercase",borderBottom:`1px solid ${C.border}`,whiteSpace:"nowrap",position:"sticky",top:0,background:C.surface}}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {rows.length===0?(
                <tr><td colSpan={11} style={{padding:28,textAlign:"center",color:C.textMuted}}>Sin datos para el período seleccionado</td></tr>
              ):rows.map((r,i)=>{
                const sem=semPct(r.pct);
                return(
                  <tr key={r.maquina} style={{background:i%2===0?"transparent":C.surface+"66"}}>
                    <td style={{padding:"8px 10px",borderBottom:`1px solid ${C.border}18`}}><Badge color={C.purple}>{r.maquina}</Badge></td>
                    <td style={{padding:"8px 10px",borderBottom:`1px solid ${C.border}18`}}><Badge color={r.proyecto?.includes("FILO")?C.accent:C.teal}>{r.proyecto||"—"}</Badge></td>
                    <td style={{padding:"8px 10px",textAlign:"center",borderBottom:`1px solid ${C.border}18`,color:C.accent,fontWeight:700}}>{fmtNum(r.horasTrabajo)}</td>
                    <td style={{padding:"8px 10px",textAlign:"center",borderBottom:`1px solid ${C.border}18`,color:C.textSub}}>{fmtFecha(r.fechaInicio)}</td>
                    <td style={{padding:"8px 10px",textAlign:"center",borderBottom:`1px solid ${C.border}18`,color:C.textSub}}>{fmtFecha(r.fechaFin)}</td>
                    <td style={{padding:"8px 10px",textAlign:"center",borderBottom:`1px solid ${C.border}18`,color:C.text,fontWeight:600}}>{r.diasEfectivos}</td>
                    <td style={{padding:"8px 10px",textAlign:"center",borderBottom:`1px solid ${C.border}18`,color:r.diasFS>0?C.red:C.textMuted,fontWeight:r.diasFS>0?700:400}}>{r.diasFS||"—"}</td>
                    <td style={{padding:"8px 10px",textAlign:"center",borderBottom:`1px solid ${C.border}18`,color:r.diasOD>0?C.yellow:C.textMuted,fontWeight:r.diasOD>0?700:400}}>{r.diasOD||"—"}</td>
                    <td style={{padding:"8px 10px",textAlign:"center",borderBottom:`1px solid ${C.border}18`,color:r.hsOD>0?C.yellow:C.textMuted,fontWeight:r.hsOD>0?700:400}}>{r.hsOD>0?fmtNum(r.hsOD):"—"}</td>
                    <td style={{padding:"8px 10px",textAlign:"center",borderBottom:`1px solid ${C.border}18`,color:r.diasFaltaOp>0?C.purple:C.textMuted}}>{r.diasFaltaOp||"—"}</td>
                    <td style={{padding:"8px 10px",textAlign:"center",borderBottom:`1px solid ${C.border}18`,color:C.blue,fontWeight:600}}>{fmtNum(r.hsContratadas)}</td>
                    <td style={{padding:"8px 10px",textAlign:"center",borderBottom:`1px solid ${C.border}18`}}>
                      <span style={{display:"inline-block",padding:"3px 10px",borderRadius:20,fontSize:11,fontWeight:700,color:sem.color,background:sem.bg,border:`1px solid ${sem.color}44`}}>{r.pct}%</span>
                    </td>
                  </tr>
                );
              })}
              {/* Fila de totales */}
              {rows.length>0&&(
                <tr style={{background:C.surface,borderTop:`2px solid ${C.border}`}}>
                  <td colSpan={2} style={{padding:"10px 10px",fontFamily:"Inter",fontWeight:700,color:C.text}}>TOTAL</td>
                  <td style={{padding:"10px",textAlign:"center",fontFamily:"Inter",fontWeight:800,color:C.accent}}>{fmtNum(totales.horasTrabajo)}</td>
                  <td colSpan={2}/>
                  <td style={{padding:"10px",textAlign:"center",fontFamily:"Inter",fontWeight:700,color:C.text}}/>
                  <td style={{padding:"10px",textAlign:"center",fontFamily:"Inter",fontWeight:700,color:C.red}}>{totales.diasFS||"—"}</td>
                  <td style={{padding:"10px",textAlign:"center",fontFamily:"Inter",fontWeight:700,color:C.yellow}}>{totales.diasOD||"—"}</td>
                  <td style={{padding:"10px",textAlign:"center",fontFamily:"Inter",fontWeight:700,color:C.yellow}}>{totales.hsOD>0?fmtNum(totales.hsOD):"—"}</td>
                  <td/>
                  <td style={{padding:"10px",textAlign:"center",fontFamily:"Inter",fontWeight:800,color:C.blue}}>{fmtNum(totales.hsContratadas)}</td>
                  <td style={{padding:"10px",textAlign:"center"}}>
                    <span style={{display:"inline-block",padding:"3px 10px",borderRadius:20,fontSize:12,fontWeight:800,color:semPct(totales.pct).color,background:semPct(totales.pct).bg,border:`1px solid ${semPct(totales.pct).color}44`}}>{totales.pct}%</span>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </Card>

      {/* ── Dashboards ICHC ─────────────────────────────────────────────── */}
      {/* 1. Gauge general — ancho completo */}
      <Card title="Cumplimiento General — % CHC">
        <div style={{padding:"20px 16px",display:"flex",alignItems:"center",gap:24,flexWrap:"wrap",justifyContent:"center"}}>
          {(()=>{
            const sem=semPct(totales.pct);
            return(<>
              <div style={{width:130,height:130,borderRadius:"50%",border:`8px solid ${sem.color}`,background:sem.bg,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",boxShadow:`0 0 40px ${sem.color}44`,flexShrink:0}}>
                <span style={{fontFamily:"Inter",fontSize:34,fontWeight:800,color:sem.color,lineHeight:1}}>{totales.pct}%</span>
                <span style={{fontSize:10,color:sem.color,fontWeight:700,letterSpacing:".1em",marginTop:2}}>CHC</span>
              </div>
              <div style={{display:"flex",flexDirection:"column",gap:8,minWidth:220}}>
                {[{l:"Hs Efectivas",v:fmtNum(totales.horasTrabajo),c:C.accent},{l:"Hs Op. a Disposición",v:fmtNum(totales.hsOD),c:C.yellow},{l:"Hs Contratadas",v:fmtNum(totales.hsContratadas),c:C.blue}].map(({l,v,c})=>(
                  <div key={l} style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"6px 12px",background:c+"15",borderRadius:7,border:`1px solid ${c}33`,gap:16}}>
                    <span style={{fontSize:11,color:C.textSub}}>{l}</span>
                    <span style={{fontFamily:"Inter",fontWeight:700,color:c,fontSize:13}}>{v}</span>
                  </div>
                ))}
              </div>
              <div style={{display:"flex",flexDirection:"column",gap:8}}>
                {[["≥ 90%","Óptimo",C.green],["70% – 89%","Atención",C.yellow],["< 70%","Crítico",C.red]].map(([r,l,c])=>(
                  <div key={l} style={{display:"flex",alignItems:"center",gap:8}}>
                    <div style={{width:10,height:10,borderRadius:"50%",background:c,flexShrink:0}}/>
                    <span style={{fontSize:11,color:C.textSub}}><strong style={{color:c}}>{r}</strong> — {l}</span>
                  </div>
                ))}
              </div>
            </>);
          })()}
        </div>
      </Card>

      {/* 2 y 3 — Side by side con mismo orden de equipos en eje Y */}
      {(()=>{
        const rowsSorted=[...rows].sort((a,b)=>a.maquina.localeCompare(b.maquina));
        const h=Math.max(220,rowsSorted.length*30+50);
        return(
          <div style={{display:"grid",gridTemplateColumns:"2fr 3fr",gap:14}}>
            {/* % CHC por equipo */}
            <Card title="% CHC por Equipo">
              <div style={{padding:"8px 16px 0",display:"flex",gap:16,flexWrap:"wrap"}}>
                <div style={{display:"flex",alignItems:"center",gap:6}}>
                  <div style={{width:20,borderTop:`2px dashed ${C.green}`}}/>
                  <span style={{fontSize:10,color:C.textSub}}><strong style={{color:C.green}}>90%</strong> Óptimo</span>
                </div>
                <div style={{display:"flex",alignItems:"center",gap:6}}>
                  <div style={{width:20,borderTop:`2px dashed ${C.yellow}`}}/>
                  <span style={{fontSize:10,color:C.textSub}}><strong style={{color:C.yellow}}>70%</strong> Atención</span>
                </div>
              </div>
              <div style={{padding:"8px 6px 12px"}}>
                <ResponsiveContainer width="100%" height={h}>
                  <BarChart data={rowsSorted} layout="vertical" margin={{left:8,right:36}}>
                    <CartesianGrid strokeDasharray="3 3" stroke={C.border} horizontal={false}/>
                    <XAxis type="number" domain={[0,Math.max(150,Math.ceil(Math.max(...rowsSorted.map(r=>r.pct),0)/10)*10)]} tick={{fill:C.textMuted,fontSize:10}} axisLine={false} tickLine={false} unit="%"/>
                    <YAxis type="category" dataKey="maquina" tick={{fill:C.textSub,fontSize:10}} width={88} axisLine={false} tickLine={false}/>
                    <Tooltip content={({active,payload})=>{
                      if(!active||!payload?.length)return null;
                      const d=payload[0].payload;const sem=semPct(d.pct);
                      return(<div style={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:9,padding:"10px 14px",fontSize:12}}>
                        <div style={{fontFamily:"Inter",fontWeight:700,color:sem.color,marginBottom:4}}>{d.maquina}</div>
                        <div style={{color:C.textSub}}>CHC: <strong style={{color:sem.color}}>{d.pct}%</strong></div>
                        <div style={{color:C.textSub}}>Hs efectivas: <strong style={{color:C.accent}}>{fmtNum(d.horasTrabajo)}</strong></div>
                        <div style={{color:C.textSub}}>Hs contratadas: <strong style={{color:C.blue}}>{fmtNum(d.hsContratadas)}</strong></div>
                      </div>);
                    }}/>
                    <ReferenceLine x={90} stroke={C.green} strokeDasharray="4 4" strokeWidth={1.5}/>
                    <ReferenceLine x={70} stroke={C.yellow} strokeDasharray="4 4" strokeWidth={1.5}/>
                    <Bar dataKey="pct" name="% CHC" radius={[0,4,4,0]} barSize={16}>
                      {rowsSorted.map((r,i)=>{const s=semPct(r.pct);return<Cell key={i} fill={s.color}/>;} )}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </Card>

            {/* Composición de días */}
            <Card title="Composición de Días por Equipo">
              <div style={{padding:"8px 16px 0",display:"flex",gap:16,flexWrap:"wrap"}}>
                {[["Días Efectivos+OD",C.green],["Días FS",C.red]].map(([l,c])=>(
                  <div key={l} style={{display:"flex",alignItems:"center",gap:5}}>
                    <div style={{width:10,height:10,borderRadius:2,background:c}}/>
                    <span style={{fontSize:10,color:C.textSub}}>{l}</span>
                  </div>
                ))}
              </div>
              <div style={{padding:"8px 6px 12px"}}>
                <ResponsiveContainer width="100%" height={h}>
                  <BarChart data={rowsSorted} layout="vertical" margin={{left:8,right:16}}>
                    <CartesianGrid strokeDasharray="3 3" stroke={C.border} horizontal={false}/>
                    <XAxis type="number" tick={{fill:C.textMuted,fontSize:10}} axisLine={false} tickLine={false} unit=" días"/>
                    <YAxis type="category" dataKey="maquina" tick={{fill:C.textSub,fontSize:10}} width={88} axisLine={false} tickLine={false}/>
                    <Tooltip content={({active,payload,label})=>{
                      if(!active||!payload?.length)return null;
                      return(<div style={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:9,padding:"10px 14px",fontSize:12}}>
                        <div style={{fontFamily:"Inter",fontWeight:700,color:C.text,marginBottom:6}}>{label}</div>
                        {payload.map((p,i)=><div key={i} style={{color:p.fill,fontWeight:600}}>{p.name}: {p.value} días</div>)}
                      </div>);
                    }}/>
                    <Bar dataKey="diasEfectivos" name="Días Efectivos+OD" fill={C.green} stackId="a" barSize={16}/>
                    <Bar dataKey="diasFS" name="Días FS" fill={C.red} stackId="a" radius={[0,4,4,0]} barSize={16}/>
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </Card>
          </div>
        );
      })()}
    </div>
  );
}


// ─── InsumoSearch — selector con búsqueda ────────────────────────────────────
function InsumoSearch({value,onChange,opciones}){
  const[open,setOpen]=useState(false);
  const[q,setQ]=useState("");
  const ref=useRef(null);
  const triggerRef=useRef(null);
  const[anchorPos,setAnchorPos]=useState({bottom:0,left:0});

  // Cerrar al clickear afuera — ignorar clicks dentro del portal
  const portalRef=useRef(null);
  useEffect(()=>{
    const h=e=>{
      const inTrigger=ref.current&&ref.current.contains(e.target);
      const inPortal=portalRef.current&&portalRef.current.contains(e.target);
      if(!inTrigger&&!inPortal){setOpen(false);setQ("");}
    };
    document.addEventListener("mousedown",h);
    return()=>document.removeEventListener("mousedown",h);
  },[]);

  const filtered=useMemo(()=>{
    if(!q)return opciones;
    const ql=q.toLowerCase();
    return opciones.filter(([cod,nom])=>cod.toLowerCase().includes(ql)||nom.toLowerCase().includes(ql));
  },[opciones,q]);

  const selected=value?opciones.find(([cod])=>cod===value):null;
  const label=selected?`${selected[0]} — ${selected[1]}`:"Insumo";

  return(
    <div ref={ref} style={{position:"relative",flexShrink:0}}>
      <div style={{display:"flex",flexDirection:"column",gap:3}}>
        <label style={{fontSize:10,color:"#888",fontWeight:600,letterSpacing:".06em",textTransform:"uppercase"}}>Insumo</label>
        <div ref={triggerRef} onClick={()=>{if(triggerRef.current){const r=triggerRef.current.getBoundingClientRect();setAnchorPos({bottom:r.bottom,left:r.left});}setOpen(o=>!o);setQ("");}}
          style={{background:"#1a1a1a",border:`1px solid ${value?"#e8001d44":"#2a2a2a"}`,borderRadius:7,color:value?"#e8001d":"#aaa",padding:"7px 10px",fontSize:11,cursor:"pointer",minWidth:180,maxWidth:240,display:"flex",alignItems:"center",justifyContent:"space-between",gap:6,userSelect:"none"}}>
          <span style={{overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",flex:1}}>{label}</span>
          <span style={{fontSize:9,flexShrink:0}}>{open?"▲":"▼"}</span>
        </div>
      </div>
      {open&&ReactDOM.createPortal(
        <div ref={portalRef} style={{position:"fixed",top:anchorPos.bottom+4,left:anchorPos.left,zIndex:99999,background:"#1c1c1c",border:"1px solid #333",borderRadius:9,minWidth:280,maxWidth:340,boxShadow:"0 8px 24px rgba(0,0,0,.6)",overflow:"hidden"}}>
          <div style={{padding:"8px 10px",borderBottom:"1px solid #2a2a2a"}}>
            <input autoFocus value={q} onChange={e=>setQ(e.target.value)}
              placeholder="Buscar por código o nombre..."
              style={{width:"100%",background:"#111",border:"1px solid #333",borderRadius:6,color:"#eee",padding:"6px 10px",fontSize:11,outline:"none",fontFamily:"Inter"}}/>
          </div>
          <div style={{maxHeight:260,overflowY:"auto"}}>
            <div onClick={()=>{onChange("");setOpen(false);setQ("");}}
              style={{padding:"8px 12px",cursor:"pointer",color:"#888",fontSize:11,borderBottom:"1px solid #1a1a1a",background:!value?"#2a2a2a":"transparent"}}>
              Todos los insumos
            </div>
            {filtered.slice(0,100).map(([cod,nom])=>(
              <div key={cod} onClick={()=>{onChange(cod);setOpen(false);setQ("");}}
                style={{padding:"8px 12px",cursor:"pointer",fontSize:11,color:value===cod?"#e8001d":"#ccc",background:value===cod?"#2a0a0a":"transparent",borderBottom:"1px solid #1a1a1a",display:"flex",gap:8,alignItems:"center"}}
                onMouseEnter={e=>e.currentTarget.style.background=value===cod?"#3a0a0a":"#252525"}
                onMouseLeave={e=>e.currentTarget.style.background=value===cod?"#2a0a0a":"transparent"}
              >
                <span style={{color:"#888",flexShrink:0,minWidth:40}}>{cod}</span>
                <span style={{overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{nom}</span>
              </div>
            ))}
            {filtered.length>100&&<div style={{padding:"6px 12px",color:"#666",fontSize:10,textAlign:"center"}}>Mostrando 100 de {filtered.length} — seguí escribiendo para filtrar</div>}
          </div>
        </div>,
        document.body
      )}
    </div>
  );
}


// ─── ViewMantenimiento ────────────────────────────────────────────────────────
function ViewMantenimiento({rma15,usdRate,extState,setExtState}){
  const{modo,proyecto,tipoMant,maquina,fechaD,fechaH,fechaDia,filtroCosto,insumoFiltro}=extState;
  const set=(k,v)=>setExtState(s=>({...s,[k]:v}));
  const setModo=v=>set("modo",v);
  const setProyecto=v=>set("proyecto",v);
  const setTipoMant=v=>set("tipoMant",v);
  const setMaquina=v=>set("maquina",v);
  const setFechaD=v=>set("fechaD",v);
  const setFechaH=v=>set("fechaH",v);
  const setFechaDia=v=>set("fechaDia",v);
  const setFiltroCosto=v=>set("filtroCosto",v);
  const setInsumoFiltro=v=>set("insumoFiltro",v);

  // Normalizar tipo para comparación case-insensitive
  const normTipo=v=>String(v||"").trim().toLowerCase();

  const proyectos=useMemo(()=>uniq(rma15.map(r=>r.proyecto).filter(Boolean)),[rma15]);

  const tiposMant=useMemo(()=>uniq(rma15.filter(r=>{
    if(proyecto!=="todos"&&r.proyecto!==proyecto)return false;
    if(maquina!=="todas"&&r.maquina!==maquina)return false;
    if(modo==="dia"){if(fechaDia&&r.fecha!==fechaDia)return false;}
    else{if(fechaD&&r.fecha<fechaD)return false;if(fechaH&&r.fecha>fechaH)return false;}
    return true;
  }).map(r=>{const t=normTipo(r.tipoMant);return t.includes("prev")?"Preventivo":t.includes("corr")?"Correctivo":r.tipoMant;}).filter(Boolean)),[rma15,proyecto,maquina,fechaD,fechaH,fechaDia,modo]);

  const maquinas=useMemo(()=>uniq(rma15.filter(r=>{
    if(proyecto!=="todos"&&r.proyecto!==proyecto)return false;
    if(tipoMant!=="todos"&&normTipo(r.tipoMant)!==normTipo(tipoMant))return false;
    if(modo==="dia"){if(fechaDia&&r.fecha!==fechaDia)return false;}
    else{if(fechaD&&r.fecha<fechaD)return false;if(fechaH&&r.fecha>fechaH)return false;}
    return true;
  }).map(r=>r.maquina).filter(Boolean)).sort(),[rma15,proyecto,tipoMant,fechaD,fechaH,fechaDia,modo]);

  const filtered=useMemo(()=>rma15.filter(r=>{
    if(proyecto!=="todos"&&r.proyecto!==proyecto)return false;
    if(tipoMant!=="todos"&&normTipo(r.tipoMant)!==normTipo(tipoMant))return false;
    if(maquina!=="todas"&&r.maquina!==maquina)return false;
    if(modo==="dia"){if(fechaDia&&r.fecha!==fechaDia)return false;}
    else{if(fechaD&&r.fecha<fechaD)return false;if(fechaH&&r.fecha>fechaH)return false;}
    // Si hay filtro por insumo, solo incluir OTs que usen ese insumo
    if(insumoFiltro&&!r.insumos.some(i=>i.codigo===insumoFiltro))return false;
    return true;
  }),[rma15,proyecto,tipoMant,maquina,fechaD,fechaH,fechaDia,modo,insumoFiltro]);

  // KPIs
  const totalOTs=filtered.length;
  const preventivos=filtered.filter(r=>normTipo(r.tipoMant).includes("prev")).length;
  const correctivos=filtered.filter(r=>normTipo(r.tipoMant).includes("corr")).length;
  const costoTotal=filtered.reduce((s,r)=>s+r.costoTotal,0);
  const noOperativos=filtered.filter(r=>!r.operativo).length;
  const equiposAfectados=uniq(filtered.map(r=>r.maquina)).length;

  // Insumos más usados
  const insumosMap={};
  filtered.forEach(r=>r.insumos.forEach(i=>{
    if(!i.codigo)return;
    if(!insumosMap[i.codigo])insumosMap[i.codigo]={nombre:i.nombre,cantidad:0,costo:0};
    insumosMap[i.codigo].cantidad+=i.cantidad;
    insumosMap[i.codigo].costo+=i.costoTotal;
  }));
  const topInsumos=Object.entries(insumosMap).sort((a,b)=>b[1].cantidad-a[1].cantidad).slice(0,10);

  // OTs por equipo
  const otsPorMaq={};
  filtered.forEach(r=>{otsPorMaq[r.maquina]=(otsPorMaq[r.maquina]||0)+1;});
  const barDataMaq=Object.entries(otsPorMaq).sort((a,b)=>b[1]-a[1]).slice(0,15).map(([maquina,ots])=>({maquina,ots}));

  // Costos por equipo según filtro
  const costosPorMaq=useMemo(()=>{
    const m={};
    filtered.forEach(r=>{
      const tipo=normTipo(r.tipoMant);
      if(filtroCosto==="prev"&&!tipo.includes("prev"))return;
      if(filtroCosto==="corr"&&!tipo.includes("corr"))return;
      if(!m[r.maquina])m[r.maquina]=0;
      m[r.maquina]+=r.costoTotal;
    });
    return Object.entries(m).filter(([,v])=>v>0).sort((a,b)=>b[1]-a[1]).slice(0,15).map(([maquina,costo])=>({maquina,costo}));
  },[filtered,filtroCosto]);

  // OTs por tipo (normalizado)
  const otsPorTipo={};
  filtered.forEach(r=>{
    const t=normTipo(r.tipoMant).includes("prev")?"Preventivo":normTipo(r.tipoMant).includes("corr")?"Correctivo":(r.tipoMant||"Otro");
    otsPorTipo[t]=(otsPorTipo[t]||0)+1;
  });
  const pieDataTipo=Object.entries(otsPorTipo).map(([name,value])=>({name,value}));
  const COLORS=["#e8001d","#3b82f6","#10b981","#f59e0b","#8b5cf6","#ec4899"];

  const hayFiltros=proyecto!=="todos"||tipoMant!=="todos"||maquina!=="todas"||fechaD||fechaH||fechaDia||insumoFiltro;

  // Lista de insumos únicos para el selector (código + nombre, ordenado alfabéticamente)
  const insumosDisponibles=useMemo(()=>{
    // Solo mostrar insumos disponibles según filtros activos (sin insumoFiltro)
    const base=rma15.filter(r=>{
      if(proyecto!=="todos"&&r.proyecto!==proyecto)return false;
      if(tipoMant!=="todos"&&normTipo(r.tipoMant)!==normTipo(tipoMant))return false;
      if(maquina!=="todas"&&r.maquina!==maquina)return false;
      if(modo==="dia"){if(fechaDia&&r.fecha!==fechaDia)return false;}
      else{if(fechaD&&r.fecha<fechaD)return false;if(fechaH&&r.fecha>fechaH)return false;}
      return true;
    });
    const m={};
    base.forEach(r=>r.insumos.forEach(i=>{if(i.codigo&&!m[i.codigo])m[i.codigo]=i.nombre||i.codigo;}));
    return Object.entries(m).sort((a,b)=>(a[1]||a[0]).localeCompare(b[1]||b[0]));
  },[rma15,proyecto,tipoMant,maquina,fechaD,fechaH,fechaDia,modo]);
  const reset=()=>{setProyecto("todos");setTipoMant("todos");setMaquina("todas");setFechaD("");setFechaH("");setFechaDia("");setInsumoFiltro("");};

  const colsPeriodo=useMemo(()=>[
    {key:"fecha",label:"Fecha",render:v=>fmtFecha(v)},
    {key:"proyecto",label:"Proyecto",render:v=><Badge color={v?.includes("FILO")?C.accent:C.teal}>{v||"—"}</Badge>},
    {key:"maquina",label:"Máquina",render:v=><Badge color={C.purple}>{v}</Badge>},
    {key:"tipoMant",label:"Tipo",render:v=><Badge color={normTipo(v).includes("prev")?C.green:C.red}>{v||"—"}</Badge>},
    {key:"intervencion",label:"Intervención",wrap:true},
    {key:"operativo",label:"Operativo",render:v=><Badge color={v?C.green:C.red}>{v?"SÍ":"NO"}</Badge>},
    {key:"costoTotal",label:"Costo ARS",render:v=><span style={{color:v>0?C.yellow:C.textMuted,fontWeight:600}}>{v>0?"$"+fmtNum(v):"—"}</span>},
    {key:"costoTotal",label:"Costo USD",render:v=><span style={{color:v>0?C.green:C.textMuted,fontWeight:600}}>{fmtUSD(v,usdRate)}</span>},
    {key:"observaciones",label:"Observaciones",wrap:true},
  ],[]);

  // colsDia no se usa más — tabla de insumos se arma inline en el dashboard

  return(
    <div className="fade-in" style={{display:"flex",flexDirection:"column",gap:14}}>
      {/* Filtros */}
      <Card>
        <div style={{padding:"12px 14px",display:"flex",flexDirection:"column",gap:10}}>
          {/* Fila 1: tabs + botón reporte */}
          <div style={{display:"flex",gap:7,alignItems:"center",flexWrap:"wrap"}}>
            <TabBtn active={modo==="dia"} onClick={()=>setModo("dia")}>Por día</TabBtn>
            <TabBtn active={modo==="periodo"} onClick={()=>setModo("periodo")}>Por período</TabBtn>
            <button onClick={()=>{const label=(fechaDia||fechaD||new Date().toISOString().slice(0,10)).replace(/-/g,"");generarExcelMantenimiento(filtered,usdRate,label);}} style={{marginLeft:8,display:"flex",alignItems:"center",gap:6,padding:"7px 14px",borderRadius:7,border:`1px solid ${C.accent}`,background:C.accentDim,color:C.accent,cursor:"pointer",fontSize:12,fontWeight:700,fontFamily:"Inter",letterSpacing:".04em"}}>
              📄 Generar Reporte
            </button>
          </div>
          {/* Fila 2: filtros */}
          <div style={{display:"flex",flexWrap:"wrap",gap:10,alignItems:"flex-end"}}>
            {modo==="periodo"&&<><DateIn label="Desde" value={fechaD} onChange={setFechaD} max={fechaH||undefined}/><DateIn label="Hasta" value={fechaH} onChange={setFechaH} min={fechaD||undefined} warn={fechaH&&fechaD&&fechaH<fechaD?"≥ Desde":null}/></>}
            {modo==="dia"&&<DateIn label="Fecha" value={fechaDia} onChange={setFechaDia}/>}
            <Sel label="Proyecto" value={proyecto} onChange={setProyecto} options={[{value:"todos",label:"Todos"},...proyectos.map(p=>({value:p,label:p}))]}/>
            <Sel label="Tipo" value={tipoMant} onChange={setTipoMant} options={[{value:"todos",label:"Todos"},...tiposMant.map(t=>({value:t,label:t}))]}/>
            <Sel label="Máquina" value={maquina} onChange={setMaquina} options={[{value:"todas",label:"Todas"},...maquinas.map(m=>({value:m,label:m}))]}/>
            <InsumoSearch value={insumoFiltro} onChange={setInsumoFiltro} opciones={insumosDisponibles}/>
            <button onClick={reset} style={{marginLeft:"auto",display:"flex",alignItems:"center",gap:5,padding:"6px 12px",borderRadius:7,border:`1px solid ${C.red}44`,background:C.redDim,color:C.red,cursor:"pointer",fontSize:11,fontWeight:600,fontFamily:"Inter",opacity:hayFiltros?1:0.3,pointerEvents:hayFiltros?"auto":"none"}}><Icon name="close" size={11} color={C.red}/>Limpiar filtros</button>
          </div>
        </div>
      </Card>

      {/* KPIs */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(140px,1fr))",gap:10}}>
        <StatCard icon="parts" label="Total OTs" value={totalOTs} color={C.blue} small/>
        <StatCard icon="check" label="Preventivos" value={preventivos} color={C.green} small/>
        <StatCard icon="warn" label="Correctivos" value={correctivos} color={C.red} small/>
        <StatCard icon="equip" label="Equipos afectados" value={equiposAfectados} color={C.purple} small/>
        <StatCard icon="warn" label="No operativos" value={noOperativos} color={C.yellow} small/>
        <StatCard icon="prod" label="Costo total insumos" value={costoTotal>0?"$"+fmtNum(costoTotal):"—"} color={C.yellow} small/>
        <StatCard icon="prod" label="Costo total USD" value={fmtUSD(costoTotal,usdRate)} color={C.green} small/>
      </div>

      {/* Gráficos solo en período */}
      {modo==="periodo"&&(
        <div style={{display:"grid",gridTemplateColumns:"1fr 2fr 2fr",gap:14}}>
          <Card title="Distribución por Tipo">
            <div style={{padding:"12px",display:"flex",justifyContent:"center",alignItems:"center",flexDirection:"column",gap:10}}>
              <PieChart width={180} height={180}>
                <Pie data={pieDataTipo} dataKey="value" cx="50%" cy="50%" outerRadius={80} innerRadius={36}>
                  {pieDataTipo.map((_,i)=><Cell key={i} fill={COLORS[i%COLORS.length]}/>)}
                </Pie>
                <Tooltip content={({active,payload})=>{
                  if(!active||!payload?.length)return null;
                  const d=payload[0].payload;
                  return(<div style={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:8,padding:"8px 12px",fontSize:12}}>
                    <div style={{color:C.text,fontWeight:600}}>{d.name}</div>
                    <div style={{color:C.accent}}>{d.value} OTs</div>
                  </div>);
                }}/>
              </PieChart>
              <div style={{display:"flex",flexDirection:"column",gap:5,width:"100%"}}>
                {pieDataTipo.map((d,i)=>(
                  <div key={i} style={{display:"flex",alignItems:"center",gap:8}}>
                    <div style={{width:10,height:10,borderRadius:"50%",background:COLORS[i%COLORS.length],flexShrink:0}}/>
                    <span style={{fontSize:12,color:C.textSub,flex:1}}>{d.name}</span>
                    <span style={{fontSize:12,fontWeight:700,color:C.text}}>{d.value}</span>
                  </div>
                ))}
              </div>
            </div>
          </Card>
          <Card title="OTs por Equipo">
            <div style={{padding:"8px 6px"}}>
              <ResponsiveContainer width="100%" height={Math.max(180,barDataMaq.length*28+40)}>
                <BarChart data={barDataMaq} layout="vertical" margin={{left:8,right:30}}>
                  <CartesianGrid strokeDasharray="3 3" stroke={C.border} horizontal={false}/>
                  <XAxis type="number" tick={{fill:C.textMuted,fontSize:10}} axisLine={false} tickLine={false}/>
                  <YAxis type="category" dataKey="maquina" tick={{fill:C.textSub,fontSize:10}} width={88} axisLine={false} tickLine={false}/>
                  <Tooltip content={({active,payload})=>{
                    if(!active||!payload?.length)return null;
                    return(<div style={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:8,padding:"8px 12px",fontSize:12}}>
                      <div style={{color:C.purple,fontWeight:700}}>{payload[0].payload.maquina}</div>
                      <div style={{color:C.accent}}>{payload[0].value} OTs</div>
                    </div>);
                  }}/>
                  <Bar dataKey="ots" fill={C.accent} radius={[0,4,4,0]} barSize={16}/>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </Card>
          <Card title="Gasto en Insumos por Equipo" action={
            <div style={{display:"flex",gap:4}}>
              {[{v:"total",l:"Total"},{v:"prev",l:"Prev."},{v:"corr",l:"Corr."}].map(({v,l})=>(
                <button key={v} onClick={()=>setFiltroCosto(v)} style={{padding:"3px 9px",borderRadius:6,border:`1px solid ${filtroCosto===v?C.accent:C.border}`,background:filtroCosto===v?C.redDim:"transparent",color:filtroCosto===v?C.accent:C.textMuted,fontSize:10,fontWeight:600,cursor:"pointer",fontFamily:"Inter"}}>{l}</button>
              ))}
            </div>
          }>
            <div style={{padding:"8px 6px"}}>
              {costosPorMaq.length===0
                ?<div style={{padding:24,textAlign:"center",color:C.textMuted,fontSize:12}}>Sin datos de costos</div>
                :<ResponsiveContainer width="100%" height={Math.max(180,costosPorMaq.length*28+40)}>
                  <BarChart data={costosPorMaq} layout="vertical" margin={{left:8,right:30}}>
                    <CartesianGrid strokeDasharray="3 3" stroke={C.border} horizontal={false}/>
                    <XAxis type="number" tick={{fill:C.textMuted,fontSize:10}} axisLine={false} tickLine={false} tickFormatter={v=>"$"+fmtNum(v)}/>
                    <YAxis type="category" dataKey="maquina" tick={{fill:C.textSub,fontSize:10}} width={88} axisLine={false} tickLine={false}/>
                    <Tooltip content={({active,payload})=>{
                      if(!active||!payload?.length)return null;
                      return(<div style={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:8,padding:"8px 12px",fontSize:12}}>
                        <div style={{color:C.purple,fontWeight:700}}>{payload[0].payload.maquina}</div>
                        <div style={{color:C.green,fontWeight:600}}>${fmtNum(payload[0].value)}</div>
                      </div>);
                    }}/>
                    <Bar dataKey="costo" fill={C.green} radius={[0,4,4,0]} barSize={16}/>
                  </BarChart>
                </ResponsiveContainer>
              }
            </div>
          </Card>
        </div>
      )}

      {/* Top insumos solo en período */}
      {modo==="periodo"&&topInsumos.length>0&&(
        <Card title="Insumos más utilizados (Top 10)">
          <div style={{overflowX:"auto"}}>
            <table style={{width:"100%",borderCollapse:"collapse",fontSize:13}}>
              <thead>
                <tr style={{background:C.surface}}>
                  {["Código","Descripción","Cantidad total","Costo ARS","Costo USD"].map((h,i)=>(
                    <th key={i} style={{padding:"9px 12px",textAlign:i<2?"left":"center",color:C.textSub,fontWeight:600,fontSize:11,letterSpacing:".05em",textTransform:"uppercase",borderBottom:`1px solid ${C.border}`}}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {topInsumos.map(([cod,v],i)=>(
                  <tr key={cod} style={{background:i%2===0?"transparent":C.surface+"55"}}>
                    <td style={{padding:"8px 12px",borderBottom:`1px solid ${C.border}18`,color:C.blue,fontWeight:600}}>{cod}</td>
                    <td style={{padding:"8px 12px",borderBottom:`1px solid ${C.border}18`,color:C.text}}>{v.nombre||"—"}</td>
                    <td style={{padding:"8px 12px",textAlign:"center",borderBottom:`1px solid ${C.border}18`,color:C.accent,fontWeight:700}}>{fmtNum(v.cantidad)}</td>
                    <td style={{padding:"8px 12px",textAlign:"center",borderBottom:`1px solid ${C.border}18`,color:v.costo>0?C.yellow:C.textMuted,fontWeight:v.costo>0?700:400}}>{v.costo>0?"$"+fmtNum(v.costo):"—"}</td>
                    <td style={{padding:"8px 12px",textAlign:"center",borderBottom:`1px solid ${C.border}18`,color:v.costo>0?C.green:C.textMuted,fontWeight:v.costo>0?700:400}}>{fmtUSD(v.costo,usdRate)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </Card>
      )}

      {/* Dashboard Por día */}
      {modo==="dia"&&(
        <div style={{display:"flex",flexDirection:"column",gap:14}}>

          {/* Fila 1: KPIs del día */}
          {!fechaDia&&(
            <Card>
              <div style={{padding:"20px",textAlign:"center",color:C.textMuted,fontSize:13}}>
                Seleccioná una fecha para ver el dashboard del día
              </div>
            </Card>
          )}

          {fechaDia&&filtered.length===0&&(
            <Card>
              <div style={{padding:"20px",textAlign:"center",color:C.textMuted,fontSize:13}}>
                Sin registros para el día seleccionado
              </div>
            </Card>
          )}

          {fechaDia&&filtered.length>0&&(()=>{
            const COLORS=["#e8001d","#3b82f6","#10b981","#f59e0b","#8b5cf6","#ec4899"];
            // Insumos del día
            const insMap={};
            filtered.forEach(r=>r.insumos.forEach(i=>{
              if(!i.codigo)return;
              if(!insMap[i.codigo])insMap[i.codigo]={nombre:i.nombre,cantidad:0,costo:0};
              insMap[i.codigo].cantidad+=i.cantidad;
              insMap[i.codigo].costo+=i.costoTotal;
            }));
            const topIns=Object.entries(insMap).sort((a,b)=>b[1].cantidad-a[1].cantidad);
            // Equipos del día con tipo
            const eqData=filtered.map(r=>({
              maquina:r.maquina,
              tipo:normTipo(r.tipoMant).includes("prev")?"Preventivo":"Correctivo",
              operativo:r.operativo,
              costo:r.costoTotal,
              intervencion:r.intervencion,
            }));
            // Torta tipo
            const tipoCount={Preventivo:0,Correctivo:0};
            filtered.forEach(r=>{const t=normTipo(r.tipoMant).includes("prev")?"Preventivo":"Correctivo";tipoCount[t]++;});
            const pieData=[{name:"Preventivo",value:tipoCount.Preventivo},{name:"Correctivo",value:tipoCount.Correctivo}].filter(d=>d.value>0);
            // Costos por equipo
            const costoEq={};
            filtered.forEach(r=>{costoEq[r.maquina]=(costoEq[r.maquina]||0)+r.costoTotal;});
            const barCosto=Object.entries(costoEq).filter(([,v])=>v>0).sort((a,b)=>b[1]-a[1]).map(([maquina,costo])=>({maquina,costo}));
            // No operativos
            const noOp=filtered.filter(r=>!r.operativo);

            return(
              <div style={{display:"flex",flexDirection:"column",gap:14}}>

                {/* Fila gráficos */}
                <div style={{display:"grid",gridTemplateColumns:"1fr 2fr",gap:14}}>

                  {/* Torta tipo + equipos no operativos */}
                  <div style={{display:"flex",flexDirection:"column",gap:14}}>
                    <Card title="Distribución por Tipo">
                      <div style={{padding:"12px",display:"flex",justifyContent:"center",alignItems:"center",flexDirection:"column",gap:8}}>
                        <PieChart width={160} height={160}>
                          <Pie data={pieData} dataKey="value" cx="50%" cy="50%" outerRadius={72} innerRadius={32}>
                            {pieData.map((_,i)=><Cell key={i} fill={i===0?C.green:C.red}/>)}
                          </Pie>
                          <Tooltip content={({active,payload})=>{
                            if(!active||!payload?.length)return null;
                            return(<div style={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:8,padding:"8px 12px",fontSize:12}}>
                              <div style={{color:C.text,fontWeight:600}}>{payload[0].payload.name}</div>
                              <div style={{color:C.accent}}>{payload[0].value} OTs</div>
                            </div>);
                          }}/>
                        </PieChart>
                        <div style={{display:"flex",flexDirection:"column",gap:5,width:"100%"}}>
                          {pieData.map((d,i)=>(
                            <div key={i} style={{display:"flex",alignItems:"center",gap:8}}>
                              <div style={{width:10,height:10,borderRadius:"50%",background:i===0?C.green:C.red,flexShrink:0}}/>
                              <span style={{fontSize:12,color:C.textSub,flex:1}}>{d.name}</span>
                              <span style={{fontSize:12,fontWeight:700,color:C.text}}>{d.value}</span>
                            </div>
                          ))}
                        </div>
                      </div>
                    </Card>

                    {noOp.length>0&&(
                      <Card title="⚠ Equipos no operativos">
                        <div style={{padding:"8px 12px",display:"flex",flexDirection:"column",gap:6}}>
                          {noOp.map((r,i)=>(
                            <div key={i} style={{display:"flex",alignItems:"center",gap:8,padding:"6px 8px",background:C.redDim,borderRadius:7,border:`1px solid ${C.red}33`}}>
                              <Badge color={C.red}>{r.maquina}</Badge>
                              <span style={{fontSize:11,color:C.textSub,flex:1,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{r.intervencion||"Sin detalle"}</span>
                            </div>
                          ))}
                        </div>
                      </Card>
                    )}
                  </div>

                  {/* Equipos atendidos */}
                  <Card title={`Equipos atendidos (${eqData.length})`}>
                    <div style={{overflowX:"auto",maxHeight:320,overflowY:"auto"}}>
                      <table style={{width:"100%",borderCollapse:"collapse",fontSize:12}}>
                        <thead>
                          <tr style={{background:C.surface}}>
                            {["Proyecto","Máquina","Tipo","Operativo","Intervención","Costo ARS","Costo USD"].map((h,i)=>(
                              <th key={i} style={{padding:"8px 12px",textAlign:i===0||i===3?"left":"center",color:C.textSub,fontWeight:600,fontSize:10,letterSpacing:".05em",textTransform:"uppercase",borderBottom:`1px solid ${C.border}`,position:"sticky",top:0,background:C.surface}}>{h}</th>
                            ))}
                          </tr>
                        </thead>
                        <tbody>
                          {eqData.map((r,i)=>(
                            <tr key={i}
                            style={{background:i%2===0?"transparent":C.surface+"55",cursor:"pointer",transition:"background .1s"}}
                            onMouseEnter={e=>{
                              e.currentTarget.dataset.bg=e.currentTarget.style.background||"transparent";
                              e.currentTarget.style.background=C.accent+"22";
                              const ot=filtered[i];const ins=ot?.insumos?.filter(x=>x.codigo)||[];
                              if(!ins.length)return;
                              const tip=document.createElement("div");tip.id="mant-tip2";
                              tip.style.cssText=`position:fixed;z-index:9999;background:#1c1c1c;border:1px solid #333;border-radius:10px;padding:12px 16px;font-size:12px;font-family:Inter,sans-serif;max-width:400px;box-shadow:0 8px 32px rgba(0,0,0,.6);pointer-events:none`;
                              const rect=e.currentTarget.getBoundingClientRect();
                              const tipW1=tip.offsetWidth||400;const tipH1=tip.offsetHeight||120;
                              tip.style.left=Math.min(rect.right+8,window.innerWidth-tipW1-8)+"px";
                              tip.style.top=Math.max(8,rect.bottom-tipH1)+"px";
                              tip.innerHTML="<div style='font-size:10px;color:#888;text-transform:uppercase;letter-spacing:.06em;margin-bottom:8px;font-weight:600'>Insumos — "+r.maquina+"</div>"+
                                ins.map(x=>"<div style='padding:3px 0;border-bottom:1px solid #2a2a2a;display:flex;justify-content:space-between;gap:12px'><span style='color:#ccc'><b style='color:#aaa'>"+x.codigo+"</b> — "+(x.nombre||"—")+"</span><span style='color:#e8001d;font-weight:700'>x"+x.cantidad+"</span></div>").join("")+
                                (ot.costoTotal>0?"<div style='margin-top:8px;text-align:right;color:#10b981;font-weight:700'>Total: $"+Math.round(ot.costoTotal).toLocaleString("es-AR")+"</div>":"");
                              document.body.appendChild(tip);
                            }}
                            onMouseLeave={e=>{e.currentTarget.style.background=e.currentTarget.dataset.bg||"transparent";const t=document.getElementById("mant-tip2");if(t)t.remove();}}
                          >
                              <td style={{padding:"7px 12px",borderBottom:`1px solid ${C.border}18`}}><Badge color={filtered[i]?.proyecto?.includes("FILO")?C.accent:C.teal}>{filtered[i]?.proyecto||"—"}</Badge></td>
                              <td style={{padding:"7px 12px",borderBottom:`1px solid ${C.border}18`}}><Badge color={C.purple}>{r.maquina}</Badge></td>
                              <td style={{padding:"7px 12px",textAlign:"center",borderBottom:`1px solid ${C.border}18`}}><Badge color={r.tipo==="Preventivo"?C.green:C.red}>{r.tipo}</Badge></td>
                              <td style={{padding:"7px 12px",textAlign:"center",borderBottom:`1px solid ${C.border}18`}}><Badge color={r.operativo?C.green:C.red}>{r.operativo?"SÍ":"NO"}</Badge></td>
                              <td style={{padding:"7px 12px",borderBottom:`1px solid ${C.border}18`,color:C.textSub,fontSize:11,maxWidth:240,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{r.intervencion||"—"}</td>
                              <td style={{padding:"7px 12px",textAlign:"center",borderBottom:`1px solid ${C.border}18`,color:r.costo>0?C.yellow:C.textMuted,fontWeight:r.costo>0?600:400}}>{r.costo>0?"$"+fmtNum(r.costo):"—"}</td>
                              <td style={{padding:"7px 12px",textAlign:"center",borderBottom:`1px solid ${C.border}18`,color:r.costo>0?C.green:C.textMuted,fontWeight:r.costo>0?600:400}}>{fmtUSD(r.costo,usdRate)}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  </Card>
                </div>

                {/* Fila 2: Insumos + costos por equipo */}
                <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:14}}>

                  {/* Top insumos del día */}
                  {topIns.length>0&&(
                    <Card title={`Insumos utilizados (${topIns.length})`}>
                      <div style={{overflowX:"auto",maxHeight:300,overflowY:"auto"}}>
                        <table style={{width:"100%",borderCollapse:"collapse",fontSize:12}}>
                          <thead>
                            <tr style={{background:C.surface}}>
                              {["Código","Descripción","Cant.","Costo ARS","Costo USD"].map((h,i)=>(
                                <th key={i} style={{padding:"8px 10px",textAlign:i<2?"left":"center",color:C.textSub,fontWeight:600,fontSize:10,letterSpacing:".05em",textTransform:"uppercase",borderBottom:`1px solid ${C.border}`,position:"sticky",top:0,background:C.surface}}>{h}</th>
                              ))}
                            </tr>
                          </thead>
                          <tbody>
                            {topIns.map(([cod,v],i)=>(
                              <tr key={cod} style={{background:i%2===0?"transparent":C.surface+"55"}}>
                                <td style={{padding:"7px 10px",borderBottom:`1px solid ${C.border}18`,color:C.blue,fontWeight:600,fontSize:11}}>{cod}</td>
                                <td style={{padding:"7px 10px",borderBottom:`1px solid ${C.border}18`,color:C.text,fontSize:11}}>{v.nombre||"—"}</td>
                                <td style={{padding:"7px 10px",textAlign:"center",borderBottom:`1px solid ${C.border}18`,color:C.accent,fontWeight:700}}>{fmtNum(v.cantidad)}</td>
                                <td style={{padding:"7px 10px",textAlign:"center",borderBottom:`1px solid ${C.border}18`,color:v.costo>0?C.green:C.textMuted,fontWeight:v.costo>0?600:400}}>{v.costo>0?"$"+fmtNum(v.costo):"—"}</td>
                                <td style={{padding:"7px 10px",textAlign:"center",borderBottom:`1px solid ${C.border}18`,color:v.costo>0?C.blue:C.textMuted,fontWeight:v.costo>0?600:400}}>{fmtUSD(v.costo,usdRate)}</td>
                              </tr>
                            ))}
                          </tbody>
                        </table>
                      </div>
                    </Card>
                  )}

                  {/* Costos por equipo */}
                  {barCosto.length>0&&(
                    <Card title="Gasto por Equipo">
                      <div style={{padding:"8px 6px"}}>
                        <ResponsiveContainer width="100%" height={Math.max(140,barCosto.length*28+30)}>
                          <BarChart data={barCosto} layout="vertical" margin={{left:8,right:40}}>
                            <CartesianGrid strokeDasharray="3 3" stroke={C.border} horizontal={false}/>
                            <XAxis type="number" tick={{fill:C.textMuted,fontSize:9}} axisLine={false} tickLine={false} tickFormatter={v=>"$"+fmtNum(v)}/>
                            <YAxis type="category" dataKey="maquina" tick={{fill:C.textSub,fontSize:10}} width={88} axisLine={false} tickLine={false}/>
                            <Tooltip content={({active,payload})=>{
                              if(!active||!payload?.length)return null;
                              return(<div style={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:8,padding:"8px 12px",fontSize:12}}>
                                <div style={{color:C.purple,fontWeight:700}}>{payload[0].payload.maquina}</div>
                                <div style={{color:C.green,fontWeight:600}}>${fmtNum(payload[0].value)}</div>
                              </div>);
                            }}/>
                            <Bar dataKey="costo" fill={C.green} radius={[0,4,4,0]} barSize={16}/>
                          </BarChart>
                        </ResponsiveContainer>
                      </div>
                    </Card>
                  )}
                </div>

                {/* Tabla insumos del día */}
                {(()=>{
                  const allIns=[];
                  filtered.forEach(r=>{
                    r.insumos.filter(x=>x.codigo).forEach(x=>{
                      allIns.push({maquina:r.maquina,tipoMant:r.tipoMant,codigo:x.codigo,nombre:x.nombre,cantidad:x.cantidad,costoARS:x.costoTotal});
                    });
                  });
                  if(!allIns.length)return null;
                  return(
                    <Card title={`Insumos utilizados — ${fmtFecha(fechaDia)} (${allIns.length} registros)`}>
                      <div style={{overflowX:"auto",overflowY:"auto",maxHeight:400}}>
                        <table style={{width:"100%",borderCollapse:"collapse",fontSize:12}}>
                          <thead>
                            <tr style={{background:C.surface}}>
                              {["Máquina","Tipo","Código","Descripción","Cantidad","Costo ARS","Costo USD"].map((h,i)=>(
                                <th key={i} style={{padding:"9px 12px",textAlign:i>4?"center":"left",color:C.textSub,fontWeight:600,fontSize:10,letterSpacing:".06em",textTransform:"uppercase",borderBottom:`1px solid ${C.border}`,whiteSpace:"nowrap",position:"sticky",top:0,background:C.surface,zIndex:1}}>{h}</th>
                              ))}
                            </tr>
                          </thead>
                          <tbody>
                            {allIns.map((x,i)=>{
                              // Buscar la OT completa para el tooltip
                              const ot=filtered.find(r=>r.maquina===x.maquina&&r.insumos.some(ins=>ins.codigo===x.codigo));
                              const otIns=ot?.insumos?.filter(ins=>ins.codigo)||[];
                              return(
                              <tr key={i} style={{background:i%2===0?"transparent":C.surface+"55",cursor:otIns.length?"pointer":"default",transition:"background .1s"}}
                                onMouseEnter={e=>{
                                  e.currentTarget.dataset.bg=e.currentTarget.style.background||"transparent";
                                  e.currentTarget.style.background=C.accent+"22";
                                  if(!otIns.length)return;
                                  const tip=document.createElement("div");tip.id="ins-tip";
                                  tip.style.cssText=`position:fixed;z-index:9999;background:#1c1c1c;border:1px solid #333;border-radius:10px;padding:12px 16px;font-size:12px;font-family:Inter,sans-serif;max-width:420px;box-shadow:0 8px 32px rgba(0,0,0,.6);pointer-events:none`;
                                  const rect=e.currentTarget.getBoundingClientRect();
                                  const tipW2=tip.offsetWidth||430;const tipH2=tip.offsetHeight||120;
                                  tip.style.left=Math.min(rect.right+8,window.innerWidth-tipW2-8)+"px";
                                  tip.style.top=Math.max(8,rect.bottom-tipH2)+"px";
                                  tip.innerHTML="<div style='font-size:10px;color:#888;text-transform:uppercase;letter-spacing:.06em;margin-bottom:8px;font-weight:600'>Todos los insumos — "+x.maquina+"</div>"+
                                    otIns.map(ins=>"<div style='padding:3px 0;border-bottom:1px solid #2a2a2a;display:flex;justify-content:space-between;gap:12px'><span style='color:#ccc'><b style='color:#aaa'>"+ins.codigo+"</b> — "+(ins.nombre||"—")+"</span><span style='color:#e8001d;font-weight:700;flex-shrink:0'>x"+ins.cantidad+(ins.costoTotal>0?" <span style='color:#10b981'>$"+Math.round(ins.costoTotal).toLocaleString("es-AR")+"</span>":"")+"</span></div>").join("")+
                                    (ot?.costoTotal>0?"<div style='margin-top:8px;text-align:right;color:#10b981;font-weight:700'>Total OT: $"+Math.round(ot.costoTotal).toLocaleString("es-AR")+"</div>":"");
                                  document.body.appendChild(tip);
                                }}
                                onMouseLeave={e=>{e.currentTarget.style.background=e.currentTarget.dataset.bg||"transparent";const t=document.getElementById("ins-tip");if(t)t.remove();}}
                              >
                                <td style={{padding:"7px 12px",borderBottom:`1px solid ${C.border}18`}}><Badge color={C.purple}>{x.maquina}</Badge></td>
                                <td style={{padding:"7px 12px",borderBottom:`1px solid ${C.border}18`}}><Badge color={normTipo(x.tipoMant).includes("prev")?C.green:C.red}>{x.tipoMant||"—"}</Badge></td>
                                <td style={{padding:"7px 12px",borderBottom:`1px solid ${C.border}18`,color:C.blue,fontWeight:600}}>{x.codigo}</td>
                                <td style={{padding:"7px 12px",borderBottom:`1px solid ${C.border}18`,color:C.text}}>{x.nombre||"—"}</td>
                                <td style={{padding:"7px 12px",textAlign:"center",borderBottom:`1px solid ${C.border}18`,color:C.accent,fontWeight:700}}>{fmtNum(x.cantidad)}</td>
                                <td style={{padding:"7px 12px",textAlign:"center",borderBottom:`1px solid ${C.border}18`,color:x.costoARS>0?C.yellow:C.textMuted,fontWeight:x.costoARS>0?600:400}}>{x.costoARS>0?"$"+fmtNum(x.costoARS):"—"}</td>
                                <td style={{padding:"7px 12px",textAlign:"center",borderBottom:`1px solid ${C.border}18`,color:x.costoARS>0?C.green:C.textMuted,fontWeight:x.costoARS>0?600:400}}>{fmtUSD(x.costoARS,usdRate)}</td>
                              </tr>
                              );
                            })}
                          </tbody>
                        </table>
                      </div>
                    </Card>
                  );
                })()}

              </div>
            );
          })()}
        </div>
      )}

      {/* Por período */}
      {modo==="periodo"&&(
        <Card title={`Órdenes de Trabajo (${filtered.length})`}>
          <div style={{overflowX:"auto",overflowY:"auto",maxHeight:420,width:"100%"}}>
            <table style={{width:"100%",tableLayout:"fixed",borderCollapse:"collapse",fontSize:12}}>
              <thead>
                <tr style={{background:C.surface}}>
                  {colsPeriodo.map((c,i)=><th key={i} style={{padding:"9px 12px",textAlign:"left",color:C.textSub,fontWeight:600,fontSize:10,letterSpacing:".06em",textTransform:"uppercase",borderBottom:`1px solid ${C.border}`,whiteSpace:"nowrap",position:"sticky",top:0,background:C.surface,zIndex:1}}>{c.label}</th>)}
                </tr>
              </thead>
              <tbody>
                {filtered.length===0
                  ?<tr><td colSpan={colsPeriodo.length} style={{padding:28,textAlign:"center",color:C.textMuted}}>Sin registros</td></tr>
                  :filtered.map((r,i)=>{
                    const ins=r.insumos?.filter(x=>x.codigo)||[];
                    return(
                      <tr key={i}
                        style={{background:i%2===0?"transparent":C.surface+"66",cursor:ins.length?"pointer":"default",transition:"background .1s"}}
                        onMouseEnter={e=>{
                          e.currentTarget.dataset.bg=e.currentTarget.style.background||"transparent";
                          e.currentTarget.style.background=C.accent+"22";
                          if(!ins.length)return;
                          const tip=document.createElement("div");tip.id="mant-tip3";
                          tip.style.cssText=`position:fixed;z-index:9999;background:#1c1c1c;border:1px solid #333;border-radius:10px;padding:12px 16px;font-size:12px;font-family:Inter,sans-serif;max-width:420px;box-shadow:0 8px 32px rgba(0,0,0,.6);pointer-events:none`;
                          const rect=e.currentTarget.getBoundingClientRect();
                          const tipW3=tip.offsetWidth||430;const tipH3=tip.offsetHeight||120;
                          tip.style.left=Math.min(rect.right+8,window.innerWidth-tipW3-8)+"px";
                          tip.style.top=Math.max(8,rect.bottom-tipH3)+"px";
                          tip.innerHTML="<div style='font-size:10px;color:#888;text-transform:uppercase;letter-spacing:.06em;margin-bottom:8px;font-weight:600'>Insumos — "+r.maquina+" ("+r.fecha+")</div>"+
                            ins.map(x=>"<div style='padding:3px 0;border-bottom:1px solid #2a2a2a;display:flex;justify-content:space-between;gap:12px'><span style='color:#ccc'><b style='color:#aaa'>"+x.codigo+"</b> — "+(x.nombre||"—")+"</span><span style='color:#e8001d;font-weight:700;flex-shrink:0'>x"+x.cantidad+(x.costoTotal>0?" <span style='color:#10b981'>$"+Math.round(x.costoTotal).toLocaleString('es-AR')+"</span>":"")+"</span></div>").join("")+
                            (r.costoTotal>0?"<div style='margin-top:8px;text-align:right;color:#10b981;font-weight:700'>Total: $"+Math.round(r.costoTotal).toLocaleString('es-AR')+"</div>":"");
                          document.body.appendChild(tip);
                        }}
                        onMouseLeave={e=>{e.currentTarget.style.background=e.currentTarget.dataset.bg||"transparent";const t=document.getElementById("mant-tip3");if(t)t.remove();}}
                      >
                        {colsPeriodo.map((c,j)=><td key={j} style={{padding:"8px 12px",borderBottom:`1px solid #ffffff0a`,color:"#e0e0e0",whiteSpace:c.wrap?"normal":"nowrap",overflow:"hidden",maxWidth:c.wrap?undefined:260}}>{c.render?c.render(r[c.key]):r[c.key]||"—"}</td>)}
                      </tr>
                    );
                  })
                }
              </tbody>
            </table>
          </div>
        </Card>
      )}
    </div>
  );
}


// ─── Login ────────────────────────────────────────────────────────────────────
function Login({onLogin}){
  const[pass,setPass]=React.useState("");
  const[error,setError]=React.useState(false);
  const[shake,setShake]=React.useState(false);

  const handleSubmit=()=>{
    if(pass==="DELTA.MINING.APP"){
      sessionStorage.setItem("dm_auth","1");
      onLogin();
    } else {
      setError(true);
      setShake(true);
      setTimeout(()=>setShake(false),500);
      setTimeout(()=>setError(false),2000);
    }
  };

  return(
    <div style={{height:"100vh",background:C.bg,display:"flex",alignItems:"center",justifyContent:"center",flexDirection:"column",gap:24}}>
      <style>{`@keyframes shake{0%,100%{transform:translateX(0)}20%,60%{transform:translateX(-8px)}40%,80%{transform:translateX(8px)}}`}</style>
      <img src={LOGO} alt="Delta Mining" style={{height:80,objectFit:"contain",marginBottom:8}}/>
      <div style={{fontFamily:"Inter",fontWeight:800,fontSize:22,color:C.accent,letterSpacing:".1em"}}>DELTA MINING APP</div>
      <div style={{
        background:C.card,border:`1px solid ${error?C.red:C.border}`,borderRadius:14,
        padding:"32px 36px",display:"flex",flexDirection:"column",gap:16,
        width:320,boxShadow:`0 8px 32px rgba(0,0,0,.4)`,
        animation:shake?"shake .4s ease":"none"
      }}>
        <div style={{fontSize:13,color:C.textSub,textAlign:"center",fontWeight:500}}>Ingresá la contraseña para continuar</div>
        <input
          type="password"
          value={pass}
          onChange={e=>{setPass(e.target.value);setError(false);}}
          onKeyDown={e=>e.key==="Enter"&&handleSubmit()}
          placeholder="Contraseña"
          style={{background:C.surface,border:`1px solid ${error?C.red:C.border}`,borderRadius:8,color:C.text,padding:"10px 14px",fontSize:14,outline:"none",fontFamily:"Inter",width:"100%",boxSizing:"border-box"}}
          autoFocus
        />
        {error&&<div style={{fontSize:12,color:C.red,textAlign:"center"}}>Contraseña incorrecta</div>}
        <button
          onClick={handleSubmit}
          style={{background:C.accent,border:"none",borderRadius:8,color:"#fff",padding:"10px",fontSize:14,fontWeight:700,fontFamily:"Inter",cursor:"pointer",letterSpacing:".06em"}}
        >
          INGRESAR
        </button>
      </div>
      <div style={{fontSize:10,color:C.textMuted}}>Delta Mining OPS — Acceso restringido</div>
    </div>
  );
}


