// ─── Export Excel ROP02 ───────────────────────────────────────────────────────
function generarExcelROP02(rows, label){
  const wb=XLSX.utils.book_new();
  const data=[["Fecha","Máquina","Proyecto","Operario","Supervisor","Horas","Combustible","Estado","Tarea","Desgaste","Observaciones"]];
  rows.forEach(r=>data.push([r.fecha,r.maquina,r.proyecto,r.operario,r.supervisor,r.horas,r.combustible,r.estado,r.tipo_trabajo,r.desgaste,r.observaciones]));
  const ws=XLSX.utils.aoa_to_sheet(data);
  ws["!cols"]=[{wch:12},{wch:12},{wch:14},{wch:18},{wch:18},{wch:7},{wch:10},{wch:10},{wch:32},{wch:16},{wch:28}];
  XLSX.utils.book_append_sheet(wb,ws,"ROP02");
  XLSX.writeFile(wb,`ROP02_${label}.xlsx`);
}

// ─── Export Excel ICHC ───────────────────────────────────────────────────────
function generarExcelICHC(rows, totales, label){
  const wb=XLSX.utils.book_new();
  const headers=["Máquina","Proyecto","Hs Efectivas","Fecha Inicio","Fecha Fin","Días Efect.+OD","Días FS","Días OD","Hs Op. a Disposición","Hs Contratadas","% CHC"];
  const data=[headers];
  rows.forEach(r=>data.push([r.maquina,r.proyecto,r.horasTrabajo,r.fechaInicio,r.fechaFin,r.diasEfectivos,r.diasFS,r.diasOD,r.hsOD,r.hsContratadas,r.pct]));
  data.push(["TOTAL","",totales.horasTrabajo,"","","",totales.diasFS,totales.diasOD,totales.hsOD,totales.hsContratadas,totales.pct]);
  const ws=XLSX.utils.aoa_to_sheet(data);
  ws["!cols"]=[{wch:12},{wch:14},{wch:13},{wch:13},{wch:13},{wch:14},{wch:9},{wch:9},{wch:20},{wch:14},{wch:8}];
  XLSX.utils.book_append_sheet(wb,ws,"ICHC");
  XLSX.writeFile(wb,`ICHC_${label}.xlsx`);
}

// ─── Export Excel Mantenimiento ───────────────────────────────────────────────
function generarExcelMantenimiento(rows, usdRate, label){
  const wb=XLSX.utils.book_new();
  const data=[["Fecha","Máquina","Proyecto","Tipo","Intervención","Operativo","Costo ARS","Costo USD"]];
  rows.forEach(r=>data.push([
    r.fecha,r.maquina,r.proyecto,r.tipoMant,r.intervencion,r.operativo?"SÍ":"NO",
    r.costoTotal>0?r.costoTotal:0,
    r.costoTotal>0&&usdRate?Math.round(r.costoTotal/usdRate):0,
  ]));
  const ws=XLSX.utils.aoa_to_sheet(data);
  ws["!cols"]=[{wch:12},{wch:12},{wch:14},{wch:13},{wch:40},{wch:10},{wch:14},{wch:12}];
  XLSX.utils.book_append_sheet(wb,ws,"Mantenimiento");
  XLSX.writeFile(wb,`Mantenimiento_${label}.xlsx`);
}

// ─── ViewRankingOperarios ─────────────────────────────────────────────────────
function ViewRankingOperarios({rop02All,rop05}){
  const rop02Prod=useMemo(()=>rop02All.filter(r=>!isExcluded(r.maquina)&&r.estado==="TRABAJO"),[rop02All]);
  const[proyecto,setProyecto]=useState("todos");
  const[modeR,setModeR]=useState("periodo");
  const[fecha,setFecha]=useState("");
  const[fechaD,setFechaD]=useState("");
  const[fechaH,setFechaH]=useState("");
  const proyectos=useMemo(()=>uniq(rop02Prod.map(r=>r.proyecto)),[rop02Prod]);

  const filtered=useMemo(()=>rop02Prod.filter(r=>{
    if(proyecto!=="todos"&&r.proyecto!==proyecto)return false;
    if(modeR==="dia"){if(fecha&&r.fecha!==fecha)return false;}
    if(modeR==="periodo"){if(fechaD&&r.fecha<fechaD)return false;if(fechaH&&r.fecha>fechaH)return false;}
    return true;
  }),[rop02Prod,proyecto,modeR,fecha,fechaD,fechaH]);

  const hayFiltros=proyecto!=="todos"||(modeR==="dia"&&!!fecha)||(modeR==="periodo"&&(!!fechaD||!!fechaH));
  const reset=()=>{setModeR("periodo");setProyecto("todos");setFecha("");setFechaD("");setFechaH("");};

  const ranking=useMemo(()=>{
    const m={};
    filtered.forEach(r=>{
      if(!r.operario)return;
      if(!m[r.operario])m[r.operario]={operario:r.operario,horas:0,proyectos:new Set(),maquinas:new Set(),dias:new Set()};
      m[r.operario].horas+=r.horas;
      if(r.proyecto)m[r.operario].proyectos.add(r.proyecto);
      if(r.maquina)m[r.operario].maquinas.add(r.maquina);
      if(r.fecha)m[r.operario].dias.add(r.fecha);
    });
    return Object.values(m).map(op=>({
      ...op,
      proyectos:[...op.proyectos].join(" / "),
      maquinas:[...op.maquinas].sort().join(", "),
      diasTrabajados:op.dias.size,
      promHsDia:op.dias.size>0?Math.round((op.horas/op.dias.size)*10)/10:0,
    })).sort((a,b)=>b.horas-a.horas);
  },[filtered]);

  const maxHoras=ranking[0]?.horas||1;

  const cols=[
    {key:"operario",label:"Operario"},
    {key:"horas",label:"Horas",render:v=><span style={{color:C.accent,fontWeight:700}}>{fmtNum(v)}</span>},
    {key:"diasTrabajados",label:"Días",render:v=><span style={{color:C.blue,fontWeight:600}}>{v}</span>},
    {key:"promHsDia",label:"Hs/Día",render:v=><span style={{color:C.teal,fontWeight:600}}>{fmtNum(v)}</span>},
    {key:"proyectos",label:"Proyecto",render:v=><Badge color={v?.includes("FILO")?C.accent:v?.includes("JOSE")?C.teal:C.textSub}>{v||"—"}</Badge>},
    {key:"maquinas",label:"Máquinas operadas",wrap:true},
  ];

  return(
    <div className="fade-in" style={{display:"flex",flexDirection:"column",gap:14}}>
      <Card>
        <div style={{padding:"12px 14px",display:"flex",flexDirection:"column",gap:10}}>
          {/* Fila 1: tabs */}
          <div style={{display:"flex",gap:7,alignItems:"center",flexWrap:"wrap"}}>
            <TabBtn active={modeR==="dia"} onClick={()=>setModeR("dia")}>Por día</TabBtn>
            <TabBtn active={modeR==="periodo"} onClick={()=>setModeR("periodo")}>Por período</TabBtn>
          </div>
          {/* Fila 2: filtros */}
          <div style={{display:"flex",flexWrap:"wrap",gap:10,alignItems:"flex-end"}}>
            {modeR==="dia"&&<DateIn label="Fecha" value={fecha} onChange={setFecha}/>}
            {modeR==="periodo"&&<><DateIn label="Desde" value={fechaD} onChange={setFechaD} max={fechaH||undefined}/><DateIn label="Hasta" value={fechaH} onChange={setFechaH} min={fechaD||undefined} warn={fechaH&&fechaD&&fechaH<fechaD?"≥ Desde":null}/></>}
            <Sel label="Proyecto" value={proyecto} onChange={setProyecto} options={[{value:"todos",label:"Todos"},...proyectos.map(p=>({value:p,label:p}))]}/>
            <button onClick={reset} style={{marginLeft:"auto",display:"flex",alignItems:"center",gap:5,padding:"6px 12px",borderRadius:7,border:`1px solid ${C.red}44`,background:C.redDim,color:C.red,cursor:"pointer",fontSize:11,fontWeight:600,fontFamily:"Inter",opacity:hayFiltros?1:0.3,pointerEvents:hayFiltros?"auto":"none"}}><Icon name="close" size={11} color={C.red}/>Limpiar filtros</button>
          </div>
        </div>
      </Card>
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(120px,1fr))",gap:10}}>
        <StatCard icon="consist" label="Operarios" value={ranking.length} color={C.purple} small/>
        <StatCard icon="hours" label="Horas totales" value={fmtNum(ranking.reduce((s,r)=>s+r.horas,0))} color={C.accent} small/>
        <StatCard icon="equip" label="Equipos distintos" value={new Set(filtered.map(r=>r.maquina)).size} color={C.teal} small/>
      </div>
      {ranking.length>0&&(
        <Card title="Top 15 Operarios — Horas trabajadas">
          <div style={{padding:"12px 16px",display:"flex",flexDirection:"column",gap:8}}>
            {ranking.slice(0,15).map((op,i)=>{
              const pct=maxHoras>0?(op.horas/maxHoras)*100:0;
              const sem=semaforo(Math.min(100,op.promHsDia/12*100));
              return(
                <div key={i} style={{display:"flex",flexDirection:"column",gap:3}}>
                  <div style={{display:"flex",alignItems:"center",gap:8}}>
                    <span style={{fontSize:11,fontWeight:800,color:C.accent,width:20,textAlign:"right",flexShrink:0,fontFamily:"Inter"}}>{i+1}</span>
                    <span style={{fontSize:12,color:C.text,flex:1,fontWeight:600}}>{op.operario}</span>
                    <span style={{fontSize:11,color:C.textSub,flexShrink:0}}>{op.proyectos}</span>
                    <span style={{fontSize:12,fontWeight:700,color:C.accent,flexShrink:0,minWidth:50,textAlign:"right"}}>{fmtNum(op.horas)} hs</span>
                    <span style={{fontSize:10,color:sem.color,flexShrink:0,minWidth:60,textAlign:"right"}}>{fmtNum(op.promHsDia)} hs/día</span>
                  </div>
                  <div style={{marginLeft:28,background:C.border,borderRadius:3,height:5,overflow:"hidden"}}>
                    <div style={{width:`${pct}%`,height:"100%",background:C.accent,borderRadius:3,transition:"width .4s ease"}}/>
                  </div>
                </div>
              );
            })}
          </div>
        </Card>
      )}
      <Card title={`Tabla completa (${ranking.length} operarios)`}>
        <Table cols={cols} rows={ranking} maxH={450} emptyMsg="Sin datos con los filtros seleccionados"/>
      </Card>
    </div>
  );
}

export default function App(){
  const[auth,setAuth]=useState(()=>sessionStorage.getItem("dm_auth")==="1");
  const[view,setView]=useState("dashboard");
  const[loading,setLoading]=useState(false);
  const[rop02All,setRop02All]=useState([]);
  const[rop05,setRop05]=useState([]);
  const[lastUpdate,setLastUpdate]=useState(null);
  const[sidebarOpen,setSidebarOpen]=useState(true);
  const[errors,setErrors]=useState([]);
  const[fatalError,setFatalError]=useState(null);
  const control=useMemo(()=>calcControl(rop02All,rop05),[rop02All,rop05]);
  // Estados persistentes de filtros por pestaña
  const[dashSt,setDashSt]=useState({proyecto:"todos",modeD:"todo",fechaD:"",fechaDD:"",fechaDH:""});
  const[rma15,setRma15]=useState([]);
  const[stMant,setStMant]=useState({modo:"dia",proyecto:"todos",tipoMant:"todos",maquina:"todas",fechaD:"",fechaH:"",fechaDia:"",filtroCosto:"total",insumoFiltro:""});
  const[usdRate,setUsdRate]=useState(null);

  // Obtener tipo de cambio ARS→USD al cargar
  useEffect(()=>{
    fetch("https://api.exchangerate-api.com/v4/latest/USD")
      .then(r=>r.json())
      .then(d=>{if(d.rates?.ARS)setUsdRate(d.rates.ARS);})
      .catch(()=>{
        // Fallback: dolar blue via otra API
        fetch("https://dolarapi.com/v1/dolares/blue")
          .then(r=>r.json())
          .then(d=>{if(d.venta)setUsdRate(d.venta);})
          .catch(()=>setUsdRate(1300));
      });
  },[]);
  const[insumos,setInsumos]=useState({});
  const[st02,setSt02]=useState({mode:"dia",fecha:"",fechaD:"",fechaH:"",vals:{proyecto:"todos",maquina:"todas",supervisor:"todos",operario:"todos"}});
  const[stVeh,setStVeh]=useState({mode:"dia",fecha:"",fechaD:"",fechaH:"",vals:{proyecto:"todos",maquina:"todas",supervisor:"todos",operario:"todos"}});
  const[st05,setSt05]=useState({mode:"dia",fecha:"",fechaD:"",fechaH:"",vals:{proyecto:"todos",maquina:"todas",supervisor:"todos",unidad:"todas"}});
  const[stCtrl,setStCtrl]=useState({mode:"dia",fecha:"",fechaD:"",fechaH:"",vals:{proyecto:"todos",maquina:"todas",supervisor:"todos"}});



  const loadData=useCallback(async()=>{
    setLoading(true);setErrors([]);setFatalError(null);
    try{
      const json=await fetchAll(APPS_SCRIPT_URL);
      const src=json.sources||{};const errs=[];
      if(src.rop05?.ok&&src.rop05.data){const rop05Raw=normalizeROP05(src.rop05.data);
      // Build tarea map first with raw data, THEN normalize
      const allTareasEarly=rop05Raw.map(r=>r.tarea).filter(Boolean);
      buildTareaMap(allTareasEarly);
      const rop05Norm=rop05Raw.map(r=>({...r,tarea:normTarea(r.tarea)}));
      setRop05(rop05Norm);}
      else if(src.rop05&&!src.rop05.ok){errs.push({source:"ROP05",...src.rop05.error});setRop05([]);}
      const rFS=src.rop02_fs?.ok&&src.rop02_fs.data?normalizeROP02(src.rop02_fs.data,"FILO DEL SOL"):[];
      if(src.rop02_fs&&!src.rop02_fs.ok)errs.push({source:"ROP02 — Filo del Sol",...src.rop02_fs.error});
      const rJM=src.rop02_jm?.ok&&src.rop02_jm.data?normalizeROP02(src.rop02_jm.data,"JOSE MARIA"):[];
      if(src.rop02_jm&&!src.rop02_jm.ok)errs.push({source:"ROP02 — José María",...src.rop02_jm.error});
      // Construir mapa canónico con TODOS los nombres antes de setear estado
      const allRop02=[...rFS,...rJM];
      const allRop05Names=src.rop05?.ok&&src.rop05.data?normalizeROP05(src.rop05.data).map(r=>r.supervisor):[];
      const allNames=[
        ...allRop02.map(r=>r.supervisor),
        ...allRop02.map(r=>r.operario),
        ...allRop05Names,
      ].filter(Boolean);
      buildCanonicalMap(allNames);
      // Construir mapa canónico de tareas (ROP05)
      const allTareas=(src.rop05?.ok&&src.rop05.data?normalizeROP05(src.rop05.data).map(r=>r.tarea):[]).filter(Boolean);
      buildTareaMap(allTareas);
      // Re-normalizar con el mapa ya construido
      const allRop02Norm=allRop02.map(r=>({...r,supervisor:normName(r.supervisor),operario:normName(r.operario)}));
      // ── RMA15 Mantenimiento ──────────────────────────────────────────────
      const rmaFS=src.rma15_fs?.ok&&src.rma15_fs.data?src.rma15_fs.data:[];
      const rmaJM=src.rma15_jm?.ok&&src.rma15_jm.data?src.rma15_jm.data:[];
      if(src.rma15_fs&&!src.rma15_fs.ok)errs.push({source:"RMA15 — Filo del Sol",...src.rma15_fs.error});
      if(src.rma15_jm&&!src.rma15_jm.ok)errs.push({source:"RMA15 — José María",...src.rma15_jm.error});
      // ── Insumos base de datos ─────────────────────────────────────────────
      const insumosMap={};
      if(src.insumos?.ok&&src.insumos.data){
        src.insumos.data.forEach(r=>{
          const cod=String(r["CODIGO"]||r["Codigo"]||r["código"]||"").trim();
          if(cod)insumosMap[cod]={
            descripcion:String(r["DESCRIPCIÓN"]||r["DESCRIPCION"]||r["Descripción"]||"").trim(),
            costoUnitario:parseFloat(String(r["COSTO UNITARIO"]||r["Costo Unitario"]||"0").replace(/[^0-9.]/g,""))||0,
          };
        });
      }
      setInsumos(insumosMap);
      const allRma=[
        ...rmaFS.map(r=>normalizeRMA15({...r,_proyectoForzado:"FILO DEL SOL"},insumosMap)),
        ...rmaJM.map(r=>normalizeRMA15({...r,_proyectoForzado:"JOSE MARIA"},insumosMap)),
      ];
      setRma15(allRma);
      setRop02All(allRop02Norm);setErrors(errs);setLastUpdate(new Date());
    }catch(err){setFatalError(err.message);}
    finally{setLoading(false);}
  },[]);

  useEffect(()=>{loadData();},[loadData]);

  const navItems=[
    {id:"dashboard",icon:"dashboard",label:"Dashboard"},
    {id:"_rop02",icon:"parts",label:"ROP02",isGroup:true},
    {id:"rop02",icon:"parts",label:"Equipos",indent:true},
    {id:"vehiculos",icon:"equip",label:"Vehículos",indent:true},
    {id:"_rop05",icon:"prod",label:"ROP05",isGroup:true},
    {id:"rop05",icon:"prod",label:"Productividad",indent:true},
    {id:"ranking",icon:"person",label:"Ranking Operarios",indent:true},
    {id:"_rma15",icon:"equip",label:"RMA15",isGroup:true},
    {id:"mant",icon:"gear",label:"Mantenimiento",indent:true},
    {id:"chc",icon:"consist",label:"ICHC"},
    {id:"control",icon:"control",label:"Control ROP05 vs ROP02",badge:control.problemas>0?control.problemas:null},
  ];
  const titles={dashboard:"Dashboard",rop02:"Equipos",vehiculos:"Vehículos y Camionetas",rop05:"Productividad",ranking:"Ranking de Operarios",chc:"ICHC — Indicador Control de Horas Contratadas",mant:"Mantenimiento",control:"Consistencia ROP02 vs ROP05"};
  const SW=sidebarOpen?240:52;

  if(!auth)return<Login onLogin={()=>{sessionStorage.setItem("dm_auth","1");setAuth(true);}}/>;
  return(
    <>
      <style>{STYLES}</style>
      <div style={{display:"flex",height:"100vh",overflow:"hidden",background:C.bg}}>
        <div style={{width:SW,flexShrink:0,background:C.surface,borderRight:`1px solid ${C.border}`,display:"flex",flexDirection:"column",transition:"width .22s ease",overflow:"hidden"}}>
          <div style={{padding:sidebarOpen?"18px 16px 14px":"18px 0 14px",borderBottom:`1px solid ${C.border}`,display:"flex",alignItems:"center",gap:8,justifyContent:sidebarOpen?"space-between":"center"}}>
            {sidebarOpen&&(<div style={{display:"flex",alignItems:"center",gap:6}}><img src={LOGO} alt="Delta Mining" style={{height:58,display:"block",padding:"4px 6px",background:C.surface}}/><div style={{display:"flex",flexDirection:"column",lineHeight:1.1}}><span style={{fontFamily:"Inter",fontWeight:800,fontSize:16,color:C.accent}}>DELTA MINING</span><span style={{fontFamily:"Inter",fontWeight:700,fontSize:16,color:C.accent}}>APP</span></div></div>)}
            <button onClick={()=>setSidebarOpen(o=>!o)} style={{background:"none",border:"none",cursor:"pointer",color:C.textMuted,padding:3,display:"flex",alignItems:"center",flexShrink:0}}>
              <Icon name={sidebarOpen?"close":"menu"} size={17}/>
            </button>
          </div>
          <nav style={{flex:1,padding:"8px 0"}}>
            {navItems.map(item=>{
              if(item.isGroup)return(
                <div key={item.id} style={{padding:sidebarOpen?"8px 14px 2px":"8px 0 2px",fontSize:9,fontWeight:700,color:C.textMuted,letterSpacing:".1em",textTransform:"uppercase",userSelect:"none",textAlign:sidebarOpen?"left":"center"}}>{sidebarOpen?item.label:"···"}</div>
              );
              const active=view===item.id;
              return(
                <button key={item.id} onClick={()=>setView(item.id)}
                  title={!sidebarOpen?item.label:undefined}
                  style={{width:"100%",background:active?C.accentDim:"none",border:"none",borderLeft:`2px solid ${active?C.accent:"transparent"}`,padding:sidebarOpen?`10px 14px 10px ${item.indent?"28px":"14px"}`:"10px 0",display:"flex",alignItems:"center",gap:9,justifyContent:sidebarOpen?"flex-start":"center",cursor:"pointer",transition:"all .15s"}}>
                  <Icon name={item.icon} size={item.indent?14:17} color={active?C.accent:item.indent?C.textMuted+"bb":C.textMuted}/>
                  {sidebarOpen&&(<><span style={{fontSize:item.indent?11:12,fontWeight:500,color:active?C.accent:C.textSub,flex:1,textAlign:"left"}}>{item.label}</span>{item.badge&&<span style={{background:C.red,color:"#fff",borderRadius:9,fontSize:9,fontWeight:700,padding:"1px 5px"}}>{item.badge}</span>}</>)}
                </button>
              );
            })}
          </nav>
        </div>
        <div style={{flex:1,display:"flex",flexDirection:"column",overflow:"hidden"}}>
          <div style={{height:50,flexShrink:0,background:C.surface,borderBottom:`1px solid ${C.border}`,display:"flex",alignItems:"center",justifyContent:"space-between",padding:"0 18px"}}>
            <h1 style={{fontFamily:"Inter",fontWeight:700,fontSize:14,color:C.text}}>{titles[view]}</h1>
            <div style={{display:"flex",alignItems:"center",gap:12}}>
              {lastUpdate&&<span style={{fontSize:10,color:C.textMuted}}>Actualizado: {lastUpdate.toLocaleTimeString("es-AR")}</span>}
              <button onClick={loadData} disabled={loading} style={{display:"flex",alignItems:"center",gap:5,background:C.accentDim,border:`1px solid ${C.accent}44`,borderRadius:7,padding:"6px 12px",cursor:loading?"not-allowed":"pointer",color:C.accent,fontSize:12,fontWeight:600,fontFamily:"Inter"}}>
                {loading?<Spinner size={12}/>:<Icon name="refresh" size={13} color={C.accent}/>}
                {loading?"Cargando...":"Actualizar"}
              </button>
            </div>
          </div>
          <div style={{flex:1,overflow:"auto",padding:16}}>
            {errors.length>0&&!fatalError&&(
              <div style={{display:"flex",flexDirection:"column",gap:6,marginBottom:14}}>
                {errors.map((e,i)=>(
                  <div key={i} style={{display:"flex",alignItems:"flex-start",gap:8,padding:"9px 12px",background:C.yellowDim,border:`1px solid ${C.yellow}44`,borderRadius:8,fontSize:12}}>
                    <Icon name="warn" size={13} color={C.yellow} style={{flexShrink:0,marginTop:1}}/>
                    <span><strong style={{color:C.yellow}}>{e.source}: </strong><span style={{color:C.textSub}}>{e.message}</span></span>
                  </div>
                ))}
              </div>
            )}
            {fatalError&&<ErrorScreen errors={[{source:"Apps Script",message:fatalError}]} onRetry={loadData}/>}
            {loading&&!lastUpdate&&!fatalError&&(
              <div style={{display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",height:"60vh",gap:14}}>
                <Spinner size={36}/>
                <div style={{color:C.textMuted,fontSize:13}}>Cargando datos desde Google Sheets...</div>
                <div style={{fontFamily:"monospace",fontSize:10,color:C.borderLight}}>{APPS_SCRIPT_URL.slice(0,60)}...</div>
              </div>
            )}
            {!fatalError&&lastUpdate&&(
              <>
                {view==="dashboard"&&<ViewDashboard rop02All={rop02All} rop05={rop05} control={control} dashSt={dashSt} setDashSt={setDashSt}/>}
                {view==="rop02"&&<ViewROP02 rop02All={rop02All} extState={st02} setExtState={setSt02}/>}
                {view==="vehiculos"&&<ViewVehiculos rop02All={rop02All} extState={stVeh} setExtState={setStVeh}/>}
                {view==="rop05"&&<ViewROP05 rop05={rop05} extState={st05} setExtState={setSt05}/>}
                {view==="ranking"&&<ViewRankingOperarios rop02All={rop02All} rop05={rop05}/>}
                {view==="mant"&&<ViewMantenimiento rma15={rma15} usdRate={usdRate} extState={stMant} setExtState={setStMant}/>}
                {view==="chc"&&<ViewCHC rop02All={rop02All}/>}
                {view==="control"&&<ViewControl control={control} rop02All={rop02All} rop05={rop05} extState={stCtrl} setExtState={setStCtrl}/>}
              </>
            )}
          </div>
        </div>
      </div>
    </>
  );
}
